OVERRIDES = {
    "tip.json": {
        "TIP142_ja.cfg.bin#3": "레벨 식스에서 막 발매한 신감각\\n입체 연애 시뮬레이션 게임. 총감독은 이시이 고로. 고글을 쓰고 플레이하면 사회 복귀가 불가능해질 정도의 몰입감이 있다. 『러브맥스와 PC방만 있으면 살 수 있다』고 호언장담하는 사람이 속출 중이다.",
        "TIP174_ja.cfg.bin#3": "\ud3ed\ub825\ub2e8 \ub300\ucc45\uc744 \ub2f4\ub2f9\ud558\ub294 \uacbd\ucc30 \ub0b4\ubd80 \uc870\uc9c1\uc774\ub098 \ud615\uc0ac\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc0ac\uc640\ud0a4\uac00 \ub9c8\ub8e8\ubcf4\uc5d0 \uc788\ub358 \uc2dc\uc808\uc5d0\ub294 \u300e\ubbf8\uce5c \ub291\ub300\u300f\ub77c \ubd88\ub9ac\uba70 \ud3ed\ub825\ub2e8\uc5d0\uac8c \ub450\ub824\uc6c0\uc758 \ub300\uc0c1\uc774\uc5c8\ub2e4. \ub108\ubb34 \uacfc\uaca9\ud55c \uc218\uc0ac \ubc29\uc2dd\uc744 \ud0dd\ud588\uae30 \ub54c\ubb38\uc5d0 \uacbd\ucc30 \ub0b4\ubd80\uc5d0\uc11c\ub3c4 \u300e\uc5b4\ub290 \ucabd\uc774 \ud3ed\ub825\ub2e8\uc778\uc9c0 \ubaa8\ub974\uaca0\ub2e4\u300f\ub294 \ub9d0\uc744 \ub4e4\uc744 \uc815\ub3c4\uc600\ub2e4.",
        "TIP175_ja.cfg.bin#3": "\uc0c9\uae30 \uc5b4\ub9b0 \uc2dc\uc120\uc774\ub098 \uc721\uccb4\uc5d0\uc11c \ubd84\ube44\ub418\ub294 \ud398\ub85c\ubaac\uc744 \ube54\ucc98\ub7fc \uc3d8\uc544 \ub0b4\ub294 \ud589\uc704\ub97c \ub9d0\ud55c\ub2e4. \ub9de\uc740 \ub0a8\uc131\uc774 \ub10b\uc744 \uc783\uc744\uc9c0\ub294 \uc3dc \uc0ac\ub78c\uc758 \ub9e4\ub825\uc5d0 \ub2ec\ub838\ub2e4. \ub2e8\uc5b4\ub85c\uc11c\ub294 2000\ub144\ub300\uc5d0 \ubaa8\ub2dd\uad6c\ubb34\uc2a4\uba54.\uc758 \uac00\uc0ac\uc5d0 \ub4f1\uc7a5\ud574 \uc77c\ubc18\uc5d0 \ud37c\uc84c\uc9c0\ub9cc, 2031\ub144 \ud604\uc7ac\ub294 \uc774\ubbf8 \uc0ac\uc5b4\uac00 \ub41c \uc9c0 \uc624\ub798\ub2e4.",
        "TIP176_ja.cfg.bin#3": "\uc288\uc774\uce58\ub85c\uc758 \uc544\ubc84\uc9c0\ub294 \ub300\ud615 \uac00\uc804 \uc81c\uc870\uc0ac\uc5d0 \ub2e4\ub154\ub2e4. \ud558\uc9c0\ub9cc \uc7a5\uae30\ud654\ub41c \ubd88\ud669\uc758 \uc601\ud5a5\uc73c\ub85c \uc2e4\uc801\uc774 \uc545\ud654\ub418\uc5b4 \ub3c4\uc0b0\ud588\uace0 \uc288\uc774\uce58\ub85c\uc758 \uc544\ubc84\uc9c0\ub3c4 \uc9c1\uc7a5\uc744 \uc783\uac8c \ub418\uc5c8\ub2e4.",
        "TIP177_ja.cfg.bin#3": ":texture=#/tip/tip1760.xa:pos=32,40:\uc720\ub7fd \uc6d0\uc790\ud575 \uc5f0\uad6c \uae30\uad6c\ub97c \ub9d0\ud55c\ub2e4. \uc138\uacc4 \ucd5c\ub300\uae09\uc758 \uc18c\ub9bd\uc790 \ubb3c\ub9ac\ud559\\n\uc5f0\uad6c \uae30\uad00\uc774\uba70, \uc138\uacc4 \ucd5c\ub300\uc758 \ucda9\ub3cc\ud615 \uc6d0\ud615 \uac00\uc18d\uae30\uc778 LHC(\ub300\ud615 \ud558\ub4dc\ub860 \ucda9\ub3cc\ud615 \uac00\uc18d\uae30)\ub97c \uc6b4\uc6a9\ud558\uace0 \uc788\ub2e4.",
        "TIP178_ja.cfg.bin#3": "\uba85\ud655\ud55c \uc815\uc758\ub294 \uc5c6\uc9c0\ub9cc \uc5b4\ub5a4 \uc774\uc720\ub85c \uacfc\uac70\ub098 \ubbf8\ub798\ub85c \ub3c4\uc57d\ud558\ub294 \ud604\uc0c1\uc744 \ub9d0\ud55c\ub2e4.",
        "TIP179_ja.cfg.bin#3": "\ucc9c\uccb4\ubb3c\ub9ac\ud559 \ub4f1\uc5d0\uc11c\ub294 \ud604\uc7ac \uc774\ub860\uc73c\ub85c \uc608\uce21\ub418\ub294 \uc218\uce58\uc640 \uc2e4\uc81c\ub85c \uad00\uce21\ub41c \uc911\ub825 \uc218\uce58\uc5d0 \ucc28\uc774\uac00 \ub098\ud0c0\ub098\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4. \uc774 \uc138\uacc4\uc758 2013\ub144 4\uc6d4 28\uc77c\uc5d0\ub294 \uc804 \uc138\uacc4\uc5d0\uc11c \uc911\ub825\ud30c\ub97c \uce21\uc815\ud558\ub358 \uc5f0\uad6c \uae30\uad00\ub4e4\uc774 \uc774\uc0c1\ud55c \uc218\uce58\ub97c \uac80\ucd9c\ud588\uc9c0\ub9cc, \uadf8 \uc6d0\uc778\uc740 \ubd88\uba85\uc73c\ub85c \ucc98\ub9ac\ub418\uc5c8\ub2e4.",
        "TIP180_ja.cfg.bin#3": ":model=#/tip/tip1130.xc:pos=50,80:\ub538\uae30\uac00 \uc62c\ub77c\uac04 \uc77c\ubcf8\uc5d0\uc11c \uac00\uc7a5 \ub300\uc911\uc801\uc778 \ucf00\uc774\ud06c. \ud30c\uc774\ube0c \ub808\ubca8\ub978\uc758 \uc1fc\ud2b8\ucf00\uc774\ud06c\ub97c \uac10\uc218\ud55c \ud30c\ud2f0\uc2dc\uc5d0\u30fb\uc2dc\ub77c\ud1a0 \uc138\uc774\uc9c0\ub294 \ud504\ub791\uc2a4 \ucf69\ucfe0\ub974\uc5d0\uc11c \uc6b0\uc2b9\ud55c \uacbd\ud5d8\ub3c4 \uc788\ub294 \uc77c\ub958 \uc7a5\uc778\uc774\ub2e4.",
        "TIP181_ja.cfg.bin#3": ":model=#/tip/tip1140.xc:pos=50,80:\ucd08\ucf5c\ub9bf \ucf00\uc774\ud06c. \ud30c\uc774\ube0c\\n\ub808\ubca8\ub978\uc758 \u300e\uc309\uc300\ud55c \uc5b4\ub978\uc758 \uc1fc\ucf5c\ub77c \ucf00\uc774\ud06c\u300f\ub294 \uce74\uce74\uc624 \ube44\uc728 85\ud37c\uc13c\ud2b8\uc758 \ube44\ud130 \ucd08\ucf5c\ub9bf\uc744 \uc0ac\uc6a9\ud574 \uc0b4\uc9dd \uc4f4\ub9db\uc774 \ub098\ub3c4\ub85d \uc644\uc131\ud588\ub2e4.",
        "TIP182_ja.cfg.bin#3": ":model=#/tip/tip1150.xc:pos=50,80:\ube44\ub2e8 \uac19\uc740 \uc2dd\uac10\uc5d0\uc11c \uc774\ub984 \ubd99\uc740 \ucf00\uc774\ud06c\uc758 \uc77c\uc885. \u300e\ucac0\ub4dd\ud55c \ubc18\uc8fd\uc744 \uace0\uc9d1\ud55c\\n\uc2dc\ud3f0 \ucf00\uc774\ud06c\u300f\ub294 \uac00\ubcbc\uc6c0\uc774 \uc7a5\uc810\uc778 \uc2dc\ud3f0 \ucf00\uc774\ud06c\uc5d0 \uc815\ubc18\ub300\uc758 \ubc1c\uc0c1\uc744 \ub3c4\uc785\ud55c \ud654\uc81c\uc758 \ub514\uc800\ud2b8\ub2e4.",
        "TIP183_ja.cfg.bin#3": "\u300eNHK \ud64d\ubc31\uac00\ud569\uc804\u300f\uc744 \ub9d0\ud55c\ub2e4. \ub9e4\ub144 12\uc6d4 31\uc77c \ubc24\uc5d0 \uc0dd\ubc29\uc1a1\ub418\ub294 \ub178\ub798 \ud504\ub85c\uadf8\ub7a8\uc774\ub2e4. \uc62c\ud574\ubd80\ud130 \ud68c\uc7a5\uc774 \ub124\uc624 NHK \ud640\ub85c \uc62e\uaca8 \uac04\ub2e4. \uc123\ub2ec\uadf8\ubbd0\uc5d0\ub294 \ub3c4\uc2dc\ucf54\uc2dc \uc18c\ubc14\ub97c \uba39\uc73c\uba70 \ud64d\ubc31\uc744 \ubcf4\ub294 \uac83\uc774 \uc77c\ubcf8 \uac70\uc2e4\uc758 \ubaa8\uc2b5\uc774\uba70, \ud64d\ubc31 \ubb34\ub300\ub294 \ub9ce\uc740 \uac00\uc218\uc5d0\uac8c \ub3d9\uacbd\uc758 \uc7a5\uc18c\ub2e4.",
        "TIP184_ja.cfg.bin#3": "\uc790\uac01 \uc5c6\ub294 \uc5ec\uc131\uc5d0\uac8c\ub294 \uc808\ub300 \ub9d0\ud574\uc11c\ub294 \uc548 \ub418\ub294 \ub9d0. \ubbf8\ud63c\uc778 \uacbd\uc6b0\uc5d0\ub294 \ud2b9\ud788 \uc8fc\uc758\uac00 \ud544\uc694\ud558\ub2e4. \ud615\uc81c\uc790\ub9e4\uc5d0\uac8c \uc544\uc774\uac00 \ud0dc\uc5b4\ub098 \uad00\uacc4\uc0c1 \u300e\uc544\uc8fc\uba38\ub2c8\u300f\uac00 \ub418\uc5b4\ub3c4, \uc870\uce74\uc5d0\uac8c\ub294 \ub2e8\ud638\ud558\uac8c \u300e\uc5b8\ub2c8\u300f\ub77c\uace0 \ubd80\ub974\uac8c \ud558\ub294 \uac83\uc774 \uc5ec\uc131\uc774\ub77c\ub294 \uc874\uc7ac\ub2e4.",
        "TIP185_ja.cfg.bin#3": "\uc21c\ubc31\uc758 \ubc14\ub514\uc288\ud2b8\ub97c \uc785\uace0 \ubbf8\ub798\ub97c \uad6c\ud558\uae30 \uc704\ud574 \uc2f8\uc6b0\ub294 \uac00\ub828\ud55c \ud788\ub85c\uc778. \ucc98\uc74c \uadf8 \uc18c\ub140\ub97c \ub9cc\ub0ac\uc744 \ub54c, \ub8e8\uc0c1\uce58\u2606\ub9e8\uc740 \uadf8\ub140\uc758 \ub4f1\uc5d0 \uc788\ub294 \ucc9c\uc0ac \ub0a0\uac1c \ubaa8\ud2f0\ud504\ub97c \uc9c4\uc9dc\ub85c \ucc29\uac01\ud574 \ucc9c\uc0ac\ub77c\uace0 \ubbff\uc5c8\ub2e4.\u2026\u2026\ub77c\ub294 \ub9dd\uc0c1\uc744 \ud55c \ub8e8\uc0c1\uce58\u2606\ub9e8\uc774\uc5c8\ub2e4.",
        "TIP186_ja.cfg.bin#3": "\uc9e7\uc740 \uc5f0\uc608 \ud65c\ub3d9 \ud6c4 \uc740\ud1f4\ud55c \ud658\uc0c1\uc758 \uc544\uc774\ub3cc \uac00\uc218\u30fb\ud638\uc2dc\ub178 \ub098\uc988\\n\ub098\uc758 \ub370\ubdd4\uace1. 2022\ub144 \ubc1c\ud45c \ub2f9\uc2dc \uc6b0\uc8fc \uc5d8\ub9ac\ubca0\uc774\ud130 \uc774\ubbf8\uc9c0\uc1a1\uc73c\ub85c \uc4f0\uc600\uace0, CF\uc5d0\uc11c \ud750\ub974\ub294 \u300e\uc6b0\uc8fc\uc5d0\uc11c \uc719\uc719. \ub7ec\ube0c\ub294 \uc720\ub9ac\uc0c9\u300f\uc774\ub77c\ub294 \uad6c\uc808\uc774 \ubb18\ud558\uac8c \uadc0\uc5d0 \ub0a8\ub294\ub2e4\uace0 \ud654\uc81c\uac00 \ub410\ub2e4. \ub2f9\uc2dc \uc720\ud589\uc5b4 \ub300\uc0c1\uc5d0\ub3c4 \uc120\uc815\ub418\uc5c8\ub2e4.",
        "TIP187_ja.cfg.bin#3": "\uc2e0\ub3c4\uac00 \ucc98\uc74c \uc0ac\uae30\uafbc\uc774\ub77c \ubd88\ub9b0 \uac83\uc740 \uc18c\ub144 \uc2dc\uc808\uc774\ub2e4. \uc124\ub0a0\uc5d0 \uce5c\ucc99 \uadc0\uc5d0 \u300e\uc6b0\ub9ac \uc138\ubc43\ub3c8\uc740 \uc804\ubd80 \uc5c4\ub9c8\ud55c\ud14c \ube7c\uc557\uaca8\u300f\ub77c\uace0 \uc18d\uc0ad\uc600\ub2e4. \ubd88\uc30d\ud558\uac8c \uc5ec\uae34 \uce5c\ucc99\uc740 \ubab0\ub798 \uc138\ubc43\ub3c8\uc744 \ub354 \uc8fc\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc548 \uc5b4\uba38\ub2c8\ub294 \u300e\uc774 \uc0ac\uae30\uafbc \uc790\uc2dd!\u300f\uc774\ub77c\uba70 \uaca9\ub178\ud588\ub2e4.",
        "TIP188_ja.cfg.bin#3": "\uc77c\ubcf8 \uacbd\uc81c \ubc1c\uc804\uc744 \uc704\ud55c \uc81c\uc5b8\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \uc0ac\ub2e8\ubc95\uc778. \ub9ce\uc740 \ub300\uae30\uc5c5\uc774 \uac00\uc785\ud574 \uc788\uc73c\uba70 \uc7ac\uacc4\uc758 \ub300\ubcc0\uc790\ub85c\uc11c \uc815\uacc4\uc5d0\ub3c4 \ud070 \uc601\ud5a5\ub825\uc744 \uc9c0\ub2cc\ub2e4. \ud2b9\ud788 \uc624\uac00\ud0c0 \ucd1d\ub9ac\uc640\uc758 \uc720\ub300\uac00 \uac15\ud574 \u300e\uc2e0\uc5d0\ub108\uc9c0 \uad6d\uac00 \uad00\ub9ac\ubc95\u300f\uc5d0 \uad00\ud574 \uc218\ub9ce\uc740 \uc81c\uc5b8\uc744 \ud588\ub2e4.",
        "TIP189_ja.cfg.bin#3": "\uacbd\uc81c\ud1b5\uc0b0\uc131\uc758 \ub0b4\ubd80 \ubd80\uad6d \uc911 \ud558\ub098. \ud3ed\ub113\uac8c \uc0b0\uc5c5 \uc815\ucc45\uc744 \uad00\ud560\ud558\uba70, \uc774 \uc138\uacc4\uc5d0\uc11c\ub294 \uc790\uc6d0\uc5d0\ub108\uc9c0\uccad\uacfc \ud568\uaed8 \u300e\uc2e0\uc5d0\ub108\uc9c0 \uad6d\uac00 \uad00\ub9ac\ubc95\u300f \uc131\ub9bd\uc5d0 \uad00\uc5ec\ud558\uace0 \uc788\ub2e4. \uc2e0\uc5d0\ub108\uc9c0 \uc815\ucc45\uc744 \ubc30\uacbd\uc73c\ub85c \uacbd\uc81c \ud65c\ub825 \ud5a5\uc0c1\uc744 \uc704\ud55c \uacbd\uc81c \uad6c\uc870 \uac1c\ud601 \ucd94\uc9c4\uc744 \ub2f4\ub2f9\ud55c\ub2e4.",
        "TIP190_ja.cfg.bin#3": "\uacbd\ube44\ub780 \ud2b9\uc815 \uc2dc\uc124\uc744 \uac10\uc2dc\ud558\uace0 \uc9c0\ud0a4\ub294 \uc0ac\ub78c\uc744 \ub73b\ud558\uc9c0\ub9cc, \uc774 \uc138\uacc4\uc5d0\uc11c\ub294 \ub9ce\uc740 \ubd80\ubd84\uc774 \uc790\ub3d9\ud654\ub41c \uace0\ub3c4 \ubcf4\uc548 \uc2dc\uc2a4\ud15c\uc744 \ub9d0\ud55c\ub2e4. \ubcf4\uc548 \uac8c\uc774\ud2b8\uc640 \uac10\uc2dc \uce74\uba54\ub77c \ub4f1\uc73c\ub85c \uad6c\uc131\ub418\uc9c0\ub9cc \uc778\ud130\ub137\uc5d0 \uacb0\ud568\uc774\ub098 \ub300\ucc98\ubc95 \uc77c\ubd80\uac00 \uc720\ucd9c\ub418\uae30\ub3c4 \ud55c\ub2e4.",
        "TIP191_ja.cfg.bin#3": "\uc2e0\uc18c\uc7ac\uc758 \ubc1c\uba85\uc73c\ub85c \ube60\ub974\uac8c \uc9c4\ud589\ub420 \ub4ef\ud588\ub358 \uc6b0\uc8fc \uc5d8\ub9ac\\n\ubca0\uc774\ud130 \uac74\uc124\uc774\uc5c8\uc9c0\ub9cc, \uc2dc\ud5d8 \uc6b4\uc6a9\uc744 \uc2dc\uc791\ud55c 2020\\n\ub144 \ubb34\ub835\ubd80\ud130 \uac74\uc124 \uc791\uc5c5\uc6d0\uc758 \uc548\uc804 \ud655\ubcf4\ub97c \uace0\ub824\ud574 \uac74\uc124\uc740\\n\ub9e4\uc6b0 \ub290\ub9ac\uac8c \uc9c4\ud589\ub418\uc5c8\ub2e4. \ud604\uc7ac\ub294 \uc774\ubbf8 \uc804\uccb4 \ub192\uc774\\n\uc758 \uc57d 90%\uc5d0 \uc774\ub974\ub800\uc73c\uba70 \uc644\uacf5\uc740 2038\ub144\uc73c\ub85c \uc608\uc815\ub418\uc5b4 \uc788\ub2e4.",
        "TIP192_ja.cfg.bin#3": "\uc774\ud1a0\uc57c\ub9c8\ub294 \ub9d0\uc37d\uc744 \ubd80\ub9b0 \ud559\uc0dd\uc5d0\uac8c \uace7\uc798 \uc774 \ubc8c\uc744 \uc900\ub2e4. \ub9c8\uc0ac\ud1a0\uac00 \uc218\uc5c5 \uc911 \uc18c\ud615 \ub2e8\ub9d0\uae30\ub85c \ud504\ub85c\uadf8\ub798\ubc0d\uc744 \ud558\ub2e4 \ub4e4\ucf30\uc744 \ub54c\ub3c4 \uba85\ub839\ubc1b\uc558\ub2e4. \uae34 \ub9ac\ud3ec\ud2b8\ub97c \uc368 \ubcf8 \uc801 \uc5c6\ub294 \uace0\ub4f1\ud559\uc0dd\uc5d0\uac8c \ub9ac\ud3ec\ud2b8 \uc6a9\uc9c0 3\uc7a5 \ubd84\ub7c9\uc758 \uc791\ubb38\uc740 \uc4f0\uba74\uc11c \uaf64 \uad34\ub85c\uc6b4 \uc591\uc774\ub2e4.",
        "TIP193_ja.cfg.bin#3": "\ucde8\uc5c5 \ud76c\ub9dd\uc790\uac00 \uc2e4\uc81c\ub85c \ucde8\uc5c5\uc5d0 \uc774\ub978 \ube44\uc728\uc744 \ub098\ud0c0\ub0b4\ub294 \uc218\uce58. 2031\ub144 \uc77c\ubcf8\uc5d0\uc11c\ub294 \uc2e0\uc878\uc790\uc758 \ucde8\uc5c5\ub3c4 \ub9e4\uc6b0 \uc5b4\ub824\uc6cc \ub300\ud559 \uc878\uc5c5\uc790\uc758 \ub0b4\uc815\ub960\uc740 40%\ub300\uae4c\uc9c0 \ub5a8\uc5b4\uc84c\ub2e4. \uacbd\uae30\uac00 \uc870\uae08 \ud68c\ubcf5\ub418\uc5b4\ub3c4 \ucde8\uc5c5\ub960\uc774 \uc624\ub97c \uc9d5\ud6c4\ub294 \uc5c6\uc73c\uba70 \uc77c\ubd80\\n\uc804\ubb38\uac00\ub294 \uad6c\uc870\uc801\uc778 \ubb38\uc81c\ub77c\uace0 \uc9c0\uc801\ud55c\ub2e4.",
        "TIP194_ja.cfg.bin#3": "\ub178\ub3d9 \uc778\uad6c \uc911 \uc2e4\uc5c5\uc790\uc758 \ube44\uc728\uc744 \ub098\ud0c0\ub0b4\ub294 \uc218\uce58. 2031\ub144 \uc77c\ubcf8\uc5d0\uc11c\ub294 \ub0a8\ub140 \ud569\uacc4 \uc644\uc804 \uc2e4\uc5c5\ub960\uc774 9.83%\ub77c\ub294 \ub192\uc740 \uc218\uce58\ub97c \uae30\ub85d\ud558\uace0 \uc788\ub2e4. \uc774\ub7ec\ud55c \uc0c1\ud669\uc5d0\ub294 \ub2e4\uc591\ud55c \uc694\uc778\uc774 \uc5bd\ud600 \uc788\uc9c0\ub9cc \u300e\uc2e0\uc5d0\ub108\uc9c0 \uad6d\uac00 \uad00\ub9ac\ubc95\u300f\uc5d0 \ub530\ub978 \uc0b0\uc5c5 \uad6c\uc870\\n\uac1c\ud601\uc758 \uc2e4\ud328\uac00 \ud06c\uac8c \uc601\ud5a5\uc744 \ubbf8\uce58\uace0 \uc788\ub2e4.",
        "TIP195_ja.cfg.bin#3": "2031\ub144 \uc77c\ubcf8\uc5d0\uc11c\ub294 \uc2e4\uc5c5\uc790 \uc99d\uac00 \ub4f1\uc73c\ub85c \uc0ac\ud68c \ubcf4\uc7a5 \ubd80\ub2f4\uc774 \uc7ac\uc815\uc744 \ud06c\uac8c \uc555\ubc15\ud558\uace0 \uc788\ub2e4. \uad6d\ucc44 \ubc1c\ud589 \uc794\uc561\ub3c4 \ub9ce\uc544 \uc2e0\uc6a9 \ud558\ub77d\uc744 \uc6b0\ub824\ud55c \uc77c\ubcf8 \uc815\ubd80\ub294 \uc18c\ube44\uc138 \uc778\uc0c1\uc744 \uc787\ub2ec\uc544 \ub2e8\ud589\ud588\uace0 \ud604\uc7ac\ub294 23%\uc5d0 \uc774\ub974\ub7ec \uad6d\ubbfc \uc0dd\ud65c\uc744 \ud06c\uac8c \uc555\ubc15\ud558\uace0 \uc788\ub2e4.",
        "TIP196_ja.cfg.bin#3": "\u300e\uc774\ucf00\uba58\u300f\uc740 2000\ub144 \uc804\ud6c4\uc758 \uc80a\uc740\uc774 \ub9d0\uc5d0\uc11c \uc2dc\uc791\ub41c \uac83\uc73c\ub85c \uc5ec\uaca8\uc9c4\ub2e4. \uc989 \uc774\ubbf8 30\ub144 \uac00\uae4c\uc774 \uc0ac\uc6a9\ub418\uc5b4 \uc628 \ub9d0\uc774\ub2e4. \uc880\ucc98\ub7fc \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294 \uc720\ud589\uc5b4\uc758 \ub4dc\ubb38 \uc0ac\ub840\ub2e4.",
        "TIP197_ja.cfg.bin#3": "\uc815\ud655\ud788\ub294 \u300e\uc8fd\uc744 \uac01\uc624\ub85c \ub178\ub825\ud558\uba74 \ud504\ub85c\uac00 \ub420 \uc218 \uc788\uc5b4\uc694(\ub204\uad6c\ub098)\u300f\ub77c\ub294 \ub9d0\ub9cc \ub4e4\uc5c8\ub2e4.",
        "TIP198_ja.cfg.bin#3": "\uce58\ub9ac\ucf54\ub294 \uad6c\uc778 \uc7a1\uc9c0\uc758 \uc0c1\ud22c\uc801\uc778 \ubb38\uad6c\uc5d0 \uc790\uc8fc \uc18d\ub294\ub2e4. \u300e\ucd08\ubcf4\uc790\ub3c4 \ub300\ud658\uc601\u300f\uc774\ub77c\uace0 \uc4f0\ub294 \ud68c\uc0ac\ub294 \uc774\uc9c1\ub960\uc774 \ub108\ubb34 \ub192\uc544 \ucd08\ubcf4\uc790\ubc16\uc5d0 \uc5c6\ub2e4. \u300e\ud560\ub2f9\ub7c9 \uc5c6\uc74c\u300f\uc774\ub77c\uace0 \uc4f0\ub294 \ud68c\uc0ac\ub294 \ud560\ub2f9\ub7c9 \uc774\uc0c1\uc758 \ubaa9\ud45c\ub97c \uc790\ubc1c\uc801\uc73c\ub85c \ub5a0\ub9e1\uae34\ub2e4. \ucd5c\uadfc\uc5d0\uc57c \uce58\ub9ac\ucf54\ub3c4 \uc0ac\uc815\uc744 \uc54c\uac8c \ub418\uc5c8\ub2e4.",
        "TIP199_ja.cfg.bin#3": "\uc9c0\uae09 \ucd1d\uc561 16\ub9cc \uc5d4. \uac01\uc885 \ubcf4\ud5d8\ub8cc\uc640 \uc138\uae08\uc744 \ube7c\uba74 \uc2e4\uc218\ub839 14\ub9cc \uc5d4. \ud734\uc77c\uc774 \ub9ce\uc740 \ub2ec\uc5d0\ub294 12\ub9cc \uc5d4\uc744 \ubc11\ub3c4\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4.",
        "TIP200_ja.cfg.bin#3": ":model=#/tip/tip1900.xc:pos=50,50:\uc774\ub984 \uadf8\ub300\ub85c \uce74\ub4dc \ud615\ud0dc\uc758 \uc5f4\uc1e0. \uc885\ub958\ub294 \ub2e4\uc591\ud558\uc9c0\ub9cc \ub300\ud45c\uc801\uc778 \uac83\uc740 \uce74\ub4dc\uc5d0 \ub0b4\uc7a5\ub41c IC \uce69\uacfc \ubb38\uc758 \uc5f4\uc1e0 \uc7a5\uce58\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc544 \uc7a0\uae08\uc744 \ud574\uc81c\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uba87 \uac00\uc9c0 \uc6d0\ub9ac\ub97c \uc870\ud569\ud574 \ubcf4\uc548\uc744 \ub192\uc778 \ud558\uc774\ube0c\ub9ac\ub4dc\ud615\ub3c4 \uc788\ub2e4.",
    },
}

OVERRIDES["tip.json"].update({
    "TIP300_ja.cfg.bin#3": "\uc544\uc778\uc288\ud0c0\uc778\uacfc \ub124\uc774\uc120 \ub85c\uc98c\uc774 \uc218\ud559\uc801\uc73c\ub85c \ub3c4\ucd9c\ud55c, \ub4a4\ud2c0\ub9b0 \ub450 \uc2dc\uacf5\uac04\uc744 \uc787\ub294 \ubc8c\ub808 \uba39\uc740 \uad6c\uba4d \uac19\uc740 \uad6c\uc870\ub97c \ub9d0\ud55c\ub2e4. \uc874 \ud720\ub7ec\uc758 \uba85\uba85\uc5d0 \ub530\ub77c \u300e\uc6dc\ud640\u300f\uc774\ub77c\uace0\ub3c4 \ubd80\ub978\ub2e4.",
    "TIP301_ja.cfg.bin#3": "\uc6d0\ub798\ub294 \ud56d\uc131\uc774 \uc790\uc2e0\uc758 \uc911\ub825\uc744 \uacac\ub514\uc9c0 \ubabb\ud558\uace0 \ubd95\uad34\ud558\ub294 \ud604\uc0c1\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc5b4\ub5a4 \uc911\ub825 \uc774\uc0c1\uc744 \uc774\uc6a9\ud574 \ube14\ub799\ud640\uacfc \uac19\uc740 \uc601\uc5ed\uc744 \uc758\uc0ac\uc801\uc73c\ub85c \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \uac83\uc744 \ube44\uc720\uc801\uc73c\ub85c \ud45c\ud604\ud55c \uac83\uc73c\ub85c \ubcf4\uc778\ub2e4.",
    "TIP302_ja.cfg.bin#3": ":model=#/tip/tip2900.xc:pos=50,40:\uad50\ud1a0\uc5d0 \uc788\ub294 \uc804\ud1b5 \uc788\ub294 \ub3c4\ub77c\uc57c\ud0a4 \uac00\uac8c \u300e\ub3c4\ub77c\uc9f1\u300f\uc758 \uc0c1\ud488. \ubc18\uc8fd\uc5d0\ub294 \uad50\ud1a0\uc5d0\uc11c \ub09c \uc2e0\uc120\ud55c \ub2ec\uac40\uc744 \uc0ac\uc6a9\ud558\uace0, \uc0dd\ud06c\ub9bc\uc740 \uc720\uc9c0\ubc29 45%\uc778 \uac83\ub9cc \uc5c4\uc120\ud55c\ub2e4. \uc18d\uc740 \ud325\uc18c \uc678\uc5d0\ub3c4 \ub9d0\ucc28, \ub538\uae30, \ucd08\ucf5c\ub9bf \ub4f1 \ucd1d 20\uc885\ub958\ub098 \ub418\ub294 \ub2e4\uc591\ud55c \ub9db\uc774 \uc788\ub2e4.",
    "TIP303_ja.cfg.bin#3": "\uadf8\ub140\uc758 \uadc0\uac00 \uc870\uae08 \uc798\ub824 \uc788\ub294 \uac83\uc740 \uc950\uc5d0\uac8c \uac09\uc544 \uba39\ud614\uae30 \ub54c\ubb38\uc774\ub2e4.",
    "TIP304_ja.cfg.bin#3": "\uc790\ub825\uc120\uc73c\ub85c \ud558\uc804 \uc785\uc790\ub97c \uac00\ub450\uae30 \uc704\ud55c \ucea1\uc290 \uc6a9\uae30. \ud575\uc735\ud569\ub85c\uc640 \uac19\uc740 \uc6d0\ub9ac\ub85c \ub9cc\ub4e4\uc5b4\uc84c\uc73c\uba70, \uadf8 \uad6c\uc870\ub97c \uc751\uc6a9\ud55c \uac83\uc73c\ub85c \ubcf4\uc778\ub2e4.",
    "TIP305_ja.cfg.bin#3": ":movie=#/mov/tip2930.moflex:pos=32,40:\uc785\uc790\uc640 \uadf8 \ubc18\uc785\uc790\uac00 \ucda9\ub3cc\ud574 \uc30d\uc18c\uba78\ud560 \ub54c \ubc1c\uc0dd\ud558\ub294 \uc5d0\\n\ub108\uc9c0. \uc30d\uc18c\uba78\uc740 \uc9c8\ub7c9\uc744 \uac70\uc758 100%\uc758 \ube44\uc728\ub85c \uc5d0\ub108\uc9c0\ub85c \ubcc0\ud658\ud558\ubbc0\ub85c \ud604\uc7ac\uc758 \ubc1c\uc804\uc744 \ud6e8\uc52c \ub2a5\uac00\ud558\uac8c \ub418\uc9c0\ub9cc, \ud604\uc7ac \uae30\uc220\ub85c \uc2e4\ud604\ud558\uae30\ub294 \uc5b4\ub835\ub2e4.",
    "TIP306_ja.cfg.bin#3": "\uc601\uc5b4\ub85c \ub2e4\ubc1c, \ubb36\uc74c, \ubb34\ub9ac \ub4f1\uc744 \ub73b\ud558\uc9c0\ub9cc, \ubb3c\ub9ac\ud559\uc5d0\uc11c\ub294 \uc785\uc790\uac00 \ubaa8\uc5ec \uc774\ub8ec \ub369\uc5b4\ub9ac\ub97c \uac00\ub9ac\ud0a8\ub2e4.",
    "TIP307_ja.cfg.bin#3": "\ubc14\ub9ac\uc628(\uc911\uc785\uc790)\uc758 \uc77c\uc885. \ub300\ubd80\ubd84\uc758 \uc6d0\uc790\ud575\uc740 \uc774 \uc911\uc131\uc790\uc640 \uc591\uc131\uc790\ub85c \uad6c\uc131\ub418\uc5b4 \uc788\uae30 \ub54c\ubb38\uc5d0 \ud575\uc790\ub77c\uace0 \ubd80\ub978\ub2e4. \uc790\uc720 \uc911\uc131\uc790\ub294 \ud575\ubd84\uc5f4\uc5d0\uc11c \ud655\uc778\ub418\uba70, \ubcf4\ud1b5 \uc790\uc5f0\uacc4\uc5d0\ub294 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \uc5ec\uaca8\uc9c4\ub2e4.",
    "TIP308_ja.cfg.bin#3": "\ud734 \uc5d0\ubc84\ub81b\uc774 \uc81c\ucc3d\ud55c \uc591\uc790 \uc5ed\ud559 \ud574\uc11d \uc911 \ud558\ub098. \uc138\uacc4\ub294 \uba87 \uac00\uc9c0 \uc11c\ub85c \ub2e4\ub978 \uc0c1\ud0dc\uac00 \uc911\ucca9\ub41c \ub2e4\uc138\uacc4\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc9c0\ub9cc, \uad00\uce21\uc790 \uc790\uc2e0\ub3c4 \uadf8\ub7f0 \uc138\uacc4\uc5d0 \uc18d\ud574 \uc788\uc5b4 \uc790\uae30 \uc138\uacc4\uc640 \ub2e4\uc138\uacc4\uc758 \uad6c\ubcc4\uc744 \uc778\uc2dd\ud560 \uc218 \uc5c6\ub2e4\ub294 \ud574\uc11d\uc774\ub2e4.",
    "TIP309_ja.cfg.bin#3": "\ucf54\ud39c\ud558\uac90\uc758 \ubcf4\uc5b4 \uc5f0\uad6c\uc18c\uc5d0\uc11c \uc2dc\uc791\ub41c \uc591\uc790 \uc5ed\ud559 \ud574\uc11d \uc911 \ud558\ub098. \uc138\uacc4\ub294 \uba87 \uac00\uc9c0 \uc11c\ub85c \ub2e4\ub978 \uc0c1\ud0dc\uc758 \uc911\ucca9\uc774\uc9c0\ub9cc, \uad00\uce21\uc790\uac00 \uad00\uce21\ud568\uc73c\ub85c\uc368 \uc218\ub834\ud55c\ub2e4\ub294 \ud574\uc11d\uc774\ub2e4. \uc5b4\ub514\uae4c\uc9c0\ub098 \ud574\uc11d\uc77c \ubfd0, \ud559\ubb38\uc801\uc73c\ub85c \uacb0\ub860\uc774 \ub09c \uac83\uc740 \uc544\ub2c8\ub2e4.",
    "TIP310_ja.cfg.bin#3": "\uc790\uae30\uc7a5 \uc548\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \uac00\uc0c1\uc758 \uc120. \ubcf4\ud1b5 \uc790\uc11d\uc758 N\uadf9\uc5d0\uc11c S\uadf9\uc744 \uc787\ub294 \ud615\ud0dc\ub85c \uadf8\ub9ac\uba70, \uc790\ub825\uc774 \uac15\ud560\uc218\ub85d \uc790\ub825\uc120\uc758 \uc218\uac00 \ube44\ub840\ud574 \ub9ce\uc544\uc9c4\ub2e4.",
    "TIP311_ja.cfg.bin#3": ":texture=#/tip/tip3000.xa:pos=32,40:\ud68c\uc804\ud558\ub294 \ucee4 \ube14\ub799\ud640\uc758 \uc678\ubd80 \uc601\uc5ed. \uc0ac\uac74\uc758 \uc9c0\ud3c9\uc120\uc5d0 \ub9de\ub2ff\uc544 \uc788\uc73c\uba70 \ud68c\uc804 \ud0c0\uc6d0\uccb4 \ubaa8\uc591\uc774\uae30 \ub54c\ubb38\uc5d0 \u300e\uc5d0\ub974\uace0 \uad6c\u300f\ub77c\uace0\ub3c4 \ubd80\ub978\ub2e4. \ub85c\uc800 \ud39c\ub85c\uc988\uc758 \uc0ac\uace0 \uc2e4\ud5d8\uc5d0 \ub530\ub974\uba74 \uc5d0\ub974\uace0 \uc601\uc5ed\uc5d0\uc11c \ube14\ub799\ud640\uc758 \uc5d0\ub108\uc9c0\ub97c \uaebc\ub0bc \uc218 \uc788\ub2e4\uace0 \ud55c\ub2e4.",
    "TIP312_ja.cfg.bin#3": "\uc904\uc740 \uc5f4\ub7c9\uc774\ub098 \uc77c, \uc5d0\ub108\uc9c0\uc758 \ub2e8\uc704\uc774\uba70, 1\uc904\uc740 1\uc640\ud2b8\ucd08\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc5d1\uc0ac\uc904\uc740 10\uc758 18\uc2b9\uc73c\ub85c, \uc22b\uc790\ub85c \ub098\ud0c0\ub0b4\uba74 1,000,000,000,000,000,000\uc904\uc774\ub2e4. \uaddc\ubaa8 9.0 \uc9c0\uc9c4\uc758 \uc5d0\ub108\uc9c0\ub294 \uc57d 2\uc5d1\uc0ac\uc904\uc774\ub2e4.",
    "TIP313_ja.cfg.bin#3": "\uc774 \uc138\uacc4\uc5d0\uc11c \uc120\uc9c4\ud30c\ub97c \uac80\ucd9c\ud558\ub294 \uc7a5\uce58\uc758 \uc774\ub984. \uce74\uc774\uc640 \uc2e0\ub3c4\uac00 \uacf5\ub3d9\uc73c\ub85c \uac1c\ubc1c\ud588\uc73c\uba70, \uc218\ud559\uc801\uc73c\ub85c \uc120\uc9c4\ud30c\ub97c \ub3c4\ucd9c\ud55c \ud720\ub7ec\uc640 \ud30c\uc778\uba3c \ub450 \uc0ac\ub78c\uc5d0\uac8c \uacbd\uc758\ub97c \ud45c\ud574 \uc774\ub984 \ubd99\uc600\ub2e4.",
    "TIP314_ja.cfg.bin#3": "\uc874 \ud720\ub7ec\uc640 \ub9ac\ucc98\ub4dc \ud30c\uc778\uba3c\uc774 \ub3c4\ucd9c\ud55c \uc9c0\uc5f0\ud30c\uc640 \uc120\uc9c4\ud30c\uc5d0 \ubc14\ud0d5\uc744 \ub450\uace0 \uc6cc\uc2f1\ud134 \ub300\ud559\uc758 \ubb3c\ub9ac\ud559\uc790 \uc874 \ud06c\ub808\uc774\uba38\uac00 \uc81c\ucc3d\ud55c \uc591\uc790 \uc5ed\ud559 \ud574\uc11d \uc911 \ud558\ub098. \ubbf8\ub798\ub85c \uc804\ud30c\ub418\ub294 \uc9c0\uc5f0\ud30c\uc640 \uacfc\uac70\ub85c \uc804\ud30c\ub418\ub294 \uc120\uc9c4\ud30c\uac00 \uc911\ucca9\ub418\uc5b4 \ud655\uc815\ub41c\ub2e4\ub294 \uacac\ud574\ub97c \ucde8\ud55c\ub2e4.",
    "TIP315_ja.cfg.bin#3": "\ud788\ub098\uc758 \ud14c\ub9c8\uace1 \u300cThe Door Into Summer\uff08\uc5ec\ub984\uc73c\ub85c \uac00\ub294 \ubb38\uff09\u300d\uc740 \uc81c\ubaa9 \uadf8\ub300\ub85c \uace0\uc804 SF \uc18c\uc124\uc744 \ubaa8\ud2f0\ud504\ub85c \uc0bc\uc558\ub2e4. \uc0ac\uc2e4 \uace0\uc591\uc774\uc758 \uc2dc\uc810\uc5d0\uc11c \uac00\uc0ac\ub97c \uc37c\ub2e4. \ubcf4\uceec \uc624\uc9c0\ub9c8 \uc528\uc5d0\uac8c\ub3c4 \uace0\uc591\uc774\uc758 \uae30\ubd84\uc73c\ub85c \uc990\uac81\uac8c \ubd88\ub7ec \ub2ec\ub77c\uace0 \ubd80\ud0c1\ud588\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP316_ja.cfg.bin#3": "\ubbf8\ucf54\ud1a0\ub294 \uc774 \ub4a4 \uc911\uc0c1\uc744 \uc785\uc740 \ucc44 \ud63c\uc790 TV \ud30c\uc774\ube0c\uc5d0\uc11c \ube44\ub514\uc624\ub97c \ud6d4\uccd0 \ub0b4 \ud788\ub098\uc5d0\uac8c \uac74\ub124\uc57c \ud55c\ub2e4. \uc815\ub9d0 \uace4\ub780\ud55c \uc77c\uc774\ub2e4. \uc774\ub7f0 \ub54c \uc2dc\uac04\ucd95\uc774 \uc62c\ubc14\ub978 \ubaa8\uc2b5\uc73c\ub85c \ub3cc\uc544\uac00\ub3c4\ub85d \ub3d5\ub294 \uac83\uc774 \ud53c\ud2b8\uc758 \uc5ed\ud560\uc774\ub2e4. \uadf8\ub807\uac8c \uc0dd\uac01\ud558\uba74 \ud53c\ud2b8\uac00 \uce74\ubbf8\uc57c\uc5d0\uac8c \uc5c4\uaca9\ud55c \uac83\ub3c4 \uc774\ud574\ud560 \uc218 \uc788\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP317_ja.cfg.bin#3": "TV \ud30c\uc774\ube0c\uc758 \ucc28\ub7c9 \ubaa8\ub378\uc740 \uc5b4\ub290 \uac78\uc791 \uc2dc\uac04\uc5ec\ud589 \uc601\ud654\uc5d0\uc11c \ub4dc\ub85c\ub9ac\uc548\uc744 \ucad3\uc544\ub2e4\ub2c8\ub294 \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\uc758 \ubc34\uc774\ub2e4. \uc2e0\ub3c4\uc758 \ub4dc\ub85c\ub9ac\uc548\uacfc \ucfe0\ub77c\ubaa8\ud1a0\uc758 \ubc34\uc73c\ub85c \uc790\ub3d9\ucc28 \ucd94\uaca9 \uc7a5\uba74\uc744 \ub9cc\ub4e4\uc9c0 \ubabb\ud55c \uac83\uc774 \uc544\uc27d\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP318_ja.cfg.bin#3": "\ud53c\ud2b8\ub294 \uc6d0\ub798 \uce74\uc774\uac00 2013\ub144 \ub2f9\uc2dc \uae30\ub974\ub358 \uace0\uc591\uc774\ub2e4. \uadf8 \ud6c4 \uce74\uc774\uac00 \uc2e4\uc885\ub418\uace0 \uc2e0\ub3c4\uac00 \ub370\ub824\uac04\ub2e4. \uadf8\ub9ac\uace0 \ubbf8\ucf54\ud1a0\uc640 \ud568\uaed8 \uae30\ub974\uac8c \ub418\ub294\ub370, \ud53c\ud2b8\ub294 \uc8fc\uc778\uc778 \uce74\uc774\uc640 \uac19\uc740 \ub0c4\uc0c8\ub97c \ub290\uaf08\ub294\uc9c0 \ubbf8\ucf54\ud1a0\ub97c \ubb34\ucc99 \uc798 \ub530\ub974\uac8c \ub41c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP319_ja.cfg.bin#3": "\ubbf8\ucf54\ud1a0\uc758 \ud14c\ub9c8\uace1 \u300cDr. Schrodinger, tell me please?\uff08\ubd80\ub514 \uc54c\ub824 \uc918, \ub2e5\ud130 \uc288\ub8b0\ub529\uac70\uff09\u300d\ub294 \uc591\uc790\ub860\uc801 \uc138\uacc4\ub97c \ud14c\ub9c8\ub85c \ud55c \uc5b4\ub290 \uc601\ud654\ub97c \ubaa8\ud2f0\ud504\ub85c \uc791\uc0ac\ud588\ub2e4. \uac8c\uc784\uc744 \ubaa8\ub450 \ud50c\ub808\uc774\ud55c \ub4a4 \uac00\uc0ac\ub97c \uc77d\uc73c\uba74 \uac10\ud68c\uac00 \uae4a\uc744\uc9c0\ub3c4\u2026\u2026\u3010\uc774\uc2dc\uc774\u3011",
    "TIP320_ja.cfg.bin#3": "\ub8e8\uc0c1\uce58\u2606\ub9e8\uc758 \ud14c\ub9c8\uace1 \u300cHero Behind The Mask\uff08\uac00\uba74 \ub4a4\uc758 \ud788\uc5b4\ub85c\uff09\u300d\ub294 \ub8e8\uc0c1\uce58\u2606\ub9e8\uc758 \uc18c\uac1c \uba58\ud2b8\ub97c \uadf8\ub300\ub85c \uc601\uc5b4\ub85c \ubc88\uc5ed\ud574 \ub2ec\ub77c\uace0 \ud588\ub2e4. \uadf8\ub798\uc11c \uc791\uc0ac\uc790\ub294 \uc2dc\ub098\ub9ac\uc624 \ub2f4\ub2f9 \uae30\ud0c0\uc9c0\ub9c8 \uc528\uac00 \ub418\uc5c8\ub2e4. \uc655\ub144\uc758 \ud2b9\ucd2c \ud788\uc5b4\ub85c\uc1a1\uc744 \uc601\uc5b4\ub85c \ubd80\ub974\uba74 \uc5b4\ub5a8\uae4c \ud558\ub294 \ucf58\uc149\ud2b8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP321_ja.cfg.bin#3": "\uc2e0\ub3c4\uc758 \ud14c\ub9c8\uace1 \u300cTime after Time\uff08\ub418\ud480\uc774\ud558\uace0, \ub418\ud480\uc774\ud558\uace0\uff09\u300d\ub294\u2026\u2026 \uc774\ubc88\uc5d0 \uc2dc\uac04\uc5ec\ud589\ubb3c\uc744 \ub9cc\ub4e4\uac8c \ub418\uc5b4 \uc870\uc0ac\ud558\uba74 \ud560\uc218\ub85d \uc774\ubbf8 \ub2e4 \ub2e4\ub904\uc9c4 \uc18c\uc7ac\ub77c \uc774\uc81c \uc544\uc774\ub514\uc5b4 \uac19\uc740 \uac74 \uc5c6\ub2e4\uace0 \uc678\uce58\ub294 \ub178\ub798\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP322_ja.cfg.bin#3": "\uc774 \ub4a4 \ube45\uc758 \ub300\uc0ac \u300e\uc5ec\uc804\ud558\uad70\u300f\uc740\u2026\u2026 \uc774 \uac1c\uadf8\uc5d0 \u300e\uc5ec\uc804\ud558\ub2e4\u300f\uace0 \ub9d0\ud55c \uac83\uc77c\uae4c\uc694?\u3010\uc774\uc2dc\uc774\u3011",
    "TIP323_ja.cfg.bin#3": "\u300e\uc6c3\ub294 \uc5bc\uad74 \uc5f0\uc2b5\u300f\uc774\ub77c\uace0 \ud558\uba74 \uadf8 \ucd08\ub300\uc791 RPG\uc758 \uba85\uc7a5\uba74. \uadf8 \uc7a5\uba74\uc744 \uc4f0\uc2e0 \uc2dc\ub098\ub9ac\uc624 \uc791\uac00\ub2d8\uaed8 \ucc98\uc74c \ub9cc\ub09c \uc790\ub9ac\uc5d0\uc11c\\n\u300e\uc6c3\ub294 \uc5bc\uad74 \uc5f0\uc2b5\u300f\uc744 \uc0ac\uc6a9\ud558\uac8c \ud574 \ub2ec\ub77c\uace0 \ubd80\ud0c1\ud588\uace0\u2026\u2026 \ud754\ucf8c\ud788 \ud5c8\ub77d\ud574 \uc8fc\uc168\uc2b5\ub2c8\ub2e4. \uac10\uc0ac\ud569\ub2c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP324_ja.cfg.bin#3": "\uc804\ud654\ub97c \uac74 \uac83\uc740 \uc2dc\uac04\uc5ec\ud589 6\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. \uc790\uc2e0\uc758 \ud734\ub300\uc804\ud654\uac00 \uc815\uc9c0\ub418\uae30 \uc804\uc5d0 \ub178\ub098\uce74\uc5d0\uac8c \uc804\ud654\ud55c \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \ub178\ub098\uce74\ub294 \uadf8 \uc0ac\uc2e4\uc744 \ubbff\uc9c0 \ubabb\ud588\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP325_ja.cfg.bin#3": "\uc6d0\ub798 \ub85c\uc2a4\ud2b8 \ud640\uc774 \uc77c\uc5b4\ub098\ub294 \uac83\uc740 1995\ub144\uc774\uace0, \uc774\uc57c\uae30 \uc18d\uc740 \uac00\uc9dc\uc778 2013\ub144\uc774\ub77c\ub294 \uc124\uc815\uc774\uc5c8\ub2e4. \ud558\uc9c0\ub9cc 2013\ub144 \uc0ac\ub78c\ub4e4\uc774 18\ub144 \uc804\uc758 \ud070 \uc7ac\ud574\ub97c \uc78a\uace0 \ubc88\uc601\uc5d0 \ube60\uc838 \uc788\ub2e4\ub294 \uc124\uc815\uc5d0 \ud604\uc2e4\uac10\uc744 \ub290\ub084 \uc218 \uc5c6\uc5b4\uc11c, \uc57d 2\uac1c\uc6d4\uc5d0 \uac78\uccd0 \uc2dc\ub098\ub9ac\uc624\ub97c \ub300\ud3ed \uc218\uc815\ud588\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP326_ja.cfg.bin#3": "\uc774 \uc0ac\ub791\uc758 \ub3c4\ud53c\ud589 \uc7a5\uba74\uc740 \uc601\ud654 \u300e\ube14\ub808\uc774\ub4dc \ub7ec\ub108\u300f\uc758 \ucd5c\ucd08 \uacf5\uac1c\ud310 \uc5d4\ub529\uc744 \uc774\ubbf8\uc9c0\ub85c \uc0bc\uc544 \ub9cc\ub4e4\uc5c8\ub294\ub370\u2026\u2026 \ucd5c\ucd08 \uacf5\uac1c\ud310\uc740 \uc0ac\uc2e4 \ubcf4\ub294 \uc0ac\ub78c\uc774 \uc801\uc740 \uac83 \uc544\ub2c8\ub0d0\uace0 \ud604\uc7a5\uc5d0\uc11c \uacc4\uc18d \ud0dc\ud074\uc744 \ubc1b\uc558\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP327_ja.cfg.bin#3": "\uc774 \ubbf8\ucf54\ud1a0\ub294 \uc2dc\uac04\uc5ec\ud589 6\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. \uc774 \ub4a4 \ud53c\ud2b8\uc640 \ud568\uaed8 \uc2e4\ub9b0\ub354 \ub7a9\uc5d0 \uc7a0\uc785\ud55c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP328_ja.cfg.bin#3": "\ub9de\uc2b5\ub2c8\ub2e4. \uc8c4\uc1a1\ud569\ub2c8\ub2e4. \uc288\ub9cc\uc758 \u300e\ud53c\uc544\ub178 \ud611\uc8fc\uace1 \uac00\ub2e8\uc870 54\ubc88\u300f\uc785\ub2c8\ub2e4. \uc774\uac83\ub9cc\uc744 \uc704\ud574 \uc624\ucf00\uc2a4\ud2b8\ub77c \ub179\uc74c\uc744 \ud574 \uc8fc\uc168\uc2b5\ub2c8\ub2e4. \uc11c\ucabd \ud558\ub298\uc5d0 \uc0c8\ubcbd\uc758 \uc0db\ubcc4\uc774 \ube5b\ub0a0 \ubb34\ub835\uc774\ub77c\ub294 \uc18c\uc7ac\uc785\ub2c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP329_ja.cfg.bin#3": "\uac00\uc9dc \ubbf8\uad6d \ub9cc\ud654 \ud788\uc5b4\ub85c\ud48d\uc758 \ubb34\ub2a5\ud55c \ud788\uc5b4\ub85c\ubb3c\uc744 \ud558\uace0 \uc2f6\ub2e4\uace0 \uc124\uc815 \uace0\uc99d\uc744 \ub2f4\ub2f9\ud55c \uc2dc\ub77c\ud1a0 \uc528\uc5d0\uac8c \uc774\uc57c\uae30\ud588\uc744 \ub54c \u300e\uc2e4\uc81c\ub85c \uc788\uc5b4\uc694\u300f\ub77c\uace0 \uc18c\uac1c\ubc1b\uc740 \uac83\uc774 \ub9ac\uc5bc \ub77c\uc774\ud504 \ud788\uc5b4\ub85c\ub2e4. \uc2dc\ub098\ub9ac\uc624\ub294 \uc774\ubbf8 \uc644\uc131\ub418\uc5b4 \uc788\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uc601\ud654 \u300e\ud0a5 \uc560\uc2a4\u300f\uac00 \uac1c\ubd09\ud588\uc744 \ub54c \uacb9\uce58\uc9c0 \uc54a\uc558\uc744\uae4c \uc870\ub9c8\uc870\ub9c8\ud588\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP330_ja.cfg.bin#3": "\u300e428\uff5e\ubd09\uc1c4\ub41c \uc2dc\ubd80\uc57c\uc5d0\uc11c\uff5e\u300f\uc5d0\uc11c \uc778\ud615 \ud0c8 \ud0c0\ub9c8\uc758 \ucf5c\ub77c\ubcf4 \ucd9c\uc5f0\uc744 \ud754\ucf8c\ud788 \ud5c8\uac00\ud574 \uc8fc\uc2e0 \uc2a4\ud30c\uc774\ud06c\u30fb\ucd98\uc18c\ud504\ud2b8 \ubd84\ub4e4\uaed8 \uc815\ub9d0 \uac10\uc0ac\ub4dc\ub9bd\ub2c8\ub2e4. \uac1c\ubc1c \ub9c9\ubc14\uc9c0\uc5d0 \ud22c\uc785\ub41c \uc544\uc774\ub514\uc5b4\uc600\uc9c0\ub9cc, 5\ud68c\uc9f8 \ubbf8\ucf54\ud1a0\uc758 \uc5ed\ud560\uc774 \ub298\uc5b4\ub098 \uc774\uc57c\uae30\uac00 \ud655\uc7a5\ub418\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP331_ja.cfg.bin#3": "\uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \uac83\uc740 \uc2dc\uac04\uc5ec\ud589 5\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. TV \ud30c\uc774\ube0c \uc548\uc744 \ub3cc\uc544\ub2e4\ub140\ub3c4 \uc758\uc2ec\ubc1b\uc9c0 \uc54a\ub3c4\ub85d \uacbd\ube44\uc6d0\uc2e4\uc5d0 \ub193\uc5ec \uc788\ub358 \uc778\ud615 \ud0c8\uc744 \ube4c\ub9b0 \uac83\uc774\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP332_ja.cfg.bin#3": "\uc774\ub300\ub85c \uc774\uc57c\uae30\uac00 \uc9c4\ud589\ub418\uba74, \uc774 \ub4a4 18\uc2dc\uc5d0 \ubbf8\ucf54\ud1a0\uac00 \ucc28 \uc548\uc5d0\uc11c \uc2e0\ub3c4\uc5d0\uac8c \ub9d0\ud558\ub294 \u300e\uafc8\uc744 \uafe8\uc5b4. \uc544\uc8fc \uc774\uc0c1\ud55c \uafc8\u300f\uc758 \uafc8\uc740 \u300e\ubc18\uc131\\n\ubb38\uc744 \uc4f0\uace0 \uc788\uc5c8\ub294\ub370 \uac11\uc790\uae30 \ub208\uc55e\uc758 \ubc18\uc131\ubb38\uc774 \uc0ac\ub77c\uc84c\ub2e4\u300f\ub294 \uc774\uc0c1\ud55c \uc774\uc57c\uae30\uac00 \ub418\uc5c8\uc744 \uac83\uc774\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP333_ja.cfg.bin#3": "\uc5d4\uc870\uc5d0\uac8c \ubd99\uc7a1\ud600 \uc788\ub294 \uac83\uc740 \uc2dc\uac04\uc5ec\ud589 2\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uace0, \uc5ec\uae30\uc11c \ub118\uc5b4\uc9c0\ub294 \uac83\uc740 \uc2dc\uac04\uc5ec\ud589 5\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. \ud788\ub098\uc5d0\uac8c \ub85c\uc2a4\ud2b8 \ud640\uc758 \ube44\ub514\uc624\ub97c \ubcf4\uc5ec \uc8fc\uae30 \uc704\ud574 TV \ud30c\uc774\ube0c \uc548\uc5d0 \uc7a0\uc785\ud55c \uac83\uc774\ub2e4. \uc778\ud615 \ud0c8\uc744 \uc4f0\uace0 \uc788\ub294 \uac83\uc740 \uac74\ubb3c \uc548\uc744 \ub3cc\uc544\ub2e4\ub140\ub3c4 \uc758\uc2ec\ubc1b\uc9c0 \uc54a\uae30 \uc704\ud574\uc11c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP334_ja.cfg.bin#3": "2031\ub144\uc73c\ub85c \ubb34\ub300\uac00 \ubcc0\uacbd\ub418\uc5b4 \uadfc\ubbf8\ub798\ub97c \ub098\ud0c0\ub0b4\ub294 \uc0c1\uc9d5\uc73c\ub85c \uc124\uc815\ub41c \uc6b0\uc8fc \uc5d8\ub9ac\ubca0\uc774\ud130. \ucc98\uc74c\uc5d0\ub294 \uc815\ub9d0\ub85c \ub3c4\ucfc4\\n\ub9cc\uc5d0 \uada4\ub3c4 \uc5d8\ub9ac\ubca0\uc774\ud130\ub97c \uac74\uc124\ud560 \uc218 \uc5c6\ub294\uc9c0 \uac80\ud1a0\ud588\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \uc624\ud0a4\ub098\uc640\uc5d0\uc11c \ubcf4\uc774\ub294 \uac70\ub300\ud55c \uac74\uc870\ubb3c\uc740 \uc9c4\uc9dc \uada4\ub3c4 \uc5d8\ub9ac\ubca0\uc774\ud130\ub77c\ub294 \ub9d0\ub3c4 \uc788\uace0 \uc544\ub2c8\ub77c\ub294 \ub9d0\ub3c4 \uc788\uace0\u2026\u2026\u3010\uc774\uc2dc\uc774\u3011",
    "TIP335_ja.cfg.bin#3": "\uc774\uac83\uc740 \uc5b8\ub860\uc758 \ub300\ud45c\uc801\uc778 \uc758\uacac\uc774\ub77c\ub294 \ub73b\uc774 \uc544\ub2c8\ub77c \uc5b4\ub514\uae4c\uc9c0\ub098 \ud0c0\uce74\uc774\ub3c4\ub77c\ub294 \uce90\ub9ad\ud130\uc758 \uac1c\uc778\uc801\uc778 \uacac\ud574\ub2e4. \uc77c\ub2e8 \ubcc0\uba85\uc744\u2026\u2026 \ucc38\uace0\ub85c \ucd08\uae30 \uc2dc\ub098\ub9ac\uc624\uc5d0\uc11c\ub294 \ud0c0\uce74\uc774\ub3c4\ub3c4 \ub9c8\uc74c\uc744 \ubc14\uafd4 \ud788\ub098\uc758 \ud3b8\uc774 \ub418\ub294 \uc124\uc815\uc774\uc5c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP336_ja.cfg.bin#3": "\ud655\uc2e4\ud788 \uc120\uc774 \uc720\ub9ac\ud558\uc9c0\ub9cc, \uc2e4\uc81c\ub85c \uac8c\uc784\uc744 \ud574 \ubcf4\uba74 \uc120\uacfc \ud6c4\uc758 \uc2b9\ub960\uc740 \uadf8\ub2e4\uc9c0 \ub2e4\ub974\uc9c0 \uc54a\ub2e4. \uc120\uc774 \uc720\ub9ac\ud55c \ub9cc\ud07c \uc9c0\ub294 \uac83\uc774 \ubd80\ub044\ub7fd\ub2e4\ub294 \uc555\ubc15\uac10\uc774 \ud070 \uac83\uc774 \uc774\uc720\uc77c\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP337_ja.cfg.bin#3": "\uc2e0\ub3c4\uac00 \ubd84\ud55c \ud45c\uc815\uc744 \uc9d3\ub294 \uac83\uc740 \uc84c\uae30 \ub54c\ubb38\uc774 \uc544\ub2c8\ub77c \u300e1\u300f\uc5d0 \u300e1\u300f\uc744 \ub9de\ud788\ub294 \ucd5c\uc545\uc758 \ud328\ubc30 \ubc29\uc2dd\uc744 \ud0dd\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. 1\ud68c\uc804\uc5d0\uc11c \uc774\uae34 \uc2e0\ub3c4\ub294 2\ud68c\uc804\uc5d0\uc11c \uc5d4\uc870\uc5d0\uac8c \ucd5c\ub300\ud55c \ud070 \uc218\ub97c \ub0b4\uac8c \ud574 \ud070 \ucc28\uc774\ub85c \uc9c0\ub294 \uc791\uc804\uc774\uc5c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP338_ja.cfg.bin#3": "\uc120\uc740 \ubaa8\ub4e0 \uc2b9\ubd80\uc5d0\uc11c \ud6c4\uc640 \uac19\uc740 \uce74\ub4dc\ub97c \ub0b4\uba74 \ud6c4\ubc18\\n\uc804\uc5d0\uc11c \uc720\ub9ac\ud558\uac8c, \ubc18\ub300\ub85c \ud6c4\ub294 \uc120\ubcf4\ub2e4 \ud55c \uc7a5 \ud070 \uce74\ub4dc\ub97c \ub0b4\uba74 \ud6c4\ubc18\uc804\uc744 \uc720\ub9ac\ud558\uac8c \uc804\uac1c\ud560 \uc218 \uc788\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP339_ja.cfg.bin#3": "\uc120\uc740 \u300e5\u300f\ub97c \ub0b4\uba74 \ubc18\ub4dc\uc2dc \uc774\uae34\ub2e4. \ubc18\ub300\ub85c \ud6c4\ub294 \u300e1\u300f\uc744 \ub0b4\uba74 \ubc18\ub4dc\uc2dc \uc9c4\ub2e4. \ud6c4\uac00 \uc120\uc758 \ud578\ub514\ucea1\uc744 \uc5c6\uc560\ub824\uba74 \uc120\uc758 \u300e5\u300f\uc5d0 \u300e1\u300f\uc744 \ub9de\ud788\uba74 \ub41c\ub2e4. \uc774\uac83\uc744 \uc2e4\ud328\ud558\uba74 \ud6c4\ub294 \ucd5c\ub300 3\uc2b9\ubc16\uc5d0 \uac70\ub458 \uc218 \uc5c6\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP340_ja.cfg.bin#3": "\uc778\ud615 \ud0c8 \uc548\uc5d0 \uc788\ub294 \uac83\uc740 \uc2dc\uac04\uc5ec\ud589 5\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. 1~4\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uc640 \ub9c8\uc8fc\uccd0 \ud63c\ub780\uc774 \uc77c\uc5b4\ub098\uc9c0 \uc54a\ub3c4\ub85d TV \ud30c\uc774\ube0c\uc758 \uc778\ud615 \ud0c8\uc744 \ube4c\ub838\ub2e4. \ub8e8\uc0c1\uce58\u2606\ub9e8\uc774 3\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uc5d0\uac8c \uce74\ub4dc\ud0a4\ub97c \uac74\ub124\uc57c\\n\ud558\uae30 \ub54c\ubb38\uc5d0, \uc778\ud615 \ud0c8\uc5d0 \ubab8\uc744 \uc228\uae34 \ucc44 \uc720\ub3c4\ud55c \uac83\uc774\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP341_ja.cfg.bin#3": "\ub098\ud30c\uc758 \uc561\uc158 \uc7a5\uba74 \ub3d9\uc791\uc740 \uc804\ubd80 \ubaa8\uc158 \ucea1\ucc98\ub2e4. \uc561\uc158 \uc804\ubb38 \ubaa8\uc158 \ubc30\uc6b0 \uc9d1\ub2e8\\n\u300e\ud65c\uadf9\uc88c\u300f\uc5d0 \ubd80\ud0c1\ud588\ub2e4. \ucc38\uace0\ub85c \ub098\ud30c\uc758 \uaca9\ud22c \uc2a4\ud0c0\uc77c\uc740 \ubb34\uc5d0\ud0c0\uc774\ub77c\uae30\ubcf4\ub2e4 \uc775\uc2a4\ud2b8\ub9bc \ub9c8\uc15c \uc544\uce20\ub77c\ub294 \uc7a5\ub974\ub77c\uace0 \ud55c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP342_ja.cfg.bin#3": "\uacc4\uc0b0\uc744 \ub2e8\uc21c\ud654\ud558\uba74 \ud6c4\ub294 3\ubc88\uc758 \uc2b9\ub9ac\ub85c \uce69 8\uac1c\ub97c \uac00\uc838\uac00\uba74 \uc774\uae34\ub2e4. \uc120\uc740 \u300e5\u300f\ub97c \uc544\ub084 \uac00\ub2a5\uc131\uc774 \ub192\uc73c\ubbc0\ub85c 1~3\ud68c\uc804\uc5d0\uc11c \uce69 4\uac1c\ub97c \uac00\uc838\uac00\ub294 \uac83\uc774 \ud544\uc218\ub2e4. \ubb3c\ub860 \uadf8 \uc791\uc804\uc744 \uc120\uc5d0\uac8c \uc77d\ud788\uba74 \ud798\ub4e0 \uc2f8\uc6c0\uc774 \ub41c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP343_ja.cfg.bin#3": "\uc548\uc5d0 \uc788\ub294 \uac83\uc740 \uc2dc\uac04\uc5ec\ud589 5\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. \ucf54\uc774\ubb34\ub77c\uc640 \ud558\uc57c\ubbf8\uc758 \ud1b5\ub85c\ub97c \ubc14\uafb8\uace0 \ube45 \ud578\ub4dc\uc640 \ub8e8\uc0c1\uce58\u2606\ub9e8\uc774 \ub9c8\uc8fc\uce58\uac8c \ud558\uae30 \uc704\ud574 \uc778\ud615 \ud0c8 \ucc28\ub9bc\uc73c\ub85c \uce74\ubbf8\uc57c\uc640 4\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub97c \uc720\ub3c4\ud558\ub294 \uac83\uc774\ub2e4. \uc778\ud615 \ud0c8\uc744 \uc4f0\uace0 \uc788\ub294 \uac83\uc740 1~4\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uc5d0\uac8c \ubaa9\uaca9\ub418\uc5b4 \ud63c\ub780\uc774 \uc77c\uc5b4\ub098\uc9c0 \uc54a\ub3c4\ub85d \ud558\uae30 \uc704\ud574\uc11c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP344_ja.cfg.bin#3": "\uadf8\ub807\ub2e4. \ub610 \uce74\ubbf8\uc57c \ub54c\ubb38\uc5d0 \ubbf8\ucf54\ud1a0\ub294 \ub2e4\uc74c \ud68c\ucc28\uc5d0\uc11c \ud574\uace8\uc5d0\uac8c \uae30\uc808\ub2f9\ud55c \ud53c\ud574\ub97c \uc548\uc740 \ucc44 \ube44\ub514\uc624\ub97c \ubc29\uc1a1\uad6d\uc5d0 \uc804\ub2ec\ud558\uace0, \uc778\ud615 \ud0c8\uc744 \uc4f0\uace0 \ubaa8\ub450\ub97c \uc720\ub3c4\ud574\uc57c \ud55c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP345_ja.cfg.bin#3": "\uadf8\ub7f0 \ud1b5\uacc4\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. \uc8c4\uc1a1\ud569\ub2c8\ub2e4. \ud0c0\uc784 \ud2b8\ub798\ube14\ub7ec\uc988\uc758 \uae30\ud68d\uc744 \uc0dd\uac01\ud558\ub358 \uc911 \ub5a0\uc624\ub978 \uc544\uc774\ub514\uc5b4 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc758\uc678\ub85c \ub9de\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP346_ja.cfg.bin#3": "\uc774 \uc785\uad6c\ub294 \uc2dc\uac04\uc5ec\ud589 5\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uac00 \uc2e4\ub9b0\ub354 \ub7a9\uc5d0 \uce68\uc785\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ud55c\ub2e4. \uc778\ud615 \ud0c8\uc774 \ubc97\uaca8\uc9c4 \ucc44 \ubc84\ub824\uc838 \uc788\ub294 \uac83\uc740 \ubbf8\ucf54\ud1a0\uac00 \uce68\uc785\ud55c \ud754\uc801\uc774\ub2e4.\\n\u3010\uc774\uc2dc\uc774\u3011",
    "TIP347_ja.cfg.bin#3": "\uc774 \uc7a5\uba74\uc744 \ubcf4\uba74 \uc5b4\uc9f8\uc11c\uc778\uc9c0 \u300e\ud3ec\uae30\ud558\uc9c0 \ub9c8! \uc27d\uac8c \ud3ec\uae30\ud558\uc9c0 \ub9c8!\u300f\ub77c\uace0 \uc678\uce58\ub294 \u300e428\uff5e\ubd09\uc1c4\ub41c \uc2dc\ubd80\uc57c\uc5d0\uc11c\uff5e\u300f\uc758 \ubbf8\ub178\ub9ac\uce74\uc640 \ubbf8\ub178\ub8e8 \uba85\uc7a5\uba74\uc774 \ub5a0\uc624\ub978\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP348_ja.cfg.bin#3": "\uc774 \ubbf8\ucf54\ud1a0\ub294 \uc2dc\uac04\uc5ec\ud589 4\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. \uc774 \ub4a4 \u300e18\uc2dc 35\ubd84\u300f\uc5d0 3\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uac00 \u300e\uc804\uc77c\ubcf8\uc804\ub825 \uc9c0\ud558\uc758 \ud3ed\ud0c4\uc744 \ud574\uc81c\ud588\ub2e4\ub294 \uc815\ubcf4\u300f\ub97c \u300e\ub8e8\uc0c1\uce58\u2606\ub9e8\u300f\uc5d0\uac8c \ub4e4\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uac00\ub2a5\ud55c \ud589\ub3d9\uc774\uc5c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP349_ja.cfg.bin#3": "\uce74\uc774 \uc77c\ud589\uc774 \uc2e4\uc2dc\ud55c \uc2e4\ud5d8\uc758 \uc601\ud5a5\uc73c\ub85c 2013\ub144\uacfc 2031\ub144 \uc0ac\uc774 18\ub144 \ub3d9\uc548 \uc2dc\uacf5 \ud63c\ud0c1\uc774\ub77c \ubd88\ub9ac\ub294 \ud604\uc0c1\uc774 \ubc1c\uc0dd\ud558\uace0 \uc788\ub2e4. \uc2dc\uac04\uc5ec\ud589\uc790\ub4e4\uc774 \ubb34\uc758\uc2dd\uc801\uc73c\ub85c \uc2dc\uac04\uc5ec\ud589\uc744 \ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc774 \uc2dc\uacf5 \ud63c\ud0c1\uc758 \uc601\ud5a5\uc774\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP350_ja.cfg.bin#3": "\ud53c\ud2b8\uac00 \uc2dc\ub178\ud558\ub77c\ub97c \uae30\uc808\uc2dc\ud0a8 \uae30\uc220\uc740 \ubc8c\ucee8 \uc2e0\uacbd \uc870\ub974\uae30\ub2e4. \ubaa9\ub35c\ubbf8 \uadfc\ucc98\uc758 \uc2e0\uacbd\uc744 \uc138\uac8c \uc6c0\ucf1c\uc950\uace0 \uc555\ubc15\ud574 \uc21c\uc2dd\uac04\uc5d0 \uae30\uc808\uc2dc\ud0a4\ub294 \uae30\uc220\uc774\ub2e4. \u300e\uc7a5\uc218\uc640 \ubc88\uc601\uc744.\u300f\u3010\uc774\uc2dc\uc774\u3011",
})

OVERRIDES["tip.json"].update({
    "TIP351_ja.cfg.bin#3": "\uc774 \ubbf8\ucf54\ud1a0\ub294 \uc2dc\uac04\uc5ec\ud589 2\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. 2\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub294 \uc544\uc9c1 \ud53c\ud2b8\ub97c \ubaa8\ub978\ub2e4. \ud558\uc9c0\ub9cc \ud53c\ud2b8\ub294 \uc774\ubbf8 3\ud68c\uc9f8 \uc774\ud6c4\uc758 \ubbf8\ucf54\ud1a0\ub4e4\uacfc \ub2e4\uc591\ud55c \ud589\ub3d9\uc744 \ud568\uaed8\ud55c \ub4a4 \uc774 \uc0c1\ud669\uc5d0 \uc774\ub974\ub800\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP352_ja.cfg.bin#3": "\uc774 \ubbf8\ucf54\ud1a0\ub294 \uc2dc\uac04\uc5ec\ud589 3\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. 3\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub294 \uc774\ub54c \u300e\uc804\uc77c\ubcf8\uc804\ub825 \uc9c0\ud558\uc758 \ud3ed\ud0c4\uc774 \ud574\uc81c\ub410\ub2e4\ub294 \uc815\ubcf4\u300f\ub97c \uc54c\uace0, 4\ud68c\uc9f8\uc5d0 \uce74\ubbf8\uc57c\uc640 \uc694\ud0c0\ub97c \uc0ac\uc640\ud0a4\uc758 \ud568\uc815\uc5d0\uc11c \uad6c\ud558\uac8c \ub41c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP353_ja.cfg.bin#3": "\uc6d0\ub798\ub294 \uc560\ub364 \uc2a4\ubbf8\uc2a4\uc758 \u300e\uad6d\ubd80\ub860\u300f\uc5d0 \ub098\uc624\ub294 \u300e\ubcf4\uc774\uc9c0 \uc54a\ub294 \uc190\u300f\uc5d0\uc11c \ud30c\uc0dd\ub41c \uacbd\uc81c \uc6a9\uc5b4\ub2e4. \uc2dc\uc7a5\uc758 \uc870\uc815 \uae30\ub2a5\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc2a4\ucf08\ub808\ud1a4\uc740 \uc790\uc5f0\uacfc\ud559\uc5d0\uc11c \uacb0\uc815\ub860\uc801\uc778 \uc758\ubbf8\ub85c\\n\uc0ac\uc6a9\ud558\uace0 \uc788\uc9c0\ub9cc, \uc774 \uc138\uacc4\uc758 \uc778\uacfc \uacb0\uc815\uc774 \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5b4\uc9c0\ub294\uc9c0 \ub2f9\uc2e0\uc774\ub77c\uba74 \uc774\ud574\ud560 \uc218 \uc788\uc744 \uac83\uc774\ub2e4.\u3000\u3010\uc774\uc2dc\uc774\u3011",
    "TIP354_ja.cfg.bin#3": "\uc9c4(\ub05d\uc5c6\ub294 \uc6d0\uc744 \uadf8\ub9ac\ub294 \uc138\uacc4\uc120)\uc774\ub77c\ub294 \uc2dc\uacc4\uac00 \uc911\uc694\ud55c \uc758\ubbf8\ub97c \uac16\ub294 \uc2dc\uac04\uc5ec\ud589 \uc601\ud654\uc758 \uac78\uc791 \u300e\uc0ac\ub791\uc758 \uc740\ud558\uc218\u300f. \uc774 \uc791\ud488\uc5d0 \uacbd\uc758\ub97c \ud45c\ud574 \u300e\ud0c0\uc784 \ud2b8\ub798\ube14\ub7ec\uc988\u300f\uc5d0\ub3c4 \uc2dc\uacc4 \ubaa8\uc591\uc758 \uc9c4\uc744 \uc228\uaca8 \ub123\uc5c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP355_ja.cfg.bin#3": "\ub8e8\uc0c1\uce58\u2606\ub9e8\uc758 \uc5bc\uad74\uc774 \uc608\ubed0\uc9c4 \uac83\uc740 \uce58\ub9ac\ucf54\uac00 \uc0ac\ub791\uc774 \ub118\uce58\ub294 \uc751\uae09 \ucc98\uce58\ub97c \ud588\uae30 \ub54c\ubb38\uc774\ub2e4! \u2026\u2026\ubb50\ub77c\uace0! \uadf8\ub7f0 \uc124\uba85 TIPS!\u3010\uc774\uc2dc\uc774\u3011",
    "TIP356_ja.cfg.bin#3": "\uc774 \ubbf8\ucf54\ud1a0\ub294 6\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. 6\uba85\uc758 \ubbf8\ucf54\ud1a0\uac00 \ud53c\ud2b8\uc640 \ud611\ub825\ud574 \uc138\uacc4\ub97c \uc6d0\ub798 \ubaa8\uc2b5\uc73c\ub85c \ub418\ub3cc\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc2dc\uac04\uc5ec\ud589\uc790\ub4e4\uc758 \ubd80\uc8fc\uc758\ud55c \ud589\ub3d9\uc73c\ub85c \uc218\uc2b5\ud560 \uc218 \uc5c6\ub294 \uc0c1\ud669\ub3c4 \uc77c\uc5b4\ub0a0 \uc218 \uc788\ub2e4. \uc0ac\uc2e4 \ud53c\ud2b8\ub294 \uadf8 \ub300\ucc45\ub3c4 \ub9c8\ub828\ud574 \ub450\uc5c8\ub2e4. \ubb34\uc5c7\uc77c\uae4c? \ucd94\ub9ac\ud574 \ubcf4\uc790. \ud78c\ud2b8\ub294 \uc548\uacbd\uc774\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP357_ja.cfg.bin#3": "18\ub144 \uc804\uc778 2013\ub144\uacfc 2031\ub144\uc740 \ub85c\uc2a4\ud2b8 \ud640\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \uadf8\uac83\uc774 \uc2dc\uacf5 \ud63c\ud0c1\uc758 \uc6d0\uc778\uc774\ub2e4. \ubbf8\ucf54\ud1a0\uc758 \uc190\ubaa9\uc2dc\uacc4\ud615 \ud0c0\uc784\uba38\uc2e0\ub3c4 \uc2dc\uacf5 \ud63c\ud0c1\uc744 \uc774\uc6a9\ud55c\ub2e4. \uadf8\ub7f0 \uc774\uc720\ub85c \ubbf8\ucf54\ud1a0\ub3c4 \ud53c\ud2b8\ub3c4 \ub85c\uc2a4\ud2b8 \ud640\uc758 \uae30\uc810\uc778 2013\ub144 4\uc6d4 28\uc77c \uc774\uc804\uc73c\ub85c\ub294 \uc2dc\uac04\uc5ec\ud589\ud560 \uc218 \uc5c6\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP358_ja.cfg.bin#3": "\ubb3c\ub860 \uc720\ub9ac\uc640 \uce74\ucf00\ub8e8, \uc2e0\ub3c4\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub2e4. \uc5b4\uca4c\uba74 \ub208\uce58\ucc48 \uc0ac\ub78c\ub3c4 \uc788\uc744\uc9c0 \ubaa8\ub974\uc9c0\ub9cc, \u300e\ud0c0\uc784 \ud2b8\ub798\ube14\ub7ec\uc988\u300f\uac00 \ucc98\uc74c \ubc1c\ud45c\ub418\uc5c8\uc744 \ub54c\uc758 \uc774\ubbf8\uc9c0 \uc77c\ub7ec\uc2a4\ud2b8\uc778 \u300e\uc2dc\uacc4\ud0d1 \uc704\uc5d0\uc11c \ubd95\uad34\ud55c \ub3c4\uc2dc\ub97c \ubc14\ub77c\ubcf4\ub294 \uc5ec\uc131\u300f\uc740 \ud788\ub098\ub2e4. \uba38\ub9ac \ubaa8\uc591\uacfc \uc637 \uc0c9\uac10\uc5d0 \uc8fc\ubaa9\ud558\uba74 \ub41c\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP359_ja.cfg.bin#3": "\uc774\uacf3\uc758 \uc561\uc158 \uc7a5\uba74\uc740 \uc560\ub2c8\uba54\uc774\uc158 \uac10\ub3c5 \uc548\ub3c4 \ub9c8\uc0ac\ud788\ub85c \uc528\uc5d0\uac8c \ucf58\ud2f0\ub97c \uadf8\ub824 \ub2ec\ub77c\uace0 \ubd80\ud0c1\ud588\ub2e4. \uadf8 \ubc16\uc5d0 \uc9c0\ud558 \uc8fc\ucc28\uc7a5\uc758 \ud53c\ud2b8 \ub4f1\uc7a5 \uc7a5\uba74\uacfc \ub098\ud30c\uc758 \uc561\uc158 \uc7a5\uba74\ub3c4 \uc548\ub3c4 \uac10\ub3c5\uc758 \ucf58\ud2f0\ub2e4. \uc0ac\uc2e4 \uadf8 \ubc16\uc5d0\ub3c4 \ub9ce\uc740 \uc560\ub2c8\uba54\uc774\uc158 \uc5f0\ucd9c\uac00\uac00 \ucf58\ud2f0\ub85c \ucc38\uc5ec\ud588\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP360_ja.cfg.bin#3": "\ucc98\uc74c \ubc1c\ud45c\ub41c \u300e\ud0c0\uc784 \ud2b8\ub798\ube14\ub7ec\uc988\u300f\uc758 PV(\uc9c0\ud558\ucca0\uc774 \ubb34\ub300\uc778 \ubc84\uc804) \ud6c4\ubc18\uc5d0 \uc788\ub358 \uc2dc\uacc4\ud0d1\uc5d0 \uc11c \uc788\ub294 \ubbf8\ucf54\ud1a0 \uc7a5\uba74\uc740 \uc774 \uc7a5\uba74\uc774\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP361_ja.cfg.bin#3": "\uc2dc\uac04\uc5ec\ud589\uc774 \ubd88\uac00\ub2a5\ud558\ub2e4\ub294 \uc99d\uba85\uc73c\ub85c \u300e\ud604\ub300\uc5d0 \ubbf8\ub798\uc5d0\uc11c \uc628 \uc2dc\uac04\uc5ec\ud589\uc790\uac00 \uc624\uc9c0 \uc54a\uc558\uae30 \ub54c\ubb38\uc774\ub2e4\u300f\ub77c\ub294 \uc124\uc774 \uc788\ub2e4. \uc774\uc5d0 \ub300\ud55c \ubc18\ub860\uc740 \u300e\ud0c0\uc784\uba38\uc2e0\uc774 \ubc1c\uba85\ub418\uae30 \uc774\uc804\uc758 \uc2dc\uac04\uc73c\ub85c\ub294 \uc2dc\uac04\uc5ec\ud589\ud560 \uc218 \uc5c6\ub2e4. \ub530\ub77c\uc11c \ud604\uc7ac\uc5d0 \ubbf8\ub798\uc5d0\uc11c \uc628 \uc2dc\uac04\uc5ec\ud589\uc790\uac00 \uc624\uc9c0 \uc54a\ub294 \uac83\uc740 \ub2f9\uc5f0\ud558\ub2e4\u300f\ub294 \uac83\uc774\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP362_ja.cfg.bin#3": "\u300e\ud0c0\uc784 \ud2b8\ub798\ube14\ub7ec\uc988\u300f\uc758 \uc2dc\uac04\uc5ec\ud589\uc5d0\ub3c4 \ud0c0\uc784\uba38\uc2e0\uc758 \ucd9c\uad6c(\ub85c\uc2a4\ud2b8 \ud640)\uac00 \uc0dd\uae30\ub294 2013\ub144\uae4c\uc9c0\ub9cc \uac08 \uc218 \uc788\ub2e4\ub294 \uc81c\uc57d\uc744 \ub450\uc5c8\ub2e4. \uc989 \uc548\ud0c0\uae5d\uac8c\ub3c4 \uacf5\ub8e1\uc744 \ub9cc\ub098\ub7ec \uac08 \uc218\ub294 \uc5c6\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP363_ja.cfg.bin#3": "\uace0\uc591\uc774\uc758 \uc774\ub984\uc77c \ubfd0 \uc544\ub2c8\ub77c \ud398\ud2b8\ub85c\ub2c8\uc6b0\uc2a4(\ud53c\ud2b8)\ub294 \ub0a8\uc131 \uc774\ub984\uc774\ub2e4. \uc5ec\uc131\uc758 \ubaa8\uc2b5\uc744 \ud55c \uadf8\ub140\uac00 \uc2eb\uc5b4\ud558\ub294 \uac83\ub3c4 \ub2f9\uc5f0\ud558\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP364_ja.cfg.bin#3": "\uce74\uc774\uac00 \uae30\ub974\ub358 \ud53c\ud2b8\ub294 \ubbf8\ucf54\ud1a0\uac00 2031\ub144\uc5d0 \ud0dc\uc5b4\ub09c \uc2dc\uc810\uc5d0 \uc774\ubbf8 \uc0ac\ub77c\uc84c\uc73c\ubbc0\ub85c, \uc774\ub54c\uc758 \ubbf8\ucf54\ud1a0\ub294 \uc544\uc9c1 \ud53c\ud2b8\ub77c\ub294 \uc774\ub984\uc758 \uace0\uc591\uc774\ub97c \ubaa8\ub978\ub2e4. \uc774 \ub4a4 \ubbf8\ucf54\ud1a0\ub294 \uace0\uc591\uc774\ub97c \uae30\ub974\uac8c \ub418\uace0 \u300e\uc544\ube44\ud130\u30fb\ud398\ud2b8\ub85c\ub2c8\uc6b0\uc2a4\uff1d\ud53c\ud2b8\u300f\ub77c\uace0 \uc774\ub984 \ubd99\uc778\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP365_ja.cfg.bin#3": "\uc2dc\ub098\ub9ac\uc624 \ucd08\ubc18 \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc2dc\uc791 \uc9c0\uc810\uc774 \ud604\ub300\uc758 \ub86f\ud3f0\uae30 \uad50\ucc28\ub85c\uc600\ub2e4. \uadf8\ub7ec\ub2e4 \uc5ec\ub7ec \uc77c\uc774 \uc788\uc5b4 \uc5b4\ub290\uc0c8 \ubbf8\ub798\uc758 \uc2dc\ubd80\uc57c\ub85c\u2026\u2026\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP366_ja.cfg.bin#3": "\uc774 \ubbf8\ucf54\ud1a0\ub294 \uc2dc\uac04\uc5ec\ud589 4\ud68c\uc9f8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP367_ja.cfg.bin#3": "\ub85c\uc2a4\ud2b8 \ud640\uc774\ub77c\ub294 \uba85\uce6d\uc5d0\ub294 \uc5ec\ub7ec \ud6c4\ubcf4\uac00 \uc788\uc5c8\uace0\u2026\u2026\\n\ub85c\uc2a4\ud2b8 \ud574\ud508, \uac8c\uc774\ud551 \ub85c\uc2a4\ud2b8, \ud734\uc988 \uac8c\uc774\ud504, \ub0ab\uc2f1 \ub808\ud504\ud2b8\u2026\u2026 \ud558\uc9c0\ub9cc \uacb0\uad6d \ucc98\uc74c \uc0dd\uac01\ud55c \ub85c\uc2a4\ud2b8 \ud640\ub85c \uacb0\uc815\ub410\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP368_ja.cfg.bin#3": "PCE\uac00 \ub4e4\uc5b4\uac00\uba74 \uad49\uc7a5\ud788 \uac8c\uc784\ub2e4\uc6cc\uc9c0\uc8e0. \ud558\uc9c0\ub9cc PCE \ub3c4\uc785\uc740 \uc2dc\ub098\ub9ac\uc624\ub97c \uc0c1\ub2f9\ud788 \uc4f4 \ub4a4\uc5d0 \uacb0\uc815\ub410\uc2b5\ub2c8\ub2e4. \uadf8\uc804\uae4c\uc9c0\ub294 \uc120\ud0dd\uc9c0\ub9cc \uc788\ub294 \uac8c\uc784\uc774\uc5c8\uc2b5\ub2c8\ub2e4.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP369_ja.cfg.bin#3": "\uc774 \uc7a0\ub4e4\uc5b4 \uc788\ub294 \ubbf8\ucf54\ud1a0\ub294 \uc2dc\uac04\uc5ec\ud589 5\ud68c\uc9f8\ub2e4. \ub208\uc744 \ub72c \ub4a4 \ud0c0\ub9c8 \uc778\ud615 \ud0c8\uc744 \uc785\uace0 \ud788\ub098, \ub8e8\uc0c1\uce58\u2606\ub9e8, \uce74\ubbf8\uc57c \uc55e\uc5d0 \ub098\ud0c0\ub098 \uc774\uc57c\uae30\uc758 \ub9c8\uc9c0\ub9c9 \ubb34\ub835 \uc2a4\ucf08\ub808\ud1a4\uc5d0\uac8c \ub300\ub4e4\uac8c \ub41c\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP370_ja.cfg.bin#3": "\uc2dc\ub098\ub9ac\uc624 \ucd08\uae30\uc5d0\ub294 \uace0\ub4f1\ud559\uc0dd \ud3b8\uc5d0\uc11c \uac8c\uc784\uc774 \uc2dc\uc791\ub410\ub2e4. \uc720\ub9ac\uc758 \ub3c5\ubc31\uc73c\ub85c \uc2dc\uc791\ud558\ub294 \uac83\ub3c4 \uc88b\uc544\ud588\uc9c0\ub9cc, \uc218\uc218\ud558\uae34 \ud588\uc9c0\ub9cc\u2026\u2026\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP371_ja.cfg.bin#3": "\ud0c0\uc784 \ud2b8\ub798\ube14\ub7ec\uc988\uc758 \ud070 \uc8fc\uc81c \uc911 \ud558\ub098\uac00 \uc790\uae30\ud76c\uc0dd\uc774\ub2e4. \uadf8\ub807\uae30\uc5d0 \ud76c\uc0dd\uc73c\ub85c \uc9c0\ucf1c\uc9c4 \ucabd\uc758 \uac10\uc815\uacfc \uace0\ub1cc\ub3c4 \uadf8\ub9ac\uace0 \uc2f6\uc5c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP372_ja.cfg.bin#3": "\uc774 \ubbf8\ucf54\ud1a0\ub294 3\ud68c\uc9f8\u2026\u2026 \ub8e8\uc0c1\uce58\u2606\ub9e8 \ud3b8\uc5d0 \ub4f1\uc7a5\ud558\ub294 \ubbf8\ucf54\ud1a0\ub2e4. 2\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uac00 \uc2e0\ub3c4\ub97c \ucad3\uc544 \ub7a9\uc5d0 \ub4e4\uc5b4\uac14\uc9c0\ub9cc 20\uc2dc\uac00 \ub418\uc5b4 \uc6d0\ub798 \uc2dc\uac04\uc73c\ub85c \ub3cc\uc544\uac00\uace0, \uc548\uc744 \ud0d0\uc0c9\ud558\ub358 \uc911 \uc625\uc0c1\uc73c\ub85c \ub098\uc640 \ubc84\ub9b0 \uac83\uc774\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP373_ja.cfg.bin#3": "\uc774 \uc7a5\uba74\uc744 \uc37c\uc744 \ub54c\ubd80\ud130 \ub9c8\uc9c0\ub9c9\uc740 \uc5ec\uae30\ub85c \uc774\uc5b4 \uac00\ub824\uace0 \uc0dd\uac01\ud588\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP374_ja.cfg.bin#3": "\ud50c\ub86f \ub2e8\uacc4\uc5d0\uc11c\ub294 \uacfc\ud559\ubd80\uac00 \uc544\ub2c8\ub77c \ud638\ub7ec \uc5f0\uad6c\ud68c\uc600\ub2e4. \ub0b4\uc6a9\ub3c4 \ud559\uad50 \uad34\ub2f4 \uac19\uc740 \uac83\uc744 \uc0dd\uac01\ud558\uace0 \uc788\uc5b4\uc11c\u2026\u2026 \ub7a9\\n\uc73c\ub85c \uce68\uc785\ud558\ub294 \ubd80\ubd84\uc5d0 \uadf8 \ud754\uc801\uc774 \ub0a8\uc544 \uc788\ub2e4.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP375_ja.cfg.bin#3": "\ubbf8\ucf54\ud1a0\ub97c \ucc98\uc74c \uad6c\uc0c1\ud588\uc744 \ub54c\ub294 \uaf64 \ud3c9\ubc94\ud55c \uc5ec\uc790\uc544\uc774\uc600\ub2e4. \uc608\ub97c \ub4e4\uba74 \ud1b5\ud559 \uc790\uc804\uac70 \uac19\uc740 \ub290\ub08c\uc774\ub2e4. \uc774\uc2dc\uc774 \uc528\uac00 \uc880 \ub354 \uac1c\uc131 \uc788\uac8c \ud574 \ub2ec\ub77c\uace0 \uc694\uccad\ud574\uc11c \ud604\uc7ac\uc758 \uce90\ub9ad\ud130\uac00 \ub418\uc5c8\ub2e4. \ud1b5\ud559 \uc790\uc804\uac70\uc5d0\uc11c \ub864\ub7ec\ucf54\uc2a4\ud130\ub85c \uc774\ubbf8\uc9c0\uac00 \ubc14\ub010 \uc148\uc774\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP376_ja.cfg.bin#3": "\ud655\uc2e4\ud788 \uac00\ud0c0\uce74\ub098\ub85c \ub300\uc0ac\ub97c \uc37c\uc9c0\ub9cc, \uc774\ub807\uac8c \uc2ec\ud55c \ud1a0\ub9c9\ub9d0\ub85c \ub9cc\ub4e4 \uc904\uc740 \ubab0\ub790\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP377_ja.cfg.bin#3": "\ucc98\uc74c \ud50c\ub86f\uc5d0\uc11c\ub294 \uce74\ucf00\ub8e8\uc758 \uc544\ubc84\uc9c0\uac00 \uc758\uc0ac\uc600\uace0, \ud14c\ub7ec\ub85c \uc751\uae09 \ud658\uc790\uac00 \ub118\uce58\ub294 \ubcd1\uc6d0\uc744 \ubb34\ub300\ub85c \ud55c ER \ud3b8\uc774 \uc788\uc5c8\ub2e4.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP378_ja.cfg.bin#3": "\uc2e0\ub3c4\uc758 \ubaa9\uc18c\ub9ac, \uba4b\uc9c0\uc8e0. \uc774\uac74 \uc2dc\ub178\ud558\ub77c \uad70\uc774 \uc544\ub2c8\uc5b4\ub3c4 \uacb0\ud63c \uc790\uae08\uc744 \ubaa8\uc73c\uaca0\uc5b4\uc694.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP379_ja.cfg.bin#3": "\ub9c8\uc9c0\ub9c9\uc744 \ud5a5\ud55c \uc791\uc740 \ubcf5\uc120\uc774\uc8e0.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP380_ja.cfg.bin#3": "\uc9e7\uac8c \ub9d0\ud558\uba74, 428\uc774\uc8e0. \uc5ed\uc2dc \uadf8\ub807\ub124\uc694.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP381_ja.cfg.bin#3": "\uc774\ud1a0 \uc9f1\uc774 \uacf5\uc791\uc6d0\uc774\ub77c\ub294 \uac83\ub3c4 \ucc98\uc74c\ubd80\ud130 \uc815\ud574\uc838 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ud000\ud140 \uc5d0\ub108\uc9c0\ub97c \uc678\uad6d\uc774 \ub178\ub9ac\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\ub3c4 \uc774\uc0c1\ud55c \uc774\uc57c\uae30\uace0\uc694.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP382_ja.cfg.bin#3": "\uc774\ub7f0 \ub9d0\uc744 \ub4e3\uace0 \uc6c3\uc74c\uae4c\uc9c0 \ubc1b\uc73c\uba74 \uc88b\uc544\ud558\uac8c \ub418\uc8e0. \uc5ed\uc2dc\uc694. \uc81c\uac00 \uace0\ub4f1\ud559\uc0dd\uc774\uc5c8\ub2e4\uba74 \ubc14\ub85c \uc88b\uc544\ud588\uc744 \uac81\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP383_ja.cfg.bin#3": "\uc774\ub7f0 \ub9d0\uc744 \uc544\ubb34\ub807\uc9c0 \uc54a\uac8c \ud560 \uc218 \uc788\ub294 \uc5b4\ub978\uc774 \ub418\uace0 \uc2f6\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP384_ja.cfg.bin#3": "\ubaa8\ub4e0 \uac83\uc744 \uc54c\uac8c \ub41c \ub4a4 \uc774\uacf3\uc5d0\uc11c \uc774\ud1a0\uc57c\ub9c8\uc758 \ub300\uc0ac\ub97c \ub4e4\uc73c\uba74 \ubb50\ub77c\\n\ub9d0\ud560 \uc218 \uc5c6\ub294 \uae30\ubd84\uc774 \ub4e4\uc9c0 \uc54a\uc744\uae4c\uc694?\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP385_ja.cfg.bin#3": "\uc2a4\ucf08\ub808\ud1a4\uc774\ub77c\ub294 \uc774\ub984\uc740 \uc774\uc2dc\uc774 \uc528\uac00 \uc9c0\uc5c8\uc2b5\ub2c8\ub2e4. \ubbf8\uad6d \ub9cc\ud654\ud48d\uc774\uace0 \ud574\uace8 \ub9c8\uc2a4\ud06c\uac00 \uba4b\uc9c0\ub2e4\ub294 \uc774\uc720\uc600\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub984\uc758 \uc758\ubbf8\uae4c\uc9c0 \uc815\ud574\uc9c4 \uac83\uc740 \uc544\ub2c8\uc5b4\uc11c\u2026\u2026 \uc5b4\ub5bb\uac8c \uc2a4\ud1a0\ub9ac\uc5d0 \ub179\uc5ec \ub123\uc744\uc9c0 \uc0dd\uac01\ud558\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP386_ja.cfg.bin#3": "\ud788\ub098\uc758 \ub0a8\uc790\uce5c\uad6c\uac00 \uc2a4\ucf08\ub808\ud1a4\uc774\ub77c\ub294 \uac78 \uc5b8\uc81c\ucbe4 \ub208\uce58\ucc44\uc168\ub098\uc694?\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP387_ja.cfg.bin#3": "\uc774 \uce74\ub4dc \uac8c\uc784\uc740 \uc774\uc2dc\uc774 \uc528\uac00 \uace0\uc548\ud55c \uac83\uc785\ub2c8\ub2e4. \uc77c\ubc18 \ud2b8\ub7fc\ud504\ub85c\ub3c4 \ud560 \uc218 \uc788\uc73c\ub2c8 \uaf2d \uc5ec\ub7ec\ubd84\ub3c4 \ud574 \ubcf4\uc138\uc694.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011\u3000\ub3cc\ud30c\uad6c\ub97c \ucc3e\ub4ef \uae09\ud558\uac8c \uc0dd\uac01\ud574 \ub0b8 \uc624\ub9ac\uc9c0\ub110 \uce74\ub4dc \uac8c\uc784\uc785\ub2c8\ub2e4. \ud544\uc2b9\ubc95\uc774 \uc788\uc744 \ub4ef\ud558\uba74\uc11c\ub3c4 \uc5c6\uc2b5\ub2c8\ub2e4. \uc815\uc11d\uc5d0 \uc9d1\ucc29\ud558\uba74 \ud5c8\ub97c \ucc14\ub9bd\ub2c8\ub2e4. \uc0ac\uc2e4 \uadf8\ub7f0 \uade0\ud615\uc758 \uac8c\uc784\uc785\ub2c8\ub2e4.\u3010\uc774\uc2dc\uc774\u3011",
    "TIP388_ja.cfg.bin#3": "\uc774\ub54c \ucc98\uc74c\uc73c\ub85c \uc2dc\uac04\uc5ec\ud589\uc744 \ud55c \uac83\uc774\ub2e4. \ubbf8\ucf54\ud1a0\ub294 3\ud68c\uc9f8\ubd80\ud130 \uc2dc\uac04\uc5ec\ud589\uc758 \uad6c\uc870\ub97c \uc774\ud574\ud558\uae30 \uc2dc\uc791\ud55c\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP389_ja.cfg.bin#3": "\uadf8\ub807\uc2b5\ub2c8\ub2e4. \uc6b4\uba85\uc740 \uc9c0\uae08 \uadf8\uacf3\uc5d0 \uc788\ub294 \ub2f9\uc2e0\uc774 \uacb0\uc815\ud558\uace0 \uc788\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP390_ja.cfg.bin#3": "\uc2e0\ub3c4\ub294 \ud154\ub808\ube44\uc804\uc744 \uac70\uc758 \ubcf4\uc9c0 \uc54a\ub294 \ub0a8\uc790\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud154\ub808\ube44\uc804\uc5d0 \ud788\ub098\uac00 \ub098\uc624\ub294 \uac83\ub3c4 \ubab0\ub790\uc2b5\ub2c8\ub2e4. \uac8c\ub2e4\uac00 \uc5f0\uad6c \uc678\uc5d0\ub294 \ubcc4\ub85c \uad00\uc2ec\uc774 \uc5c6\uc5b4\uc11c, \ud154\ub808\ube44\uc804\uc5d0\uc11c \ud788\ub098\ub97c \ubd10\ub3c4 \u300e\ubb54\uac00 \uc798 \ub2ee\uc740 \uc5ec\uc790\ub124\u300f \uc815\ub3c4\ub85c \ub118\uacbc\uc744\uc9c0\ub3c4\uc694.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP391_ja.cfg.bin#3": "\u300e\uc6d0\ub798 \uc138\uacc4\uc758 \ubbf8\ub798\uc5d0\uc11c \ub098\ub294 \ubbf8\ucf54\ud1a0\uac00 \ub9cc\ub4e4\uc5c8\ub2e4\u2026\u2026\u300f\ub77c\ub294\\n\uc2dd\uc758 \ub9d0\uc744 \ub4e4\uc740 \uac83\uc785\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP392_ja.cfg.bin#3": "\uce74\ubbf8\uc57c\uc5d0 \ub300\ud574 \uc0ac\uc640\ud0a4\ub294 \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \ube44\uc815\uc0c1\uc801\uc778 \uc9d1\ub150\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4. \uc65c \uadf8\ub807\uac8c\uae4c\uc9c0 \ud588\ub294\uc9c0\uc5d0 \ub300\ud574\uc11c\ub294, \uc0ac\ub791\uacfc\\n\uc99d\uc624\ub294 \uc885\uc774 \ud55c \uc7a5 \ucc28\uc774\uc774\uae30 \ub54c\ubb38\uc774\ub77c\uace0\ubc16\uc5d0 \ub2f5\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP393_ja.cfg.bin#3": "\uc5ec\uae30\uc11c\ubd80\ud130\uc758 \uc804\uac1c\uac00 \uc791\ud488 \uc804\uccb4\uc5d0\uc11c \ub3d9\ub5a8\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2d0\uae4c\u2026\u2026\ub77c\uace0 \uc0dd\uac01\ud55c \uc801\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\ucd9c\uc758 \ud798\uc73c\ub85c \ub05d\uae4c\uc9c0 \ud574\ub0bc \uac83\uc774\ub77c \ubbff\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP394_ja.cfg.bin#3": "\uc774 \ubd80\ubd84\ub3c4 \uac8c\uc784\uc774 \ub41c \ubaa8\uc2b5\uc744 \ubcf4\uae30 \uc804\uae4c\uc9c0\ub294 \uc815\ub9d0 \ub9c8\uc74c\uc744 \uc878\uc600\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc7a5\ub09c\uc73c\ub85c \uc4f4 \uac83\uc740 \uc544\ub2c8\uc5d0\uc694. \uc9c4\uc9c0\ud558\uac8c \uc37c\uc2b5\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP395_ja.cfg.bin#3": "\uc18c\ub984 \ub3cb\ub124\uc694.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP396_ja.cfg.bin#3": "\ubb3c\ub860 \ud3c9\ubc94\ud558\uac8c \uc2f8\uc6e0\ub2e4\uba74 \uadf8\ub798\ub3c4 \ube45 \ud578\ub4dc\uac00 \uc774\uacbc\uc744 \uac81\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uace0\ub3c5\ud55c \ub0a8\uc790\ub780 \ub54c\ub85c \uc77c\ubd80\ub7ec \uc9c0\uace0 \uc2f6\uc5b4\uc9c0\ub294 \ubc95\uc785\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP397_ja.cfg.bin#3": "\uc5ec\uae30\uc758 \ubbf8\ucf54\ud1a0\ub294 5\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub2e4. \uc720\ub9ac\ub294 \uc774\ubbf8 6\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uc5d0\uac8c \uc625\uc0c1\uc5d0\uc11c \u300e\uc88b\uc544\ud558\ub2c8\uae4c\u300f\ub77c\ub294 \ub9d0\uc744 \ub4e4\uc740 \uc0c1\ud0dc\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP398_ja.cfg.bin#3": "\uc720\ub9ac\uac00 \ub9cc\ub098\uace0 \uc788\ub294 \ubbf8\ucf54\ud1a0\ub294 1\ud68c\uc9f8, 3\ud68c\uc9f8, 5\ud68c\uc9f8, 6\ud68c\uc9f8\ub2e4. \uce74\ubbf8\uc57c\uac00 \uacc4\uc18d \ud568\uaed8 \uc788\uc5c8\ub358 \uac83\uc740 4\ud68c\uc9f8\ub2e4. \ud655\uc2e4\ud788 4\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\uac00 \uac00\uc7a5 \uae4a\uc774 \uace0\ubbfc\ud588\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP399_ja.cfg.bin#3": "\uc774\ub984\uc5d0 \u2606\ub97c \ub123\uc790\ub294 \uac83\uc740 \uc774\uc2dc\uc774 \uc528\uc758 \uc544\uc774\ub514\uc5b4\uc600\uc9c0\ub9cc, \uc5b4\ub5bb\uac8c\ub4e0 \uc2a4\ud1a0\ub9ac\uc0c1 \uc758\ubbf8\uac00 \uc788\ub294 \uac83\uc73c\ub85c \ub9cc\ub4e4\uace0 \uc2f6\uc5b4\uc11c \uc774\ub7f0 \uc7a5\uba74\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ub8e8\uc0c1\uce58\u2606\ub9e8\uc758 \ucd5c\ud6c4\ub294 \uc88b\uc544\ud558\ub294 \uc7a5\uba74 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP400_ja.cfg.bin#3": "\uacc4\uc18d \ucfe8\ud558\uac8c \ud589\ub3d9\ud558\ub358 \uc2e0\ub3c4\uac00 \uc5ec\uae30\uc11c \ucc98\uc74c\uc73c\ub85c \uc790\uc2e0\uc758 \uac10\uc815\uc744 \ud138\uc5b4\ub193\uae30 \uc2dc\uc791\ud569\ub2c8\ub2e4. \uc815\ub9d0 \uc88b\uc544\ud558\ub294 \uc7a5\uba74\uc785\ub2c8\ub2e4.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
})

OVERRIDES["tip.json"].update({
    "TIP401_ja.cfg.bin#3": "\uc2e0\ub3c4\ub294 \uc5ec\uae30\uc11c\ubd80\ud130 \ub354\uc6b1 \uba4b\uc788\uc5b4\uc9c0\uc8e0.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP402_ja.cfg.bin#3": "\uc5ec\uae30\uc11c \ud788\ub098\ub294 \uc190\ubaa9\uc2dc\uacc4\ub97c \ucc28\uace0 \uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc989 \ubbf8\ucf54\ud1a0\uc5d0\uac8c \uc190\ubaa9\uc2dc\uacc4\uac00 \uc5b4\uba38\ub2c8\uc758 \uc720\ud488\uc73c\ub85c \uc804\ud574\uc9c0\uc9c0 \uc54a\uac8c \ub429\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uba74 \uc65c \ud788\ub098\uac00 \uc190\ubaa9\uc2dc\uacc4\ub97c \uac00\uc9c0\uace0 \uc788\uc5c8\ub294\uac00. \uadf8\uac83\uc774 \ub9c8\uc9c0\ub9c9\uc758 \u300e\ub9c8\uc9c0\\n\ub9c9\uc758 \uc870\uac01\u300f\uc774 \ub418\ub294 \uac83\uc785\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP403_ja.cfg.bin#3": "\uc778\uac04\uc774 \uc544\ub2cc \uadf8\ub140\uac00 \ub9d0\ud558\uae30 \ub54c\ubb38\uc5d0 \ubb34\uac8c \uc788\ub294 \ub9d0\uc774 \ub429\ub2c8\ub2e4.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP404_ja.cfg.bin#3": "\uc774\ucbe4 \ub418\uba74 \uadf8\ub140\uc758 \ubaa8\ub378\uc744 \ub208\uce58\ucc48 \uc0ac\ub78c\ub3c4 \uc788\uaca0\uc9c0\uc694. \uc54c\uace0 \ub098\uc11c \uadf8\ub140\uc758 \ubaa8\uc2b5\uc744 \ubcf4\uba74\u2026\u2026 \ud3ed\uc18c\ud558\uc9c0 \uc54a\ub098\uc694?\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP405_ja.cfg.bin#3": "\uc790, \uc5ec\uae30\uc11c\ubd80\ud130\uc758 \uc804\uac1c\uac00 \uc0ac\uc2e4 \uc4f0\uba74\uc11c \uac00\uc7a5 \uace0\ubbfc\ud588\ub358 \ubd80\ubd84\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc774\uc57c\uae30\ub85c\ub294 \ubbf8\ucf54\ud1a0\uac00 \uacb0\uc2ec\ud558\uace0 \ub2e8\uc228\uc5d0 \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \ud758\ub7ec\uac00\ub294 \uac83\uc774 \ub9de\uc9c0\ub9cc\u2026\u2026. \uc800\ub294 \uc5b4\ub5a4 \uc810\uc5d0 \uac78\ub9ac\uace0 \ub9d0\uc558\uc2b5\ub2c8\ub2e4(\uacc4\uc18d).\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP406_ja.cfg.bin#3": "\ubaa8\ub378\uc774 \ubaa8\ub378\uc774\ub2c8 \ub2f9\uc5f0\ud788 \ubb34\uc11c\uc6b8 \uc218\ubc16\uc5d0 \uc5c6\uaca0\uc9c0\uc694.\\n\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP407_ja.cfg.bin#3": "(\uacc4\uc18d) \uc8fc\uc778\uacf5\uc774 \uc5f0\uc778\uc774\ub098 \uac00\uc871\uc744 \uad6c\ud558\uae30 \uc704\ud574 \uc2dc\uac04\uc744 \ub2e4\uc2dc \uc4f4\ub2e4. \uc2dc\uac04\uc5ec\ud589\uc744 \ub2e4\ub8ec \uc791\ud488\uc5d0\ub294 \uadf8\ub7f0 \uc804\uac1c\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub0af\uc120 \ud0c0\uc778\uc758 \uc2dc\uac04\uae4c\uc9c0 \ud568\uaed8 \ubc14\uafb8\ub294 \uac83\uc774 \uc633\uc740\uc9c0\uc5d0 \ub300\ud574 \uae4a\uc774 \uc0dd\uac01\ud55c \uc791\ud488\uc740 \ubcc4\ub85c \uc5c6\uc5c8\ub358 \uac83 \uac19\uc2b5\ub2c8\ub2e4(\uacc4\uc18d).\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP408_ja.cfg.bin#3": "(\uacc4\uc18d) \uc790\uae30 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\ub9cc\uc744 \uc704\ud574 \uc2dc\uac04\uc744 \ubc14\uafd4\ub3c4 \ub418\ub294\uac00. \uadf8\uac83\uc774 \uc81c\uac00 \ub9c8\uc9c0\ub9c9\uc744 \uc4f0\uba74\uc11c\\n\uac78\ub838\ub358 \uc810\uc785\ub2c8\ub2e4. \uc798\ubabb\ub41c \uc2dc\uac04\uc774\ub77c\uace0 \ud574\ub3c4 \uc18c\uc911\ud788 \uc5ec\uae30\ub294 \uc0ac\ub78c\uc740 \uc788\uc744 \uac83\uc785\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uce74\ubbf8\uc57c\uc640 \ub8e8\uc0c1\uce58\u2606\ub9e8\uc774 \uadf8\ub7ac\uc2b5\ub2c8\ub2e4(\uacc4\uc18d).\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP409_ja.cfg.bin#3": "(\uacc4\uc18d) \uc18c\uc911\ud55c \uc0ac\ub78c\uc744 \uad6c\ud558\uae30 \uc704\ud55c \uc77c\uc774\ub77c\ub3c4 \ub9ce\uc740 \uc0ac\ub78c\uc744 \ub04c\uc5b4\ub4e4\uc774\ub294 \uac83\uc774\ub77c\uba74 \uc633\ub2e4\uace0 \ub2e8\uc5b8\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \uc989 \ub9ce\uc740 \uc0ac\ub78c\uc744 \ub04c\uc5b4\ub4e4\uc774\uc9c0 \uc54a\uae30 \uc704\ud574 \uc2dc\uac04\uc5ec\ud589\uc744 \ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uc0ac\ub78c\ub3c4 \uc788\uc9c0 \uc54a\uc744\uae4c\u2026\u2026 \uc774\uac83\uc774 \uc5ec\uae30\uae4c\uc9c0 \uc4f0\uace0 \ub3c4\ub2ec\ud55c \uacb0\ub860\uc774\uc5c8\uc2b5\ub2c8\ub2e4(\uacc4\uc18d).\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP410_ja.cfg.bin#3": "(\uacc4\uc18d) \uc808\ub300 \uc633\ub2e4\uace0 \ub2e8\uc5b8\ud560 \uc218 \uc5c6\ub294 \uae38\uc774\uae30\uc5d0 \uac08\ub4f1\uc774 \uc788\uace0, \uac08\ub4f1\uc774 \uc788\uc5c8\uae30\uc5d0 \uc120\ud0dd\ud55c \uae38\uc5d0 \uc758\ubbf8\uac00\\n\uc788\uc2b5\ub2c8\ub2e4. \ud6cc\ub96d\ud55c \uc5f0\ucd9c\ub3c4 \ub354\ud574\uc838 \ub208\ubb3c \uc5c6\uc774\ub294 \ubcfc \uc218 \uc5c6\ub294 \uc7a5\uba74\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP411_ja.cfg.bin#3": "\uc0ac\uc2e4 \uc5b4\ub290 \uc120\uc0dd\ub2d8 \uac8c\uc784\uc758 \uc18d\ud3b8 \ud788\ub85c\uc778\uc73c\ub85c \uc0ac\uc6a9\ud588\ub358 \uc774\ub984\uc785\ub2c8\ub2e4. \uc18d\ud3b8\uc774 \ub098\uc624\uc9c0 \uc54a\uac8c \ub418\uc5b4 \uc5ec\uae30\uc11c \ube5b\uc744 \ubcf4\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uae30\ud0c0\uc9c0\ub9c8\u3011",
    "TIP412_ja.cfg.bin#3": "\ub85c\uc2a4\ud2b8 \ud640\uc774\ub77c\ub294 \ud638\uce6d\uc740 \uc77c\ub2e8 \uac00\uce6d\uc73c\ub85c \uc0ac\uc6a9\ud588\ub358 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc5ec\ub7ec \ubc88 \ub4e3\ub2e4 \ubcf4\ub2c8 \uc9c0\ub098\uce58\uac8c \ud280\uc9c0 \uc54a\uc544 \uc2a4\ud1a0\ub9ac\uc5d0 \uc798 \uc5b4\uc6b8\ub9b0\ub2e4\ub294 \uc758\uacac\uc774 \ub098\uc654\uace0, \uadf8\ub300\ub85c \ucc44\ud0dd\ub41c \uac83\uc73c\ub85c \uae30\uc5b5\ud569\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP413_ja.cfg.bin#3": "\uae30\ub3d9 \uc218\uc0ac\ub300\uc640 \uc218\uc0ac \uc81c1\uacfc \ud2b9\uc218\ubc94 \uc218\uc0ac\uacc4(SIT)\ub97c \uc11e\uc740 \ub4ef\ud55c \ubd80\uc11c\ub85c \ucc3d\uc791\ud588\uc9c0\ub9cc, \ub274\uc695 \uc2dc\uacbd\uc5d0\ub294 \uc2e4\uc81c\ub85c Emergency Service Squad\ub77c\ub294 \ubd84\ub300\uac00 \ud3b8\uc131\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc81c\uac00 \uacfc\uac70\uc5d0 \uc774 \uc0ac\uc2e4\uc744 \uc77d\uc5b4 \ub450\uc5b4 \uae30\uc5b5 \uc5b4\ub518\uac00\uc5d0 \ub0a8\uc544 \uc788\uc5c8\uc744 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP414_ja.cfg.bin#3": "\uc758\ubbf8\ub97c \ubaa8\ub974\uaca0\ub2e4\uba74 \ub85c\ubc84\ud2b8 A. \ud558\uc778\ub77c\uc778\uc758\\n\u300e\uc5ec\ub984\uc73c\ub85c \uac00\ub294 \ubb38\u300f\uc744 \uc77d\uc5b4 \ubcf4\uc2ed\uc2dc\uc624. \uc791\ud488 \uc18d\uc5d0 \uacfc\uac70\uc758 \uc5ec\ub7ec \uc2dc\uac04\uc5ec\ud589 \uc791\ud488\uc5d0 \ub300\ud55c \uc624\ub9c8\uc8fc\uac00 \ub098\uc624\ub294\ub370, \uc774\ub294 \ub514\ub809\ud130 \uc774\uc2dc\uc774 \uc9c0\ub85c \uc528\uc758 \ub9ac\uc2a4\ud399\ud2b8\uc758 \ud45c\ud604\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP415_ja.cfg.bin#3": "\ud574\uc678 \ub274\uc2a4\uc5d0\uc11c \ub2e4\ub904\uc9c4 \ub9ac\uc5bc \ub77c\uc774\ud504 \ud788\uc5b4\ub85c\ub4e4\uc758 \uc601\uc0c1\uacfc \uc0ac\uc9c4\uc744 \uc774\uc2dc\uc774 \uc528\uc640 \uae30\ud0c0\uc9c0\ub9c8 \uc528\uc5d0\uac8c \ubcf4\uc5ec \ub4dc\ub838\uc2b5\ub2c8\ub2e4. \uc7a5\ub09c\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \ud788\uc5b4\ub85c\ub4e4\uc758 \uc778\ud130\ubdf0 \ub4f1\uc744 \ub4e4\uc5b4 \ubcf4\uba74 \ub9e4\uc6b0 \uc9c4\uc9c0\ud55c \uc758\uacac\uc744 \ub9d0\ud558\uace0 \uc788\uc5b4, \uac1c\uc778\uc801\uc73c\ub85c \ud638\uac10\uc744 \ub290\uaf08\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP416_ja.cfg.bin#3": "\uc9c0\uc9c4 \uc7ac\ud574\uc640 \uc5d0\ub108\uc9c0 \uc815\ucc45 \ub4f1\uc758 \ud604\ud669\uc744 \uc791\ud488 \uc548\uc5d0 \ubc18\uc601\ud558\uace0 \uc2f6\ub2e4\ub294 \uac83\uc740 \ub514\ub809\ud130 \uc774\uc2dc\uc774 \uc528\uc758 \uc758\uc9c0\uc600\uaca0\uc9c0\uc694. \ucc98\uc74c\uc5d0\ub294 \ub3c4\ucfc4\uc5d0 \uac70\ub300\ud55c \ucd95\uc804 \uc2dc\uc2a4\ud15c\uc774 \uac74\uc124\ub418\uc5b4 \uc788\ub2e4\ub294 \ub4f1 \uc5d0\ub108\uc9c0\uc5d0 \uad00\ud55c \uc124\uc815\ub3c4 \uc788\uc5c8\uc9c0\ub9cc, \uadf8\ub807\uac8c\uae4c\uc9c0 \ud30c\uace0\ub4e0 \ud45c\ud604\uc740 \uc5c6\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP417_ja.cfg.bin#3": "\ub85c\ub110\ub4dc\u30fbL\u30fb\ub9ec\ub9bf \ubc15\uc0ac\uc758 \ud0c0\uc784\uba38\uc2e0 \uc774\ub860\uc744 \ub2e4\ub8e8\uace0 \uc2f6\ub2e4\ub294 \uc544\uc774\ub514\uc5b4\ub294 \uc774\uc2dc\uc774 \uc528\uc5d0\uac8c\uc11c \ub098\uc654\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc11c\ub458\ub7ec \uc815\ubcf4\ub97c \ub2e4\uc2dc \ubaa8\uc73c\uace0 \uc2a4\ud1a0\ub9ac\uc640 \uc124\uc815\uc744 \uc218\uc815\ud588\ub358 \uae30\uc5b5\uc774 \uc788\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP418_ja.cfg.bin#3": "\uc0ac\uc2e4 \ubbf8\ucf54\ud1a0\uc640 \uc720\ub9ac\uac00 \uacfc\ud559\ubd80\uc5d0\uc11c \uc81c\uc791\ud558\ub294 \ud30c\uc6cc \ub85c\ub354\uc778\ub370, \uc774 \uc544\uc774\ub514\uc5b4\uac00 \ub098\uc654\uc744 \ub54c \uc77c\ubcf8\uc5d0\uc11c \uac1c\ubc1c \uc911\uc778 \uc7ac\ud574 \ub300\ucc45 \uc7a5\ube44\uc778 \uad6c\uc870 \ub85c\ubd07 \ub4f1\uc5d0 \uad00\ud574 \uc774\uc57c\uae30\ud588\ub358 \uae30\uc5b5\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc9c0\uc9c4 \uc7ac\ud574 \uc774\uc57c\uae30\ub97c \ud53c\ud560 \uc218 \uc5c6\uc5c8\ub358 \uc2dc\uae30\uc600\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP419_ja.cfg.bin#3": "\uc6b0\uc8fc \uacf5\uac04\uc73c\ub85c \ub098\uac00\ub294 \uc6b4\ubc18 \uc218\ub2e8\uc778 \uada4\ub3c4 \uc5d8\ub9ac\ubca0\uc774\ud130\uac00 \ub3c4\ucfc4\ub9cc\uc5d0 \uc788\ub2e4\ub294 \uc544\uc774\ub514\uc5b4\uc640, \uadf8\uac83\uc740 \ub108\ubb34 \ube44\uc57d\uc801\uc774\ub77c\ub294 \uc758\uacac\\n\uc0ac\uc774\uc5d0\uc11c \ub17c\uc758\uac00 \ubc8c\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \ucd5c\uc885\uc801\uc73c\ub85c\ub294\\n\u300e\uc6b0\uc8fc \uc5d8\ub9ac\ubca0\uc774\ud130\u300f\ub77c\ub294 \uc560\uce6d\uc758 \uac70\ub300\ud55c \ud0dc\uc591\uad11 \ubc1c\uc804 \ud0c0\uc6cc\ub77c\ub294 \ud615\ud0dc\ub85c \uacb0\ub860\uc774 \ub0ac\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP420_ja.cfg.bin#3": "\uac1c\uc778\uc801\uc73c\ub85c \uc774 \uc758\uacac\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4. \ucc45\uc774\ub098 \uc7a1\uc9c0 \uceec\ub809\uc158\\n\uc740 \uc5c4\uccad\ub09c \ubb34\uac8c\uac00 \ub418\uc5b4 \ubc14\ub2e5\uc774 \ube60\uc9c0\uac70\ub098 \uc9d1\uc774 \uae30\uc6b8\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc885\uc774\uac00 \ucd5c\uace0\uc778\uc9c0 \uc544\ub2cc\uc9c0\ub294 \ubaa8\ub974\uaca0\uc9c0\ub9cc, \ucd5c\uac15\uc77c\uc9c0\ub3c4 \ubaa8\ub985\ub2c8\ub2e4. \uc544\ub2c8, \ucd5c\uc545\uc77c\uae4c\uc694?\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP421_ja.cfg.bin#3": "\uc5ec\ub7ec \uc791\ud488\uc5d0\uc11c \ud574\ud0b9 \ubb18\uc0ac\uac00 \ub098\uc624\uc9c0\ub9cc, \uc5ed\uc2dc \ud604\uc2e4\uac10 \uc788\ub294 \ud45c\ud604\uc744 \ud558\uae30\ub294 \uc5b4\ub835\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ub108\ubb34 \ud604\uc2e4\uc801\uc73c\ub85c \ub9cc\ub4e4\uba74 \ud50c\ub808\uc774\uc5b4\uac00 \uc758\ubbf8\ub97c \uc54c \uc218 \uc5c6\uac8c \ub418\uac70\ub098 \uc7a5\uba74\uc774 \uc7a5\ud669\ud574\uc9c0\uae30\ub3c4 \ud558\uace0\u2026\u2026 \ud654\ub824\ud558\uac8c \ub9cc\ub4e4\uba74 \ud604\uc2e4\uc801\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\uc744 \uac00\ub2a5\uc131\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP422_ja.cfg.bin#3": "\uc2e4\uc81c\ub85c\ub294 \uac00\ub2a5\uc131 \ub2e8\uacc4\uc5d0\uc11c \uacbd\uc2dc\uccad\uc774 \u300e\ud604\uc9c1 \ud615\uc0ac\uac00 \uad00\uc5ec\ud588\ub2e4\u300f\uace0 \ubc1c\ud45c\ud558\ub294 \uc77c\uc740 \uc5c6\uc744 \uac83\uc785\ub2c8\ub2e4. \uc774\ub294 \uc0ac\uc640\ud0a4 \ud55c \uc0ac\ub78c\uc758 \uc18c\ud589\uc774 \uc544\ub2c8\ub77c, \uacbd\uc2dc\uccad\uacfc \uc5b8\ub860 \ub0b4\ubd80\uc5d0 \uc788\ub358 \ud574\uace8 \ub3d9\uc870\uc790\ub4e4\uc774 \ud55c\ud328\uac00 \ub418\uc5b4 \ubc8c\uc778 \uc77c\uc774\ub77c\ub294 \uc124\uc815\uc785\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP423_ja.cfg.bin#3": "\uc2dc\ub178\ud558\ub77c \uc870\uc218\uac00 \uc774 \uc791\ud488\uc758 \ud788\ub85c\uc778\uc785\ub2c8\ub2e4. \ub2e4\ub9cc \uac1c\uc778\uc801\uc778\\n\uacac\ud574\uc774\ubbc0\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uac15\uc694\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP424_ja.cfg.bin#3": "\uc6b0\uc5f0\ud788\ub3c4 \uc800\uc640 \uac19\uc740 \uc774\ub984\uc758 \ud30c\ud2f0\uc2dc\uc5d0\uac00 \uc788\ub294 \ubaa8\uc591\uc774\ub124\uc694\uff08\uc6c3\uc74c\uff09. \uc800\ub294 \ub514\uc800\ud2b8 \uacc4\uc5f4 \ub0a8\uc790\ub77c\uace0 \uc790\uce6d\ud558\ub294 \ub2e8\uac83\uc744 \uc88b\uc544\ud558\ub294 \uc911\ub144\uc774\uc9c0\ub9cc, \ub9c8\uba54\uce78\uc774\ub098 \ud0c0\uc774\uc57c\ud0a4, \ub124\ub9ac\ud0a4\ub9ac \uac19\uc740 \ud654\uacfc\uc790\ub97c \ub354 \uc88b\uc544\ud569\ub2c8\ub2e4. \ub2e4\uc74c \uc0dd\uc5d0 \ub2e4\uc2dc \ud0dc\uc5b4\ub09c\ub2e4\uba74 \ud325\uc18c \uacf5\uc7a5\uc744 \uacbd\uc601\ud558\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP425_ja.cfg.bin#3": "\ub85c\uc2a4\ud2b8 \ud640\uc5d0\uc11c \ubc1c\uc0dd\ud55c \uc5d0\ub108\uc9c0\uc758 \uba85\uce6d \ud6c4\ubcf4\ub294 \uba87 \uac00\uc9c0\uac00 \uc788\uc5c8\ub358 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \u300e\uc30d\uc18c\uba78 \uc5d0\ub108\uc9c0\u300f\ub098 \u300e\uc560\ub2c8\ud790\ub808\uc774\uc158 \ud30c\uc6cc\u300f \ub4f1\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc5b4\ub290 \uac83\ub3c4 \uc369 \ub9c8\uc74c\uc5d0 \ub4e4\uc9c0 \uc54a\uc544, \ub9c9\uc5f0\ud558\uc9c0\ub9cc \uadc0\uc5d0 \uc775\uc740 \u300e\ud000\ud140\u300f\uc73c\ub85c \uacb0\uc815\ud588\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP426_ja.cfg.bin#3": "\uc77c\ubcf8\uc744 \uc88c\uc9c0\uc6b0\uc9c0\ud558\ub294 \uc5b4\ub460\uc758 \ud751\ub9c9 \uac19\uc740 \uc778\ubb3c\uc744 \ud55c \uba85\ub9cc \uc124\uc815\ud574\ub3c4 \uc88b\uc558\uaca0\uc9c0\ub9cc, \uadf8\ub7ec\uba74 \ub0a1\uc740 \uc2dc\ub300\uc758 \uc815\uce58\ub97c \ub2f5\uc2b5\ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc77c \uac83 \uac19\uc558\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud604\uc2e4\uc5d0\ub3c4 \uc788\uc744 \ubc95\ud55c \uc5d0\ub108\uc9c0 \uc815\ucc45\uc73c\ub85c \ud070 \uc601\ud5a5\ub825\uc774\ub098 \uad8c\ud55c\uc744 \uac00\uc9c4 \uc9c1\ucc45\uc744 \ub4f1\uc7a5\uc2dc\ud0a4\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP427_ja.cfg.bin#3": "\u300e\ubb3c\uc9c8\uacfc \uc815\ubcf4\uc758 \uc2dc\uac04 \ub3c4\uc57d\uc5d0 \uad00\ud55c \uace0\ucc30\u300f\uc774\ub77c\ub294 \ub17c\ubb38\uc758 \uc77c\ubd80\ub77c\ub294 \uc124\uc815\uc785\ub2c8\ub2e4. \uc2a4\ud1a0\ub9ac \uc791\uc131 \ucd08\uae30\uc5d0 \u300e\uc77c\ub2e8 \uc784\uc2dc\ub85c \uc4f4 \ubb38\uc7a5\u300f\uc73c\ub85c \uc791\uc131\ud588\ub358 \uae30\uc5b5\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc124\uc815\uc740 \uc5ec\ub7ec \uac00\uc9c0\ub85c \ubcc0\uacbd\ub418\uc5c8\uc9c0\ub9cc, \ucd5c\uc885\uc801\uc73c\ub85c \ub2e4\uc2dc \uc77d\uc5b4 \ubcf4\ub2c8 \ubb38\uc81c\uac00 \uc5c6\uc5b4 \uadf8\ub300\ub85c \ud65c\uc6a9\ud558\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP428_ja.cfg.bin#3": "\uc2e4\ub9b0\ub354 \ub7a9 \ub0b4\ubd80 \ubcf4\uc548\uc5d0 \uad00\ud574\uc11c\ub294 \uc2a4\ud1a0\ub9ac \uc804\uac1c\uc0c1 \uc5b5\uc9c0\ub85c \uc124\uc815\ud55c \ubd80\ubd84\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc2e4\uc81c \ucd9c\uc785 \uad00\ub9ac \uc2dc\uc2a4\ud15c\uc774\ub098 \uc678\ubd80\uc640\uc758 \ud1b5\uc2e0 \ubc29\ud574 \ub4f1\uc744 \uc0ac\uc2e4\uc801\uc73c\ub85c \ud45c\ud604\ud558\uba74 \uc8fc\uc778\uacf5\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc774 \uba48\ucdb0 \ubc84\ub9ac\uae30 \ub54c\ubb38\uc5d0, \ubcf8\uc791\uc5d0\uc11c\ub294 \uade0\ud615\uc744 \uc911\uc2dc\ud55c \uc124\uc815\uc744 \ubaa9\ud45c\ub85c \ud588\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP429_ja.cfg.bin#3": "\ud504\ub791\uc2a4 \uc678\uc778\ubd80\ub300\uc5d0 \uc2e4\uc81c\ub85c \uc804\ud22c \uacf5\ubcd1 \ubd80\ub300\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud588\ub358 \uae30\uc5b5\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ud0c0\ub098\uce74\uc758 \ub098\uc774\ub97c \uc0dd\uac01\ud558\uba74 1984\ub144\uc5d0 \uac1c\ud3b8\ub41c \u300e\uc81c6 \uc678\uc778\uacf5\ubcd1\uc5f0\ub300\u300f(1984\ub144 \ub2f9\uc2dc \uc870\uc9c1\uba85)\uc5d0 \uc785\ub300\ud588\ub2e4\ub294 \uc124\uc815\uc774 \uc801\uc808\ud558\uc9c0 \uc54a\uc744\uae4c \uc0dd\uac01\ud569\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP430_ja.cfg.bin#3": "\uc800\ub294 \uc2dc\uac04\uc5ec\ud589\uc744 \uc218\ud559\uc801\uc73c\ub85c \uc774\ub860\ud654\ud560 \ub2a5\ub825\ub3c4 \uc7ac\ub2a5\ub3c4 \uc5c6\uc5b4 \uc8c4\uc1a1\ud588\uc9c0\ub9cc, \uc5b4\ub5bb\uac8c\ub4e0 \uc5bc\ubc84\ubb34\ub9b4 \uc218 \uc788\ub294 \uc5f0\ucd9c\uc744 \ubd80\ud0c1\ub4dc\ub838\uc2b5\ub2c8\ub2e4. \uc218\uc2dd\uc5d0 \uad00\ud574\uc11c\ub294 \ub530\ub73b\ud55c \ub9c8\uc74c\uc73c\ub85c \u300e\uc5bc\ubc84\ubb34\ub9ac\uace0 \uc788\uad6c\ub098!\u300f \ud558\uace0 \uc6c3\uc5b4 \uc8fc\uc2dc\uba74 \uac10\uc0ac\ud558\uaca0\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP431_ja.cfg.bin#3": "SIF\uc758 \ubaa8\ub378\uc740 \uc774\ud0c8\ub9ac\uc544 \uad6d\uac00 \ud5cc\ubcd1\ub300\uc758 \ud2b9\uc218\ubd80\ub300\uc778\\n\u300eGIS\u300f\uc600\uc9c0\ub9cc, \uadf8 \ud6c4 \ube0c\ub77c\uc9c8\uc758 \uce58\uc548 \ubd80\ub300 \u300eBOPE\u300f \ub4f1\uc774 \uc11e\uc5ec \ub4e4\uc5b4\uc640 \ucd5c\uc885\uc801\uc73c\ub85c \uc7a5\ube44 \ub4f1\uc5d0\ub294 \uc0c1\ub2f9\ud788 SF\uc801\uc778 \uc694\uc18c\uac00 \uac00\ubbf8\ub418\uc5c8\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP432_ja.cfg.bin#3": "\uc5ec\uae30\uc11c \ub9d0\ud558\ub294 \uc704\ud5d8\ud55c \ubb34\ub9ac, \uc989 SIF\uac00 \uc18c\uc18d\ub41c \uad6d\uac00 \ud2b9\uc218 \uc0ac\uc548 \ub300\ucc45 \ubcf8\ubd80\ub294 \ucc98\uc74c\uc5d0\ub294 \ub85c\uc2a4\ud2b8 \ud640 \ub300\ucc45\ub9cc \ub9e1\ub294 \uc124\uc815\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ubbf8\ub798\uc758 \uce58\uc548\uacfc \uc0ac\ud68c \uc0c1\ud669\uc744 \uc791\ud488\uc5d0 \ubc18\uc601\ud558\uace0 \uc2f6\ub2e4\ub294 \uc694\uad6c\uac00 \uc788\uc5b4 \uc810\ucc28 \uc5ec\ub7ec \uc5ed\ud560\uc744 \ub298\ub9b0 \uacb0\uacfc, \uc0c1\ub2f9\ud788 \uac15\ub825\ud55c \ud589\uc815 \uc870\uc9c1\uc774\ub77c\ub294 \uc124\uc815\uc774 \ub418\uc5b4 \ubc84\ub838\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP433_ja.cfg.bin#3": "\uc774 \ube14\ub85d\uc740 \uc2e4\ub9b0\ub354 \ub7a9\uc758 \uc2e4\ud5d8\uc5d0\uc11c \ubc1c\uc0dd\ud558\ub294 \uac10\ub9c8\uc120\u30fb\uc911\uc131\uc790\uc120 \ub4f1\uc744 \ucc28\ud3d0\ud558\ub294 \ucf58\ud06c\ub9ac\ud2b8\ub77c\ub294 \uc124\uc815\uc785\ub2c8\ub2e4. \uc2e4\uc81c \uc785\uc790 \uac00\uc18d\uae30 \ub4f1\uc5d0\ub3c4 \ubc29\uc0ac\uc120\uc744 \ucc28\ud3d0\ud558\uae30 \uc704\ud574 \ub0a9 \ube14\ub85d \ub4f1\uc774 \uc900\ube44\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP434_ja.cfg.bin#3": "\ud788\ub098\ub294 SIF\ub97c \u300e\uacbd\ucc30\u300f\uc774\ub77c\uace0 \ubd80\ub974\uc9c0\ub9cc, \uc774\ub4e4\uc740 \uacbd\ucc30\uccad \uad00\ud560\uc774 \uc544\ub2c8\ub77c \uad6d\uac00 \ud2b9\uc218 \uc0ac\uc548 \ub300\ucc45 \ubcf8\ubd80\uc758 \uce58\uc548 \ubd80\ub300\uc785\ub2c8\ub2e4. \uc77c\uc885\uc758 \ubc95 \uc9d1\ud589 \uae30\uad00\uc778 \uac83\uc740 \ub9de\uc9c0\ub9cc, \uc77c\ubcf8\uc758 \uacbd\ucc30\uc774\ub098 \uc790\uc704\ub300\uc640\ub294 \uc804\ud600 \ub2e4\ub978 \uc131\uaca9\uc758 \uc870\uc9c1\uc785\ub2c8\ub2e4.\\n\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP435_ja.cfg.bin#3": "\ub85c\ub110\ub4dc\u30fbL\u30fb\ub9ec\ub9bf\uc758 \ud0c0\uc784\uba38\uc2e0\uc774 \uc124\uc815\uc5d0 \ubc18\uc601\ub418\uae30 \uc804\uae4c\uc9c0, \uc77c\ubcf8\\n\uc5d0\uc11c\ub294 \uc798 \uc54c\ub824\uc9c0\uc9c0 \uc54a\uc740 \uc6cc\uc2f1\ud134 \ub300\ud559\uc758 \uc874\u30fb\\nG. \ud06c\ub808\uc774\uba38 \ubc15\uc0ac\uac00 \uc8fc\uc7a5\ud55c \u300e\uad50\ub958 \ud574\uc11d\u300f(TIQM)\uc744 \uc0ac\uc6a9\ud55c \uc2dc\uac04\uc5ec\ud589 \uc124\uc815\uc744 \ubaa8\uc0c9\ud558\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc120\uc9c4\ud30c\ub77c\ub294 \ub9d0\uc774 \uc790\uc8fc \ub098\uc624\ub294 \uac83\uc740 \uc774 \uc601\ud5a5\uc785\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP436_ja.cfg.bin#3": "\ud788\ub098\ub97c \ub178\ub9b0 SIF\uc758 \ucd1d\ud0c4\uc774 \ube57\ub098\uac04 \uac83\uc740 \uce74\uc774\uac00 \uc77c\uc2dc\uc801\uc73c\ub85c\\n\uc911\ub825 \uc774\uc0c1\uc5d0 \uc758\ud55c \uacf5\uac04 \uc65c\uace1\uc744 \uc77c\uc73c\ucf30\ub2e4\ub294 \ud750\ub984\uc785\ub2c8\ub2e4. \uc5b5\uc9c0\ub77c\ub294 \ub9d0\uc744 \ub4e4\uc73c\uba74 \uadf8 \ub9d0\uc774 \ub9de\ub2e4\uace0 \ub2f5\ud560 \uc218\ubc16\uc5d0 \uc5c6\uc9c0\ub9cc, \uc2e4\ub9b0\ub354 \ub0b4\ubd80\ub098 \uadf8 \uadfc\ucc98\uc5d0\uc11c\ub9cc \ud6a8\uacfc\uac00 \uc788\uace0 \uce74\uc774\uc758 \uc704\uce58\uc5d0\uc11c\ub294 \ud6a8\uacfc\uac00 \uc5c6\ub2e4\ub294 \uc124\uc815\uc785\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP437_ja.cfg.bin#3": "\ubbf8\ucf54\ud1a0\uac00 \uc785\ub294 \ubc29\ud638\ubcf5\uc740 \uc2dc\uac01\uc801\uc778 \uad00\uc810\uc5d0\uc11c \uac1c\ubc1c \uc911\uc778 \uac83\uc744 \ud3ec\ud568\ud55c \uc6b0\uc8fc\ubcf5\uc744 \ubaa8\ub378\ub85c \uc0bc\uc558\uc2b5\ub2c8\ub2e4. \uc6d0\ub798 \uc774 \uc138\uc0c1\uc5d0 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \uac83 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc7a5\ube44\uc774\ubbc0\ub85c, \uac89\ubaa8\uc2b5\ub9cc\uc73c\ub85c\ub3c4 \uc124\ub4dd\ub825\uc774 \uc788\uc5b4 \ubcf4\uc774\ub294 \ud615\ud0dc\uc640 \ub514\uc790\uc778\uc774 \uc88b\uaca0\ub2e4\ub294 \ud310\ub2e8\uc774\uc5c8\ub358 \uac83 \uac19\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP438_ja.cfg.bin#3": "\uac00\ub2a5\ud55c \ud55c \uacfc\ud559\uc801\uc73c\ub85c \uc62c\ubc14\ub978 \uc11c\uc220\uc744 \ud558\ub824\uace0 \ud588\uc9c0\ub9cc, \uc2a4\ud1a0\ub9ac\uc640 \uae00\uc790 \uc218 \ub54c\ubb38\uc5d0 \uc758\ub3c4\uc801\uc73c\ub85c \uac04\ub2e8\ud558\uac8c \uc801\uac70\ub098 \uc77c\ubd80\ub7ec \uc758\ubbf8\ub97c \ud750\ub9b0 \ubd80\ubd84\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uac83\uc740 \uace0\uc99d \ub2f4\ub2f9 \uce21\uc758 \ubcc0\uba85\uc785\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP439_ja.cfg.bin#3": "\uc2e4\ub9b0\ub354 \ub7a9\uc758 \uc2e4\ud5d8 \uc911 \ub300\uc0ac\ub294 \uace0\uc5d0\ub108\uc9c0 \ubb3c\ub9ac\ud559 \uc2e4\ud5d8 \ub4f1\uc758 \ub17c\ubb38\uc744 \ubaa8\ub378\ub85c \uc791\uc131\ud588\uc9c0\ub9cc, \uc880 \ub354 \ucc3d\uc791\uc744 \ub123\uc5b4 \uc774\ud574\ud558\uae30 \uc26c\uc6b4 \ud45c\ud604\uc73c\ub85c \ub9cc\ub4dc\ub294 \ud3b8\uc774 \uc88b\uc558\uc744\uc9c0\ub3c4 \ubaa8\ub985\ub2c8\ub2e4. \ubd84\uc704\uae30\ub294 \uc0b4\uc544 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0\ub9cc\uc694.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP440_ja.cfg.bin#3": "\uc5ec\uae30 \ub300\uc0ac\uc5d0 \ub098\uc624\ub294 \ud720\ub7ec\u30fb\ud30c\uc778\uba3c\u30fb\uac8c\uc774\uc9c0\ub294 \uac00\uc0c1\uc758 \uc6a9\uc5b4\uc9c0\ub9cc, \uc5b4\ub5a4 \uc218\ub2e8\uc73c\ub85c \uc120\uc9c4\ud30c\ub97c \uac80\ucd9c\ud558\ub294 \uc2dc\uc2a4\ud15c\uc774\ub77c\ub294 \uc124\uc815\uc785\ub2c8\ub2e4. \ub9e5\uc2a4\uc6f0\uc758 \uc804\uc790\uae30 \ubc29\uc815\uc2dd\uc5d0\uc11c \ub3c4\ucd9c\ud55c \uc120\uc9c4\ud30c\ub97c \ubc1c\uc804\uc2dc\ucf1c \uad11\uc790\uc758 \ud761\uc218\\n\uc774\ub860\uc744 \uc8fc\uc7a5\ud55c \ud720\ub7ec\uc640 \ud30c\uc778\uba3c\uc5d0\uac8c \uacbd\uc758\ub97c \ud45c\ud574 \uc774\ub984 \ubd99\uc600\uc2b5\ub2c8\ub2e4.\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP441_ja.cfg.bin#3": "\ud50c\ub808\uc774\ud574 \uc8fc\uc154\uc11c \uac10\uc0ac\ud569\ub2c8\ub2e4. \uc720\uc77c\ud55c \uc544\uc26c\uc6c0\uc740 2049\ub144\uc758 \uc720\ub9ac\uac00 \uc7ac\ud559 \uc911\uc778 \uc2a4\uc704\uc2a4 \uc81c\ub124\ubc14 \uad50\uc678(\uc77c\ubd80 \ud504\ub791\uc2a4 \uad6d\uacbd)\uc758 \uc720\ub7fd \uc6d0\uc790\ud575 \uc5f0\uad6c \uae30\uad6c(CERN)\uae4c\uc9c0 \ucde8\uc7ac\ud558\ub7ec \uac00\uc9c0 \ubabb\ud588\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \uac8c\uc784\uc740 \uc644\uc131\ub418\uc5b4 \ubc84\ub838\uc9c0\ub9cc \ucde8\uc7ac\ube44\ub294 \ub098\uc624\uc9c0 \uc54a\uc744\uae4c\uc694?\\n\u3010\uc2dc\ub77c\ud1a0\u3011",
    "TIP442_ja.cfg.bin#3": "\uc544\ub78d\uc5d0\uc11c \uc815\ub839\uc774\ub098 \ub9c8\uc778 \ub4f1\uc744 \uac00\ub9ac\ud0a4\ub294 \ub9d0. \ub05d\uc5c6\ub294 \uc6d0\uc744 \uadf8\ub9ac\ub294 \uc138\uacc4\uc120 \uc704\uc758 \uc785\uc790\ub97c \ub9d0\ud55c\ub2e4. \uc2dc\uac04\uc5ec\ud589\uc73c\ub85c \ubbf8\ub798\uc5d0\uc11c \uacfc\uac70\ub85c \ubcf4\ub0b4\uc9c4 \uac83\uc744 \ub2e4\uc2dc \ubbf8\ub798\uc5d0\uc11c \uacfc\uac70\ub85c \uac00\uc838\uc654\ub2e4\uace0 \ud558\uc790. \uadf8\ub7ec\uba74 \ub204\uad6c\ub3c4 \ub9cc\ub4e4\uc9c0 \uc54a\uc558\uc744 \ubb3c\uac74\uc774 \uadf8 \uc2dc\uac04\ub300\uc5d0 \uc874\uc7ac\ud558\uac8c \ub41c\ub2e4. \uc774\ub7f0 \ubaa8\uc21c\ub41c \uc874\uc7ac\ub97c \uc9c4\uc774\ub77c\uace0 \ubd80\ub978\ub2e4.\u3010\ud574\uc124\u3011",
    "TIP443_ja.cfg.bin#3": "\uc790\uc138\ud55c \ub0b4\uc6a9\uc740 \uc54c \uc218 \uc5c6\uc9c0\ub9cc, \uc5b4\ub5a4 \uc591\uc790\uc801 \uc218\ub2e8\uc73c\ub85c \ud2b9\uc815 \uc2dc\uac04\uc5d0 \ubb3c\uc9c8\uc744 \ub3d9\uae30\ud654\ud574 \uace0\uc815\ud558\ub294 \uae30\ub2a5\uc778 \ub4ef\ud558\ub2e4. \uc774 \uc575\ucee4\uac00 \uc624\uc804 11\uc2dc\uc5d0 \uc124\uce58\ub418\uc5c8\uae30 \ub54c\ubb38\uc5d0 \ubbf8\ucf54\ud1a0\ub294 \ub85c\uc2a4\ud2b8 \ud640 \uc9c1\uc804\uc5d0, \uc624\uc804 11\uc2dc\uc758 \uac19\uc740 \uacf5\uac04\uc73c\ub85c \uc2dc\uac04\uc5ec\ud589\ud558\uac8c \ub41c\ub2e4.\u3010\ud574\uc124\u3011",
    "TIP444_ja.cfg.bin#3": "\uc774 \uc2dc\uc810\uc5d0\uc11c \uc774\uc57c\uae30\ub418\ub294 \uc6e8\uc774\ube0c\ub294 \uc544\uc9c1 \uac1c\ub150\uc774\uba70, \uc2e4\uc81c\ub85c\ub294 \uc544\uc9c1 2013\ub144\uacfc 2031\ub144\uc774 \uacc4\uc18d \ubc18\ubcf5\ub420\uc9c0\ub294 \uacb0\uc815\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc774 \ub4a4 \uc2e0\uc758 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc190\uc5d0 \uc758\ud574 \u300e\uadf8\uac83\u300f\uc774 \uc77c\uc5b4\ub0a0\uc9c0 \uacb0\uc815\ub41c\ub2e4.\u3010\ud574\uc124\u3011",
    "TIP445_ja.cfg.bin#3": "\uc774 \uba54\uc77c\uc740 6\ud68c\uc9f8\ub97c \uacaa\ub294 \ubaa8\ub4e0 \ubbf8\ucf54\ud1a0\uc758 \ud734\ub300\uc804\ud654\uc5d0\uc11c \uc218\uc2e0\ud560 \uc218 \uc788\uc9c0\ub9cc, 2~6\ud68c\uc9f8\uc758 \ud734\ub300\uc804\ud654\ub294 \uc774\ubbf8 \uc774 \uba54\uc77c\uc744 \uc218\uc2e0\ud588\uc73c\ubbc0\ub85c \ub2e4\uc2dc \uc218\uc2e0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub530\ub77c\uc11c \uba54\uc77c\uc774 \ub3c4\ucc29\ud558\ub294 \uac83\uc740 1\ud68c\uc9f8\uc758 \ud734\ub300\uc804\ud654\ubfd0\uc774\ub2e4. \uc774 \uba54\uc77c\ub3c4 \uc9c4(\ub05d\uc5c6\ub294 \uc6d0\uc744 \uadf8\ub9ac\ub294 \uc138\uacc4\uc120)\uc774\ub2e4. \uc0ac\uc2e4 \uc774 \uc774\uc57c\uae30\uc5d0\ub294 \ub610 \ud558\ub098\uc758 \uc9c4\uc774 \uc228\uaca8\uc838 \uc788\ub2e4. \ub2f9\uc2e0\uc740 \ucc3e\uc544\ub0bc \uc218 \uc788\uc744\uae4c?\u3010\ud574\uc124\u3011",
    "TIP446_ja.cfg.bin#3": "\ubbf8\ucf54\ud1a0\uac00 11\uc2dc\ubd80\ud130 20\uc2dc\uae4c\uc9c0 \uc2dc\uac04\uc5ec\ud589\ud558\ub294 \ub3d9\uc548 \ubc1b\ub294 \uba54\uc77c\uc740 2\ud1b5\uc774\ub2e4. \uc218\uc5c5\uc774 \ub05d\ub098\uace0 15\uc2dc \uc804\uc5d0 \ud734\ub300\uc804\ud654 \uc804\uc6d0\uc744 \ucf20 1\ud68c\uc9f8\uc758 \ubbf8\ucf54\ud1a0\ub294 \uc790\uc2e0\uc5d0\uac8c\uc11c \uc628 \uba54\uc77c\uc5d0 \ub180\ub77c \uc2e0\ub3c4\uc5d0\uac8c\uc11c \uc628 \ub450 \ubc88\uc9f8 \uba54\uc77c\uc744 \ud655\uc778\ud558\ub294 \uac83\uc744 \uc78a\uace0 \uc788\ub2e4. \uc2e0\ub3c4\uc5d0\uac8c\uc11c \uc628 \uba54\uc77c\uc744 \ucc98\uc74c \ubcf8 \uac83\uc740 2\ud68c\uc9f8 \ubbf8\ucf54\ud1a0\uc600\ub2e4.\u3010\ud574\uc124\u3011",
    "TIP447_ja.cfg.bin#3": "\ubb34\ub300\uc640 \uad00\uac1d \uc0ac\uc774, \u300e\ud53d\uc158\uc758 \uc138\uacc4\u300f\uc640 \u300e\ud604\uc2e4\u300f \uc0ac\uc774\ub97c \uac00\ub85c\ub9c9\ub294 \ud22c\uba85\ud55c \ubcbd\uc744 \ub9d0\ud55c\ub2e4.\u3010\ud574\uc124\u3011",
})

