OVERRIDES["outline.json"].update({
    "OUTLINE_C_ja.cfg.bin#3": "14\uc2dc. \ub274\uc2a4 \uce90\uc2a4\ud130\ub97c \uafc8\uafb8\ub294 TV \ud30c\\\uc774\ube0c\uc758 \uc5ec\uc790 \uc544\ub098\uc6b4\uc11c \ud6c4\uc2dc\ubbf8 \ud788\ub098\ub294 \uc120\ubc30 \uc720\ub9ac\uce74\\\uc5d0\uac8c \uad34\ub86d\ud798\uc744 \ub2f9\ud558\uace0 \uc788\uc5c8\ub2e4. \uadf8\ub54c \ubcf4\ub3c4 \ud504\ub85c\uadf8\ub7a8\uc758 \ud504\ub85c\\\ub4c0\uc11c \ud0c0\uce74\uc774\ub3c4\uac00 \ub098\ud0c0\ub098 \ucde8\uc7ac\ub97c \ubd80\ud0c1\ud55c\ub2e4.\\n\uae30\ud68c\ub97c \uc7a1\uc740 \ud788\ub098\ub294 \uce74\uba54\ub77c\ub9e8 \ucfe0\ub77c\ubaa8\ud1a0\uc640\\\ud568\uaed8 \u300e\ud574\uace8 \uad34\uc778\u300f \ucde8\uc7ac\uc5d0 \ub098\uc120\ub2e4.",
    "OUTLINE_C_ja.cfg.bin#4": "\uccab \ucde8\uc7ac\uc9c0\ub294 \ubbf8\ub3c4\ub9ac\uac00\uc624\uce74 \uace0\ub4f1\ud559\uad50\uc600\ub2e4. \ud558\uc9c0\ub9cc\\\ub3c4\uc911\uc5d0 \ud574\uace8 \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\uc5d0\uac8c \uc810\uac70\ub41c\\\ubc84\uc2a4\ub97c \ubc1c\uacac\ud55c\ub2e4. \ubc94\uc778\uc758 \ubaa9\uc801\uc774 TV \ud30c\uc774\ube0c\\\ud3ed\ud30c\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc548 \ud788\ub098\ub294 \uce74\ubbf8\uc57c\uc640 \ud611\ub825\ud574 \ud14c\ub7ec\ub97c\\\uc800\uc9c0\ud55c\ub2e4. \uadf8\ub9ac\uace0 \uc0ac\uac74 \ubc30\ud6c4\uc5d0 \ud2b9\uc885\uc758\\\uc608\uac10\uc744 \ub290\ub07c\uace0, \ub2e4\uc2dc \ubbf8\ub3c4\ub9ac\uac00\uc624\uce74 \uace0\ub4f1\ud559\uad50\ub85c \ud5a5\ud55c\ub2e4.",
    "OUTLINE_C_ja.cfg.bin#5": "15\uc2dc. \ud788\ub098\ub294 \ubbf8\ub3c4\ub9ac\uac00\uc624\uce74 \uace0\ub4f1\ud559\uad50\uc5d0 \ucde8\uc7ac\ub97c \uc654\ub2e4.\\n\ubbf8\ucf54\ud1a0\uc640 \uc720\ub9ac\uc5d0\uac8c\uc11c \u300e\ud574\uace8 \uad34\uc778\u300f\uc774 \uc4f0\ub294\\\ub9c8\uc2a4\ud06c \ub514\uc790\uc778\uc774 \u300e\ub137 \ub9ac\ud06c\uc2a4\u300f\ub77c\ub294\\\ub3d9\uc601\uc0c1 \ub274\uc2a4 \uc0ac\uc774\ud2b8\uc758 \ub9c8\ud06c\uc640 \ube44\uc2b7\ud558\ub2e4\ub294\\\ub9d0\uc744 \ub4e4\uc740 \ud788\ub098\ub294 \ub2e4\uc74c \ub2e8\uc11c\ub97c \ucc3e\uc544\\\ub137 \ub9ac\ud06c\uc2a4 \uc6b4\uc601 \ud68c\uc0ac\ub85c \ud5a5\ud55c\ub2e4.",
    "OUTLINE_C_ja.cfg.bin#6": "\ub137 \ub9ac\ud06c\uc2a4 \ub300\ud45c \ud0c0\ub2e4\ub178\ub97c \ucde8\uc7ac\ud558\ub358 \uc911 \uac11\uc790\uae30\\\uac74\uc7a5\ud55c \uac70\ud55c\uc774 \ubc29\uc5d0 \ub4e4\uc5b4\uc640 \uc2b5\uaca9\ub2f9\ud55c\ub2e4.\\\ud788\ub098\ub294 \ub0a8\uc790\uc758 \ud5c8\ub97c \ucc14\ub7ec \uc2a4\ud134\uac74\uc73c\ub85c \ubc18\uaca9\ud55c\ub2e4.\\\ub0a8\uc790\uac00 \uc4f0\ub7ec\uc9c4 \ud2c8\uc5d0 \ucfe0\ub77c\ubaa8\ud1a0, \ud0c0\ub2e4\ub178\uc640 \ud568\uaed8\\\ud544\uc0ac\uc801\uc73c\ub85c \ub3c4\ub9dd\uce5c\ub2e4.",
    "OUTLINE_C_ja.cfg.bin#7": "16\uc2dc. \ud788\ub098\ub294 \uacbd\ucc30\uacfc \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\uc758 \ubc00\ud68c \uc815\ubcf4\\\uac00 \uc720\ucd9c\ub418\uc5b4 \ud604\uc7a5\uc73c\ub85c \ud5a5\ud55c\ub2e4. \uadf8\uacf3\uc5d0\ub294 \ud788\ub098\\\ub97c \uc2b5\uaca9\ud588\ub358 \ub0a8\uc790\uac00 \uc788\uc5c8\ub2e4. \ud788\ub098\ub294 \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\uc640 \uacbd\ucc30\\\uc758 \ub0b4\ud1b5\uc790\uc5d0\uac8c \ub3cc\uaca9 \uc778\ud130\ubdf0\ub97c \uac10\ud589\ud55c\ub2e4. \uadf8\ub4e4\uc758\\\ubaa9\uc801\uc774 \ub7a9 \uc7a0\uc785\uc784\uc744 \uc54c\uace0 \ud2b9\uc885\uc5d0 \uae30\ubed0\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ucfe0\ub77c\ubaa8\ud1a0\uc5d0\uac8c\\\uc9c8\ucc45\ubc1b\uace0 \ub9cc\ub2e4.",
    "OUTLINE_C_ja.cfg.bin#8": "\ucde8\uc7ac \uc601\uc0c1\uc744 \ubc29\uc1a1\uad6d\uc73c\ub85c \uac00\uc838\uc628 \ud788\ub098\ub294 \ubcf5\ub3c4\uc5d0\uc11c\\\ub9cc\ub09c \ubbf8\ucf54\ud1a0\uc758 \ub9d0\uc5d0 \ub530\ub77c \uc720\ub9ac\uce74\uc5d0\uac8c\uc11c \uac74\ub124\ubc1b\uc740\\\ud14c\uc774\ud504\ub97c \ubcf8\ub2e4. \uadf8\uac83\uc740 \uc8fd\uc740 \ud788\ub098\uc758 \uc544\ubc84\uc9c0 \uc544\ud0a4\ub77c\uac00\\\ub85c\uc2a4\ud2b8 \ud640\uc758 \ube44\ubc00\uc5d0 \ub2e4\uac00\uac04 \uc601\uc0c1\uc774\uc5c8\ub2e4.\\\ud788\ub098\uac00 \uadf8 \uc601\uc0c1\uc744 \ub2e4 \ubcf4\uace0 \ub0ac\uc744 \ub54c, \ud574\uc548\uc5d0\uc11c \uc6b0\uc8fc\\\uc5d8\ub9ac\ubca0\uc774\ud130\uac00 \ud3ed\ubc1c\ud558\ub294 \uac83\uc744 \ubaa9\uaca9\ud55c\ub2e4.",
    "OUTLINE_C_ja.cfg.bin#9": "17\uc2dc. \uc18c\ub780\uc2a4\ub7ec\uc6b4 TV \ubc29\uc1a1\uad6d. \ud788\ub098\ub294 \ucde8\uc7ac\\\uc601\uc0c1\uc744 \ubc29\uc1a1\ud574 \ub2ec\ub77c\uace0 \ubd80\ud0c1\ud558\uc9c0\ub9cc, \uc0c1\uce35\ubd80\uc758 \uc9c0\uc2dc\\\ub85c \uac70\uc808\ub2f9\ud55c\ub2e4. \uc88c\uc808\ud558\uba74\uc11c\ub3c4 \uc720\ub9ac\uce74\\\uc640 \uc774\uc57c\uae30\ub97c \ub098\ub204\uba70 \ub2e4\uc2dc \uc77c\uc5b4\uc120 \ud788\ub098\ub294 \ud0c0\ub2e4\ub178\uc758 \uc778\ud130\ub137\\\uc911\uacc4\ub85c \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\uc758 \ubaa9\uc801\uc774 \ub85c\uc2a4\ud2b8 \ud640\uc758\\\uc7ac\ud604\uc784\uc744 \ubcf4\ub3c4\ud558\ub824 \ud55c\ub2e4.",
    "OUTLINE_C_ja.cfg.bin#10": "\ud788\ub098\ub294 \ucfe0\ub77c\ubaa8\ud1a0\ub97c \uc124\ub4dd\ud574 \ub7a9\uc73c\ub85c \ud5a5\ud55c\ub2e4. \ub3c4\uc911\uc5d0 \uc774\ud0c8\\\ud55c \ud0c0\ub2e4\ub178 \ub355\ubd84\uc5d0 \ub7a9 \uc55e\uc5d0\uc11c \uc778\ud130\ub137\\\uc911\uacc4\uac00 \ubb34\uc0ac\ud788 \uc2dc\uc791\ub41c\ub2e4. \uadf8\uacf3\uc5d0 \ud574\uace8 \ud14c\ub7ec\ub9ac\\\uc2a4\ud2b8\uac00 \ub098\ud0c0\ub09c\ub2e4. \ud14c\ub7ec\uc758 \uc8fc\ubaa8\uc790 \uc2a4\ucf08\ub808\ud1a4\\\uc774 \ud788\ub098 \uc77c\ud589\uc744 \ub9cc\ub098\uaca0\ub2e4\uace0 \ud55c\ub2e4. \ud788\ub098\ub294 \uc2a4\ucf08\ub808\ud1a4\uacfc\\\ub300\uba74\ud574 \uc778\ud130\ubdf0\ub97c \uc2dc\uc791\ud55c\ub2e4\u2026\u2026",
    "OUTLINE_C_ja.cfg.bin#11": "18\uc2dc. \ud788\ub098\uc758 \uc2a4\ucf08\ub808\ud1a4 \uc778\ud130\ubdf0\\\uac00 \uc2dc\uc791\ub41c\ub2e4. \uc2a4\ucf08\ub808\ud1a4\uc758 \ubaa9\uc801\uc740 \ub3c4\ucfc4 \uc18c\uba78\uc774\ub2e4.\\\uadf8 \ubaa9\uc801\uc740 \ubcf5\uc218\uc600\ub2e4. \uc815\ubd80\ub294 \uc0ac\uac74\uc5d0\uc11c \uc190\uc5d0\\\ub123\uc740 \ubbf8\uc9c0\uc758 \uc5d0\ub108\uc9c0\ub97c \ub3c5\uc810\ud558\uace0, \uadf8\\\uc81c\uc5b4\ub97c \uc704\ud574 \ub9ce\uc740 \uc5f0\uad6c\uc6d0\uc744 \ud76c\uc0dd\uc2dc\ud0a8 \uc0ac\uc2e4\\\uc744 \uc740\ud3d0\ud558\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4.",
    "OUTLINE_C_ja.cfg.bin#12": "\uc2a4\ucf08\ub808\ud1a4\uc740 \uc0ac\uac74 \ub2f9\uc2dc \uc5f0\uad6c\uc6d0\uc758 \uc0dd\uc874\uc790\\\uc600\ub2e4. \uc2dc\uccad\uc790\ub4e4\uc758 \uaca9\ub824\ub85c \uc790\uc2e0\uc744 \ub418\ucc3e\\\uc740 \ud788\ub098\uc5d0\uac8c \uc2a4\ucf08\ub808\ud1a4\uc740 \ub9e8\uc5bc\uad74\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uadf8 \uc815\uccb4\\\ub294 \ud788\ub098\uc758 \uc5f0\uc778 \uce74\uc774\uc600\ub2e4. \ubc29\uc744 \ub098\uac00\\\ub294 \uce74\uc774. \ud788\ub098\ub294 \ub85c\uc2a4\ud2b8 \ud640 \uc7ac\ud604\uc744 \ub9c9\uae30\\\uc704\ud574 \ub4a4\ub97c \ucad3\uc544 \ub7a9 \uae4a\uc740 \uacf3\uc73c\ub85c \ud5a5\ud55c\ub2e4.",
    "OUTLINE_H_ja.cfg.bin#3": "15\uc2dc. \ubbf8\ub3c4\ub9ac\uac00\uc624\uce74 \uace0\ub4f1\ud559\uad50 \ud559\uc0dd \uc720\ub9ac\ub294 \uc18c\uafc9\uce5c\uad6c\\\ubbf8\ucf54\ud1a0\uc758 \uc81c\uc548\uc73c\ub85c \ub85c\uc2a4\ud2b8 \ud640 \uc774\ud6c4\\\uacc4\uc18d \ucd9c\uc785 \uae08\uc9c0\uc778 \uc2e4\ub9b0\ub354 \ub7a9\uc5d0 \uc7a0\uc785\ud558\uac8c\\\ub41c\ub2e4. \ubc1c\ub2e8\uc740 \ubbf8\ucf54\ud1a0\uc758 \ud734\ub300\uc804\ud654\uc5d0,\\\ubbf8\ucf54\ud1a0\uac00 \ucd9c\uc785 \uae08\uc9c0\uc778 \ub7a9 \uc548\uc5d0 \uc11c \uc788\ub294\\\uae30\uc5b5\uc5d0 \uc5c6\ub294 \uc0ac\uc9c4\uc774 \uc804\uc1a1\ub41c \uac83\uc774\uc5c8\ub2e4.",
    "OUTLINE_H_ja.cfg.bin#4": "\ub450 \uc0ac\ub78c\uc740 \ub7a9 \uc815\ubb38\uae4c\uc9c0 \uc624\uc9c0\ub9cc \ub4e4\uc5b4\uac08 \ubc29\ubc95\uc774 \uc5c6\ub2e4.\\n\uadf8\ub54c \uad50\uc0ac \uc774\ud1a0\uc57c\ub9c8\uac00 \uc640\uc11c \ub7a9\uc5d0 \uc218\uc218\uaed8\ub07c\uc758 \uc5d0\ub108\\\uc9c0\uac00 \uc7a0\ub4e4\uc5b4 \uc788\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc740 \ub7a9 \uc7a0\uc785\\\uc744 17\uc2dc\ub85c \uc815\ud558\uace0 \ud559\uad50\ub85c \ub3cc\uc544\uac04\ub2e4. \ub3c4\uc911\uc5d0 \ucd95\uad6c \uace8\\\ub300\uac00 \uc4f0\ub7ec\uc838 \uc628\ub2e4. \uac04\ubc1c\uc758 \ucc28\ub85c \ud53c\ud558\uc790 \uc9c0\uba74\uc5d0\\\u300e\ub2e4\uac00\uc624\uba74 \uc8fd\uc778\ub2e4\u300f\ub77c\uace0 \uc4f0\uc5ec \uc788\uc5c8\ub2e4.",
    "OUTLINE_H_ja.cfg.bin#5": "16\uc2dc. \uc720\ub9ac\ub294 \uc2ec\ubd80\ub984\uc744 \ubd80\ud0c1\ubc1b\uc544 \ud559\uad50\ub97c \ub098\uc120\ub2e4.\\n\uc720\ub9ac\ub294 \uacfc\ud559\ubd80 \ub3d9\ub8cc\uc778 \uc288\uc774\uce58\ub85c\uc640 \ub9c8\uc0ac\ud1a0\uc5d0\uac8c \ub7a9\\\uc7a0\uc785\uc744 \uc54c\ub9b0\ub2e4. \uc2ec\ubd80\ub984\uc744 \ub9c8\uce5c \uc720\ub9ac\ub294\\\ud504\ub791\uc2a4\uc5b4 \uba54\uc77c\uc744 \ubc1b\ub294\ub2e4. \ubc1c\uc2e0\uc790\ub294\\\u300cmikoto\u300d. \uba54\uc77c\uc5d0\ub294 18\ub144 \ud6c4\uc758\\\ub0a0\uc9dc\uac00 \uc801\ud78c \uc601\uc5b4 \ub17c\ubb38 \ub9c1\ud06c\uac00 \uc788\uc5c8\ub2e4.",
    "OUTLINE_H_ja.cfg.bin#6": "\ub7a9\uc73c\ub85c \ud5a5\ud558\ub358 \ub3c4\uc911 \uc720\ub9ac\ub294 \ud574\uace8\uc5d0\uac8c \uc2b5\uaca9\ub2f9\ud574\\\u300e\ub2e4\uac00\uc624\uc9c0 \ub9c8\u300f\ub77c\ub294 \ud611\ubc15\uc744 \ubc1b\ub294\ub2e4. \ub7a9\\\uc55e\uc5d0\uc11c \ubbf8\ucf54\ud1a0 \uc77c\ud589\uacfc \ud569\ub958\ud55c \uc720\ub9ac\ub294 \uc5b4\uc9f8\uc11c\uc778\uc9c0\\\uc5f4\ub824 \uc788\ub358 \ubb38\uc744 \uc9c0\ub098 \uc7a0\uc785\ud558\uc9c0\ub9cc, \uc774\ud1a0\uc57c\ub9c8\uc5d0\uac8c\\\ubc1c\uacac\ub41c\ub2e4. \uc774\ud1a0\uc57c\ub9c8\uc758 \uc548\ub0b4\ub85c \uc625\uc0c1\uc5d0 \uc624\ub978 \uc720\ub9ac\\\uc77c\ud589\uc740 \uc6b0\uc8fc \uc5d8\ub9ac\ubca0\uc774\ud130 \ud3ed\ubc1c\uc744 \ubaa9\uaca9\ud55c\ub2e4.",
    "OUTLINE_H_ja.cfg.bin#7": "17\uc2dc. \ub7a9\uc5d0 \ud574\uace8 \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\uac00 \uc7a0\uc785\ud558\ub294 \uac83\uc744 \ubcf4\\\uace0 \ub3c4\ub9dd\uce58\ub824\ub294 \ubbf8\ucf54\ud1a0 \uc77c\ud589. \ud558\uc9c0\ub9cc \uc720\ub9ac\ub294 \ud63c\uc790 \uc9c0\ud558\\\ub85c \ud5a5\ud574 \uacc4\ub2e8\uc5d0\uc11c \ub5a8\uc5b4\uc838 \uc758\uc2dd\uc744 \uc783\ub294\ub2e4. \ubbf8\ucf54\ud1a0\uc640 \uc288\uc774\uce58\ub85c\\\uc758 \uac04\ud638\ub85c \uae68\uc5b4\ub09c \uc720\ub9ac\ub294 \uc0dd\uba85\uc758 \uc740\uc778\uc774 \ub538\\\uc5d0\uac8c \uc0ac \uc900 \uc778\ud615\uc744 \ucc3e\uace0 \uc788\ub2e4\uace0 \ubc1d\ud78c\ub2e4.",
    "OUTLINE_H_ja.cfg.bin#8": "\ub7a9\uc744 \ub098\uc544\uac00\ub358 \uc138 \uc0ac\ub78c\uc740 \ud574\uace8 \uc77c\ub2f9\uacfc \ub9c8\uc8fc\uccd0 \ub3c4\uc8fc\ud55c\ub2e4.\\n\ub3c4\uc911\uc5d0 \uc288\uc774\uce58\ub85c\uc640 \ub5a8\uc5b4\uc9c4\ub2e4. \ub3c4\ub9dd\uce5c \ub450 \uc0ac\ub78c\\\uc740 \ud1b5\ub85c\uc5d0\uc11c \uc270\ub2e4. \uc720\ub9ac\ub294 \ubbf8\ucf54\ud1a0\uc5d0\uac8c \uba54\uc77c\ub85c \ub3c4\ucc29\\\ud55c \uc218\uc218\uaed8\ub07c\uc758 \uc601\uc5b4 \ub17c\ubb38\uc744 \uc77d\uac8c \ud55c\ub2e4. \ub17c\ubb38\uc5d0\ub294\\\ub85c\uc2a4\ud2b8 \ud640\uc758 \uc0dd\uc874\uc790\ub4e4\uc740 \uc2dc\uac04\uc5ec\ud589\uc790\ub77c\uace0 \uc4f0\uc5ec\\\uc788\uc5c8\ub2e4.",
    "OUTLINE_H_ja.cfg.bin#9": "18\uc2dc. \uc720\ub9ac\uac00 \uacc4\ub2e8\uc744 \ucc3e\uc544 \ubc16\uc73c\ub85c \ub098\uc624\uc790,\\\uadf8\uacf3\uc740 \uace0\ub4f1\ud559\uad50 \ub4b7\ub9c8\ub2f9\uc774\uc5c8\ub2e4. \uc720\ub9ac\ub294 \ubbf8\ucf54\ud1a0\ub97c\\\ub0b4\ucad3\uace0 \ud63c\uc790 \ub7a9\uc73c\ub85c \ub3cc\uc544\uac04\ub2e4. \ud558\uc9c0\ub9cc \ub204\uad70\uac00\uc5d0\uac8c\\\uc5bb\uc5b4\ub9de\uace0 \uc758\uc2dd\uc744 \uc783\ub294\ub2e4. \ub208\uc744 \ub5a0 \ubcf4\ub2c8 \ud574\uace8 \ub9c8\uc2a4\\\ud06c\uac00 \uc788\uc5c8\uace0, \uc815\uccb4\ub294 \uc288\uc774\uce58\ub85c\uc600\ub2e4. \uc288\uc774\uce58\ub85c\ub294\\\ubbf8\ucf54\ud1a0\uc758 \uc7ac\uce68\uc785\uc744 \uc54c\uace0 \ubd99\uc7a1\uc73c\ub77c\uace0 \uba85\ub839\ud55c\ub2e4.",
    "OUTLINE_H_ja.cfg.bin#10": "\ubb36\uc5ec \uc788\ub358 \uc720\ub9ac\ub294 \ub9c8\uc0ac\ud1a0\uc5d0\uac8c \uad6c\ucd9c\ub418\uc5b4 \ub458\\\uc774\uc11c \uc288\uc774\uce58\ub85c\ub97c \ub9c9\uc73c\ub7ec \uac04\ub2e4. \uc720\ub9ac\uac00 \ubbf8\ucf54\ud1a0\ub97c \uad6c\ud558\uc790\\\uc288\uc774\uce58\ub85c\ub294 \ubbf8\ucf54\ud1a0\ub97c \ud5a5\ud55c \ub9c8\uc74c\uc744 \ub4dc\ub7ec\ub0b8\ub2e4.\\\ud750\ub290\ub07c\ub294 \uc288\uc774\uce58\ub85c\uac00 \ucd1d\uc5d0 \ub9de\ub294\ub2e4. \uc3dc \uc0ac\ub78c\uc740\\\uc774\ud1a0\uc57c\ub9c8\uc600\ub2e4. \uc774\ud1a0\uc57c\ub9c8\ub294 \ub9c8\uc0ac\ud1a0\ub3c4 \uc3d8\uace0, \ucd5c\uc2ec\ubd80\uc758\\\uce74\ub4dc\ud0a4\ub97c \ube7c\uc557\uc544 \ub3c4\uc8fc\ud55c\ub2e4. \uc720\ub9ac\ub294 \uc774\ud1a0\uc57c\ub9c8\ub97c \ucad3\ub294\ub2e4.",
    "OUTLINE_M_ja.cfg.bin#3": "20\uc2dc \uc9c1\uc804. \uce74\uc774\ub294 \ud788\ub098\uc5d0\uac8c \uc774 \uc138\uacc4\uc5d0\uc11c \uc77c\uc5b4\\\ub098\ub294 \uc2dc\uac04 \ub8e8\ud504\uc5d0 \uad00\ud574 \uc774\uc57c\uae30\ud558\uace0 \uc788\uc5c8\ub2e4. 20\\\uc2dc\uc5d0 \uc5d0\ub108\uc9c0\uac00 18\ub144 \uc804\uc73c\ub85c \ub3c4\uc57d\ud574 \ud3ed\ubc1c\ud558\uace0,\\\uc138\uacc4\ub294 \uac19\uc740 \uc2dc\uac04\uc744 \ubc18\ubcf5\ud55c\ub2e4. \uce74\uc774\uc758 \ubaa9\uc801\uc740\\\uadf8\uac83\uc744 \ub9ac\uc14b\ud558\uace0 \uc138\uacc4\ub97c \uc6d0\ub798 \ubaa8\uc2b5\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294\\\uac83\uc774\uc5c8\ub2e4. \ud558\uc9c0\ub9cc \uadf8\uacf3\uc5d0 \ubbf8\ucf54\ud1a0\uac00 \ub098\ud0c0\ub09c\ub2e4.",
    "OUTLINE_M_ja.cfg.bin#4": "\uce74\uc774\ub97c \uc124\ub4dd\ud558\ub824\ub294 \ubbf8\ucf54\ud1a0. \uc2e0\ub3c4\uc5d0\uac8c\uc11c \uc218\uc2dd\\\uc744 \ub4e4\uc740 \uce74\uc774\ub294 \uc5b4\uc9f8\uc11c\uc778\uc9c0 \uc138\uacc4\uc758 \ub9ac\uc14b\uc744\\\ub2e8\ub150\ud55c\ub2e4. \uadf8\ub54c \ubb34\uc7a5 \uc9d1\ub2e8 SIF\uac00 \ub09c\uc785\ud55c\ub2e4.\\\ucd1d\uc5d0 \ub9de\uc740 \uce74\uc774\ub294 \ubbf8\ucf54\ud1a0\uc758 \ud314 \uc548\uc5d0\uc11c \uc228\uc744 \uac70\ub454\ub2e4.\\\ub3d9\uc2dc\uc5d0 \ub3c4\ucfc4\ub294 \uac80\uc740 \uad6c\uccb4\uc5d0 \uc0bc\ucf1c\uc9c0\uace0, \ud788\ub098\ub294 18\ub144 \uc804\\\uc73c\ub85c, \ubbf8\ucf54\ud1a0\ub294 11\uc2dc\ub85c \uc2dc\uac04\uc5ec\ud589\ud55c\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#3": "14\uc2dc. \ucc98\uc790\uc2dd\uc744 \ub0a9\uce58\ub2f9\ud55c \ud615\uc0ac \uce74\ubbf8\uc57c\ub294\\\ubc94\uc778\uc758 \uba85\ub839\uc73c\ub85c \uc2dc\ubd80\uc57c\uc5d0 \uc788\uc5c8\ub2e4. \uad50\ucc28\ub85c\uc5d0 \uc18c\ub140\uac00\\\uc2dc\ud55c\ud3ed\ud0c4\uc774 \ub4e0 \uac00\ubc29\uc744 \ub193\ub294\ub2e4. \ud3ed\ud0c4\uc740 \uce74\\\uc6b4\ud2b8\uac00 0\uc774 \ub418\uc9c0\ub9cc \ud3ed\ubc1c\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubc94\uc778\uc740 \uce74\ubbf8\uc57c\\\uc5d0\uac8c \uc804\ud654\ub85c \uc9c4\uc9dc\ub77c\uba74 \uc5b4\ub5bb\uac8c \ub418\ub294\uc9c0 \ud611\ubc15\ud558\uace0, \uc774\uc5b4\\\ubc84\uc2a4 \ub0a9\uce58\ub97c \ub3d5\ub3c4\ub85d \uba85\ub839\ud55c\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#4": "\ubc84\uc2a4\uc5d0 \ud0c4 \uce74\ubbf8\uc57c. \ubc94\ud589 \uc9d1\ub2e8\uc758 \uc77c\uc6d0\uc73c\\\ub85c \uad50\ucc28\ub85c\uc758 \uc18c\ub140\uac00 \uc62c\ub77c\ud0c4\ub2e4. \ud788\ub098\uc640 \ud611\ub825\\\ud574 \ubaa9\ud45c\uac00 \ubc29\uc1a1\uad6d \ud3ed\ud30c\uc784\uc744 \ubc1d\ud600\ub0b8 \uce74\ubbf8\uc57c\\\ub294 \uc18c\ub140\uc758 \ub3c4\uc6c0\ub3c4 \ubc1b\uc544 \ud14c\ub7ec \uc800\uc9c0\uc5d0 \uc131\uacf5\\\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uc18c\ub140\ub294 \uce74\ubbf8\uc57c\uc5d0\uac8c \ucd1d\uc744 \uaca8\ub204\uace0, \ud568\uaed8\\\uc624\ub77c\uace0 \uba85\ub839\ud55c\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#5": "15\uc2dc. \uce74\ubbf8\uc57c\ub294 \uc18c\ub140\uc640 \ubc29\uc1a1\uad6d \uc790\ub8cc\uc2e4\\\uc5d0 \uc788\uc5c8\ub2e4. \uc18c\ub140\uc758 \uc9c0\uc2dc\ub85c \ub85c\uc2a4\ud2b8 \ud640\uc758 \uc218\uc218\uaed8\ub07c\uc5d0\\\uad00\ud55c \ucde8\uc7ac \ud14c\uc774\ud504\ub97c \ucc3e\uc544\ub0b8\ub2e4. \uadf8\uacf3\uc5d0 \uce74\ubbf8\uc57c\\\uc758 \uc0c1\uc0ac \uc0ac\uc640\ud0a4\uac00 \ub098\ud0c0\ub098 \ub0a9\uce58\uac00 \uc790\uc2e0\uc758 \uc9c0\uc2dc\\\uc600\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \ud63c\ub780\uc2a4\ub7ec\uc6cc\ud558\ub294 \uce74\ubbf8\uc57c\uc5d0\uac8c \uc0ac\uc640\ud0a4\ub294 \ubc1c\ud3ec\ud55c\ub2e4.\\\uce74\ubbf8\uc57c\ub294 \uc18c\ub140\uc758 \ub3c4\uc6c0\uc73c\ub85c \ubc29\uc1a1\uad6d\uc744 \ud0c8\ucd9c\ud55c\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#6": "\uc18c\ub140\ub294 \uc790\uc2e0\uc744 \ubbf8\ucf54\ud1a0\ub77c\uace0 \uc18c\uac1c\ud558\uba70 \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\uc758 \ub3d9\ub8cc\uac00\\\uc544\ub2c8\ub77c\uace0 \ubc1d\ud78c\ub2e4. \uce74\ubbf8\uc57c\ub294 \ucc98\uc790\uc2dd\uc744 \uad6c\ud558\uae30 \uc704\ud574\\\ubbf8\ucf54\ud1a0\uc640 \uc0ac\uc640\ud0a4\uac00 \uc9c0\uc815\ud55c \uc8fc\ucc28\uc7a5\uc73c\ub85c \ud5a5\ud55c\ub2e4.\\\uc8fc\ucc28\uc7a5\uc5d0\uc11c \ud574\uace8\uc5d0\uac8c \uc2b5\uaca9\ub2f9\ud558\uc9c0\ub9cc \uc218\uc218\uaed8\ub07c\uc758 \ubbf8\ub140\uac00\\\uadf8\ub4e4\uc744 \uc77c\uc18c\ud55c\ub2e4. \uc0ac\uc640\ud0a4\uc758 \uc804\ud654\ub85c \ud14c\ub7ec \uc870\uc9c1\uc758\\\ub9ac\ub354 \uc2a4\ucf08\ub808\ud1a4\uc758 \uc874\uc7ac\uac00 \ubc1d\ud600\uc9c4\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#7": "16\uc2dc. \uce74\ubbf8\uc57c\ub294 \uc900\ube44\ub41c \ucc28\ub97c \uc6b4\uc804\ud574\\\uac74\uc124 \ud604\uc7a5\uc5d0 \ub3c4\ucc29\ud55c\ub2e4. \uc18c\ub9ac\uc5d0 \uc2e0\uacbd \uc4f0\uc778 \uce74\ubbf8\uc57c\ub294\\\ucc28 \ud2b8\ub801\ud06c\ub97c \uc5f0\ub2e4. \uc548\uc5d0\ub294 \ubb36\uc778\\\ucd1d\ub9ac\uac00 \uc788\uc5c8\ub2e4. \uc5bb\uc5b4\ub9de\uace0 \uae30\uc808\ud55c \uce74\ubbf8\uc57c\uac00 \uc758\uc2dd\\\uc744 \ub418\ucc3e\uc790 \uc0ac\uc640\ud0a4\ub294 \ub7a9\uc758 \ubcf4\uc548 \uc2dc\uc2a4\ud15c\\\ud574\uc81c\uc640 \ud328\uc2a4 \ubc1c\uae09\uc744 \ucd1d\ub9ac\uc5d0\uac8c \uc694\uad6c\ud558\uace0 \uc788\uc5c8\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#8": "\uc0ac\uc640\ud0a4\ub294 \uce74\ubbf8\uc57c\uc758 \ucc98\uc790\uc2dd\ub3c4 \ubd88\ub7ec \uc81c\ud55c \uc2dc\uac04\\\ub0b4\uc5d0 \ub450 \uc0ac\ub78c\uc5d0\uac8c \ub3c4\ucc29\ud558\uc9c0 \ubabb\ud558\uba74 \uc8fd\uc774\uaca0\ub2e4\uace0\\\ud611\ubc15\ud55c\ub2e4. \uce74\ubbf8\uc57c\uac00 \ucc98\uc790\uc2dd\uc5d0\uac8c \ub2ec\ub824\uac00\ub294 \ub3d9\uc548 \ucd1d\ub9ac\ub294\\\uc0ac\uc0b4\ub418\uace0 \ub9cc\ub2e4. \ucd1d\ub9ac\uac00 \uc8fd\uc740 \uc9c1\ud6c4 \uc6b0\uc8fc\\\uc5d8\ub9ac\ubca0\uc774\ud130\uac00 \ud3ed\ubc1c\ud55c\ub2e4. \uc5ec\ud30c\ub85c \ubc1c\ud310\uc774 \ubb34\ub108\uc838\\\uce74\ubbf8\uc57c\uc758 \uc544\ub4e4 \uc694\ud0c0\uac00 \ubd95\uad34\uc5d0 \ud718\ub9d0\ub9b0\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#9": "17\uc2dc. \uce74\ubbf8\uc57c\ub294 \uc794\ud574 \uc18d\uc5d0 \ub5a8\uc5b4\uc9c4 \uc694\ud0c0\ub97c\\\uad6c\ud558\ub824 \ud558\uc9c0\ub9cc \uc790\uc7ac \ubd95\uad34\uc5d0 \ud718\ub9d0\ub9b0\ub2e4. \uce74\ubbf8\uc57c\ub97c \uad6c\ud55c \uac83\uc740 \uc120\ubc30\\\ud615\uc0ac \ub178\ub098\uce74\uc640 \ubbf8\ucf54\ud1a0\uc600\ub2e4. \uc544\ub4e4\uc758 \uc8fd\uc74c\uc5d0 \ubd84\ub178\ud558\ub294 \uce74\ubbf8\uc57c. \uadf8\\\ub54c \uc0ac\uc640\ud0a4\uc5d0\uac8c\uc11c \ub9c8\uc9c0\ub9c9 \uacb0\ud310\uc744 \ub0b4\uc790\ub294 \uc5f0\ub77d\\\uc774 \uc628\ub2e4. \ubbf8\ucf54\ud1a0\ub294 \uce74\ubbf8\uc57c\ub97c \ub530\ub77c\uac04\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#10": "\uc0ac\uc640\ud0a4\uc640 \ub9de\uc11c\ub294 \uce74\ubbf8\uc57c. \uad81\uc9c0\uc5d0 \ubab0\ub9b0 \uc0ac\uc640\ud0a4\\\ub294 \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\uac00 \ub41c \uc774\uc720\uc640 \uce74\ubbf8\uc57c\uc758\\\uc544\ub4e4\uc774 \uc0b4\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\ub9ac\uace0 \uc790\uc0b4\ud55c\ub2e4.\\\ubbf8\ucf54\ud1a0\ub294 \uce74\ubbf8\uc57c\uac00 \uc2dc\uac04\uc5ec\ud589\uc790\ub77c\uace0 \ubc1d\ud788\uba70\\\ud14c\ub7ec\ub97c \ub9c9\uae30 \uc704\ud574 \ud611\ub825\uc744 \ubd80\ud0c1\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uce74\ubbf8\uc57c\\\ub294 \uc544\ub4e4\uc744 \uad6c\ud558\uae30 \uc704\ud574 PC\ubc29\uc73c\ub85c \ud5a5\ud55c\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#11": "18\uc2dc. \uce74\ubbf8\uc57c\ub294 PC\ubc29\uc758 \ud55c \ubc29\uc5d0\uc11c \uc694\ud0c0\\\ub97c \ucc3e\ub294\ub2e4. \uc758\uc790\uc5d0 \ubb36\uc778 \uc694\ud0c0\uc758 \uba38\ub9ac \uc704\\\uc5d0\ub294 \uc5fc\uc0b0\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uc7a5\uce58\uac00 \uc788\ub2e4. \ud574\uc81c \ubc84\ud2bc\\\uc740 \uc788\uc9c0\ub9cc, \uadf8\uac83\uc740 \uc804\uc77c\ubcf8\uc804\ub825 \ubcf8\uc0ac \ube4c\ub529\uc744\\\ud3ed\ud30c\ud558\ub294 \uc2a4\uc704\uce58\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\uc758 \ubaa9\uc228\\\uacfc \uc694\ud0c0\uc758 \ubaa9\uc228 \uc911 \uce74\ubbf8\uc57c\ub294 \uad81\uadf9\uc758 \uc120\ud0dd\uc744 \uac15\uc694\ubc1b\ub294\ub2e4.",
    "OUTLINE_P_ja.cfg.bin#12": "\uce74\ubbf8\uc57c\ub294 \ud574\uc81c \ubc84\ud2bc\uc744 \ub204\ub974\uc9c0 \uc54a\uace0 \ubab8\uc744 \ub358\uc838 \uc694\ud0c0\ub97c\\\uc9c0\ud0a4\ub824 \ud55c\ub2e4. \uadf8\ub54c \ubbf8\ucf54\ud1a0\uac00 \ub098\ud0c0\ub098 \ud574\uc81c\\\ubc84\ud2bc\uc744 \ub204\ub974\uc9c0\ub9cc \ube4c\ub529\uc740 \ud3ed\ubc1c\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc2dc\uac04\\\uc5ec\ud589\uc790\uc778 \ubbf8\ucf54\ud1a0\ub294 \ud3ed\ud0c4\uc774 \uc0ac\uc2e4 \uc774\ubbf8 \ud574\uccb4\ub418\uc5c8\ub2e4\ub294\\\uac83\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uad6c\ud55c \uc694\ud0c0\ub97c\\\ubbf8\ucf54\ud1a0\uc5d0\uac8c \ub9e1\uae30\uace0 \uce74\ubbf8\uc57c\ub294 \ub7a9\uc73c\ub85c \ud5a5\ud55c\ub2e4.",
    "OUTLINE_R_ja.cfg.bin#3": "15\uc2dc. \uc790\uce6d \ud788\uc5b4\ub85c \ub8e8\uc0c1\uce58\u2606\ub9e8\uc740\\\uc5f0\uc778 \uce58\ub9ac\ucf54\uc640 \ub370\uc774\ud2b8\ub97c \uc55e\ub450\uace0 \uc788\uc5c8\ub2e4. \ubb34\uc9c1\\\uc778 \ub8e8\uc0c1\uce58\u2606\ub9e8\uc740 \ubd80\ubaa8\uc758 \uc1a1\uae08\uc73c\ub85c \uc0dd\ud65c\\\ud588\uc9c0\ub9cc 30\uc138 \uc0dd\uc77c\uc744 \uacc4\uae30\ub85c \ub04a\uacbc\ub2e4.\\\uc218\uc911\uc758 \ud604\uae08\uc740 \uace0\uc791 152\uc5d4.\\\uadf8\ub798\ub3c4 \ub370\uc774\ud2b8\ub97c \ud5a5\ud574 \uac04\ub2e4.",
    "OUTLINE_R_ja.cfg.bin#4": "\ud558\uc9c0\ub9cc \uc774\ubc88\uc5d0\ub294 \uce58\ub9ac\ucf54\uc5d0\uac8c \uac11\uc790\uae30 \uc774\ubcc4\uc744 \ud1b5\ubcf4\ubc1b\ub294\ub2e4.\\5\ub144\uac04 \uc0ac\uadc0\uc5c8\ub294\ub370 \uacc4\uc18d \uc77c\ud558\uc9c0 \uc54a\uc544 \uc7a5\ub798\\\uac00 \ubd88\uc548\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \ud558\uc9c0\ub9cc \ub8e8\uc0c1\uce58\u2606\ub9e8\\\uc740 \uce58\ub9ac\ucf54\uac00 \ub5a0\ub09c \uc774\uc720\uac00 \uc545\uc758 \ube44\ubc00 \uacb0\uc0ac\\\uac00 \uc138\ub1cc\ud588\uae30 \ub54c\ubb38\uc774\ub77c\uace0 \ubbff\uace0, \ud788\uc5b4\ub85c \ub3d9\ub8cc\\\ub4e4\uc5d0\uac8c \ub418\ucc3e\uc744 \ubc29\ubc95\uc744 \uc0c1\ub2f4\ud558\ub7ec \uac04\ub2e4.",
    "OUTLINE_R_ja.cfg.bin#5": "16\uc2dc. \ud788\uc5b4\ub85c \ub3d9\ub8cc\uc774\uc790 \ubb34\uc9c1\uc778 \ucf54\uc774\ubb34\ub77c\uc640 \ud558\uc57c\ubbf8\\\uc5d0\uac8c \uc0c1\ub2f4\ud55c \ub8e8\uc0c1\uce58\u2606\ub9e8\uc740 \ucde8\uc5c5\uc744 \uacb0\uc2ec\ud55c\ub2e4.\\\uc5f0\uc608 \uc0ac\ubb34\uc18c\uc758 \uba74\uc811\uc744 \ubcf4\uae30\ub85c \ud55c\ub2e4. \uba74\uc811 \ud6c4,\\\uc5f0\uc608 \uc0ac\ubb34\uc18c \uac74\ubb3c\uc5d0\uc11c \uc2a4\uc988\uce74\uc640\ub77c\ub294 \ubcf4\uceec \ud2b8\ub808\uc774\\\ub108 \ub0a8\uc790\uc640 \ub2e4\uc815\ud55c \ubaa8\uc2b5\uc758 \uce58\ub9ac\ucf54\ub97c \ub9cc\ub098\uace0 \ub8e8\uc0c1\uce58\u2606\ub9e8\uc740\\\ucda9\uaca9\uc744 \ubc1b\ub294\ub2e4.",
    "OUTLINE_R_ja.cfg.bin#6": "\ub8e8\uc0c1\uce58\u2606\ub9e8\uc740 \uce58\ub9ac\ucf54\uc640 \ud568\uaed8 \uc788\ub358 \uc2a4\uc988\uce74\uc640\uac00 \ub9ce\uc740\\\uc5ec\uc131\uc744 \uc18d\uc5ec \uc654\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \uc81c\uc7ac\ud558\ub824 \ud55c\ub2e4. \ud558\uc9c0\ub9cc\\\uce58\ub9ac\ucf54\ub294 \uadf8\ub7f0 \ub8e8\uc0c1\uce58\u2606\ub9e8\uc744 \ub098\ubb34\ub77c\uba70 \uc2a4\uc988\uce74\uc640\uc640 \ub5a0\ub09c\ub2e4.\\\uae4a\uc774 \uc0c1\ucc98 \uc785\uc740 \ub8e8\uc0c1\uce58\u2606\ub9e8. \uadf8\uc758 \ub208\uc55e\\\uc5d0\uc11c \uc6b0\uc8fc \uc5d8\ub9ac\ubca0\uc774\ud130\uac00 \uac11\uc790\uae30 \ud3ed\ubc1c\ud55c\ub2e4.",
    "OUTLINE_R_ja.cfg.bin#7": "17\uc2dc. \ub8e8\uc0c1\uce58\u2606\ub9e8\uc740 \uc5f0\uc608 \uc0ac\ubb34\uc18c \uac74\ubb3c\\\uc5d0\uc11c \uae30\uc808\ud55c \uce58\ub9ac\ucf54\ub97c \uad6c\ud55c\ub2e4. \uadf8 \ud6c4 \uac70\ub9ac\uc5d0\uc11c\\\ub2e4\uce5c \ubbf8\ucf54\ud1a0\ub97c \uad6c\ud558\uc790 \ud14c\ub7ec\ub9ac\uc2a4\ud2b8 \ube45\\\ud578\ub4dc\uac00 \ub41c \uc61b \uce5c\uad6c \ud63c\ub9c8\uac00 \ubbf8\ucf54\ud1a0\ub97c \ub0b4\ub193\uc73c\\\ub77c\uace0 \ub2e4\uadf8\uce5c\ub2e4. \ub8e8\uc0c1\uce58\u2606\ub9e8\uc758 \uce5c\uad6c \ub098\ud30c\\\ub294 \ub450 \uc0ac\ub78c\uc744 \ub3c4\ub9dd\uce58\uac8c \ud558\uace0 \uc2f8\uc6c0\uc744 \uac78\uc9c0\ub9cc \ud328\ubc30\ud55c\ub2e4.",
    "OUTLINE_R_ja.cfg.bin#8": "\ubbf8\ucf54\ud1a0\ub97c \uc26c\uac8c \ud55c \ub8e8\uc0c1\uce58\u2606\ub9e8 \uc55e\uc5d0 \uce58\ub9ac\ucf54\\\uac00 \ub098\ud0c0\ub09c\ub2e4. \ud654\ud574\ud55c \uac83\ub3c4 \uc7a0\uc2dc,\\\uce58\ub9ac\ucf54\ub294 \ube45 \ud578\ub4dc\uc5d0\uac8c \ubaa9\uc774 \uc878\ub824 \uc6c0\uc9c1\uc774\\\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc808\ub9dd\ud558\ub294 \ub8e8\uc0c1\uce58\u2606\ub9e8 \uc55e\uc5d0\\\ub0a8\uaca8\uc9c4 \ubbf8\ucf54\ud1a0\uc758 \uba54\ubaa8. \uac70\uae30\uc5d0\ub294 \ub8e8\uc0c1\uce58\u2606\\\ub9e8\uc774 \uc2dc\uac04\uc5ec\ud589\uc790\ub77c\uace0 \uc4f0\uc5ec \uc788\uc5c8\ub2e4.",
    "OUTLINE_R_ja.cfg.bin#9": "18\uc2dc. \ub098\ud30c\uc640 \uce58\ub9ac\ucf54\ub97c \uc783\uace0 \uc808\ub9dd\ud558\ub294 \ub8e8\uc0c1\uce58\\\u2606\ub9e8. \uace0\ub4f1\ud559\uad50 \uc2dc\uc808\uc758 \uce5c\uad6c \ud0c0\ub2e4\ub178\uc640 \ub178\uc219\uc790 \ud0c0\ub098\\\uce74\uc758 \uc751\uc6d0\uc73c\ub85c \ub2e4\uc2dc \uc77c\uc5b4\ub098 \ud558\uc218\ub3c4\ub97c\\\ud1b5\ud574 \ub7a9\uc73c\ub85c \ud5a5\ud55c\ub2e4. \ub7a9 \uc785\uad6c\uc5d0\uc11c \ud0c0\ub098\uce74\\\ub294 \ub8e8\uc0c1\uce58\u2606\ub9e8 \uc77c\ud589\uc744 \ud1b5\uacfc\uc2dc\ud0a4\uae30 \uc704\ud574 \uac10\uc2dc\\\uc790 \uc55e\uc5d0 \ub098\uc11c \ud76c\uc0dd\ub418\uace0 \ub9cc\ub2e4.",
    "OUTLINE_R_ja.cfg.bin#10": "\uac15\ub2f9\uc5d0\uc11c\ub294 \ube45 \ud578\ub4dc\uac00 \ubbf8\ucf54\ud1a0\ub97c \uc8fd\uc774\ub824 \ud558\uace0\\\uc788\uc5c8\ub2e4. \ub8e8\uc0c1\uce58\u2606\ub9e8\uacfc \ube45 \ud578\ub4dc\\\uc758 \uaca9\ud22c\uac00 \uc2dc\uc791\ub41c\ub2e4. \ub2e4\uccd0\uc11c \ud3ec\uae30\ud558\ub824\ub358 \uadf8\ub54c,\\\ucf54\uc774\ubb34\ub77c, \ud558\uc57c\ubbf8, \uce58\ub9ac\ucf54, \ub098\ud30c\uac00 \ub098\ud0c0\ub09c\ub2e4. \ube45\\\ud578\ub4dc\ub294 \uc544\ubb34\ub3c4 \uc8fd\uc774\uc9c0 \uc54a\uc558\ub2e4. \ub8e8\uc0c1\uce58\\\u2606\ub9e8\uc740 \ub3d9\ub8cc\ub4e4\uc758 \uc751\uc6d0\uc744 \ubc1b\uc544 \uc2f8\uc6c0\uc5d0\uc11c \uc774\uae34\ub2e4.",
    "OUTLINE_S_ja.cfg.bin#3": "15\uc2dc. \ubb3c\ub9ac\ud559\uc790 \uc2e0\ub3c4\ub294 \ud0c0\uc784\uba38\uc2e0 \uac1c\ubc1c\\\uc0ac\uae30\ub97c \ubc8c\uc778 \ud0d3\uc5d0 \ud22c\uc790\uc790 \uc5d4\uc870\uc5d0\uac8c \ubd99\uc7a1\ud600\\\ub2f9\uc7a5\uc774\ub77c\ub3c4 \uc8fd\uc744 \ucc98\uc9c0\uc600\ub2e4. \ud558\uc9c0\ub9cc \uc790\uc2e0\uc740 \uace7 \uad6c\ucd9c\ub420 \uac70\ub77c\uba70 \ud0dc\uc5f0\ud55c \uc2e0\ub3c4.\\\uadf8\ub54c \ub538 \ubbf8\ucf54\ud1a0\uac00 \uc0ac\uc774\ub80c\uc744 \ub4e4\uace0\\\ub098\ud0c0\ub098 \uc5d4\uc870 \uc77c\ud589\uc740 \ub3c4\uc8fc\ud55c\ub2e4. \uc608\uace0\ub300\ub85c\\\uad6c\ucd9c\ub41c\ub2e4.",
    "OUTLINE_S_ja.cfg.bin#4": "\uadf8 \ud2c8\uc5d0 \ud0c8\ucd9c\ud558\ub294 \uc2e0\ub3c4\uc640 \ubbf8\ucf54\ud1a0\uc600\uc9c0\ub9cc,\\\ud0c0\uace0 \uc788\ub358 \uc790\uc804\uac70\uac00 \ud391\ud06c \ub098 \ub2e4\uc2dc \uc5d4\uc870\\\uc5d0\uac8c \ubd99\uc7a1\ud788\uace0 \ub9cc\ub2e4. \uc5d4\uc870\ub294 \ubbf8\ucf54\ud1a0\ub97c \uc778\uc9c8\ub85c\\\uc0bc\uc544 17\uc2dc\uae4c\uc9c0 \ub3c8\uc744 \ub9c8\ub828\ud558\ub77c\uace0 \uba85\ub839\ud55c\ub2e4.\\\uc2e0\ub3c4\ub294 \uc54c\uaca0\ub2e4\uace0 \uc751\ud558\uba74\uc11c\ub3c4 \uc790\uc2e0\uc758 \uc2e4\ud5d8\uc744\\\uc6b0\uc120\ud574 \uc5f0\uad6c\uc18c\ub85c \ud5a5\ud574 \ubc84\ub9b0\ub2e4.",
    "OUTLINE_S_ja.cfg.bin#5": "16\uc2dc. \uc5f0\uad6c\uc18c\ub85c \ub3cc\uc544\uc628 \uc2e0\ub3c4\uc5d0\uac8c \uc870\uc218 \uc2dc\ub178\ud558\ub77c\\\ub294 \ubbf8\ucf54\ud1a0\ub97c \uad6c\ud558\ub77c\uace0 \uc124\ub4dd\ud55c\ub2e4. \uc2e0\ub3c4\ub3c4 \ubc1b\uc544\\\ub4e4\uc778\ub2e4. \ubc29\uc1a1\uad6d\uc5d0\uc11c \ud6c4\ubc30 \ud0c0\uce74\uc774\ub3c4\ub97c \ud611\ubc15\ud574 \ub3c8\uc744 \ub0b4\uac8c \ud558\ub824 \ud558\uc9c0\ub9cc \uacbd\ucc30\uacfc \ud14c\ub7ec\ub9ac\uc2a4\ud2b8\\\uc758 \ubc00\ud68c \uc774\uc57c\uae30\ub97c \ub4e3\uace0 \uc0dd\uac01\uc744 \ubc14\uafbc\ub2e4. \ud14c\ub7ec \uc870\uc9c1\\\uc5d0 \ub0b4\ud1b5\ud558\ub294 \uc0ac\uc640\ud0a4\uc57c\ub9d0\ub85c \uc5d4\uc870\uac00 \uc6d0\ub9dd\ud558\ub294 \uc0c1\ub300\\\uc600\ub2e4.\\n",
    "OUTLINE_S_ja.cfg.bin#6": "\ubc00\ud68c \ud604\uc7a5\uc744 \ud3ec\ucc29\ud55c \uc601\uc0c1\uc774 \ud3d0\uae30\ub410\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc548\\\uc2e0\ub3c4\ub294 \uc601\uc0c1\uc774 \ub4e0 \uba54\ubaa8\ub9ac \uce74\ub4dc\ub97c \ud6d4\uccd0 \uc5d4\uc870\uc640\uc758\\\ud611\uc0c1\uc5d0 \uc4f0\uae30\ub85c \ud55c\ub2e4. \ubbf8\ucf54\ud1a0\ub97c \uad6c\ud558\uae30 \uc704\ud574 \ucc28\ub85c \uc5d4\uc870\uac00 \uae30\ub2e4\ub9ac\ub294 \ucc3d\uace0\ub85c\\\ud5a5\ud558\ub358 \ub3c4\uc911, \uc2e0\ub3c4 \uc77c\ud589\uc740 \uc6b0\uc8fc \uc5d8\ub9ac\ubca0\uc774\ud130\\\uac00 \ud14c\ub7ec\ub85c \ud3ed\ud30c\ub418\ub294 \uac83\uc744 \ubaa9\uaca9\ud55c\ub2e4.",
    "OUTLINE_S_ja.cfg.bin#7": "17\uc2dc. \ucc3d\uace0\uc5d0 \uc628 \uc2e0\ub3c4. \uc2e0\ub3c4\ub294 \ud14c\\\ub808\ube44\uc804 \ubc29\uc1a1\uad6d\uc5d0\uc11c \uc190\uc5d0 \ub123\uc740 \uc601\uc0c1\uacfc \uc790\uc2e0\uc758 \ubaa9\uc228\uc744 \ub2f4\ubcf4\ub85c,\\\uc5d4\uc870\uc5d0\uac8c \ub3c4\ubc15 \uc2b9\ubd80\ub97c \uac74\ub2e4. \uce74\ub4dc \uac8c\\\uc784\uc5d0\uc11c \uc2e0\ub3c4\uac00 \uc2b9\ub9ac\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub798\ub3c4 \ubbf8\ucf54\ud1a0\\\ub294 \ud480\ub824\ub098\uc9c0 \uc54a\uace0, \uc2e0\ub3c4\uc758 \uc81c\uc548\uc73c\ub85c \uc5d4\uc870\uc758 \uc0dd\uac01\uc744\\3\ubc88 \ub9de\ud788\ub294 \ub3c4\ubc15\uc744 \ud558\uac8c \ub41c\ub2e4.",
    "OUTLINE_S_ja.cfg.bin#8": "\uc2e0\ub3c4\ub294 \uc5d4\uc870\uc758 \uc0dd\uac01\uc744 3\ud68c \uc5f0\uc18d \ub9de\ud600 \uc2b9\ub9ac\ud55c\ub2e4.\\n\uc5d4\uc870\ub294 \uc2e0\ub3c4 \uc77c\ud589\uc758 \uc55e\uae38\uc744 \ub9c9\uc9c0\ub9cc, \uc2dc\ub178\ud558\ub77c\uc758\\\uae30\uc9c0\ub85c \ud0c8\ucd9c\uc5d0 \uc131\uacf5\ud55c\ub2e4. \ucc28 \uc548\uc5d0\uc11c \ub3c4\ubc15\uc758 \ub2f5\uc744\\\uc5b4\ub5bb\uac8c \uc54c\uc558\ub294\uc9c0 \uc9c8\ubb38\ubc1b\uc790 \uc2e0\ub3c4\ub294 \ubbf8\ucf54\ud1a0\\\uc5d0\uac8c \ub4e4\uc5c8\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uadf8\ub9ac\uace0 \ubbf8\ucf54\ud1a0\\\uc5d0\uac8c \u300e\ub108\ub294 \uc2dc\uac04\uc5ec\ud589\uc790\ub2e4\u300f\ub77c\uace0 \ub9d0\ud55c\ub2e4.",
    "OUTLINE_S_ja.cfg.bin#9": "18\uc2dc. \uc2e0\ub3c4\ub294 \uc2dc\ub178\ud558\ub77c\uc758 \ubd80\ud0c1\uc73c\ub85c \uc2e0\ub3c4\uc758 \uc5f0\uad6c\uc18c\\\uc5d0 \ub4e4\ub974\uae30\ub85c \ud55c\ub2e4. \uadf8\uacf3\uc5d0 \uc5d4\uc870\uac00 \ub098\ud0c0\ub098 \ud0c0\uc784\\\uba38\uc2e0 \uac1c\ubc1c\uc744 \uac04\uccad\ud55c\ub2e4. \ud558\uc9c0\ub9cc \uc5d4\uc870\uc758 \ubd80\ud558 \uba54\uc790\ud0a4\uac00\\\uc5d4\uc870\ub97c \ucc0c\ub978\ub2e4. \uc5d4\uc870\ub294 \uc8fd\uc740 \uac00\uc871\uc744 \uadf8\ub9ac\uc6cc\\\ud558\uba70 \uc228\uc744 \uac70\ub454\ub2e4. \uc2e0\ub3c4\uc758 \uc2e0\ubcd1\uc744 \ub118\uae30\ub294 \uac70\ub798\uac00 \uc131\ub9bd\ud588\\\ub2e4\ub294 \uba54\uc790\ud0a4. \uadf8 \ub9e4\uc218\uc790\ub294 \uc2dc\ub178\ud558\ub77c\uc600\ub2e4.",
    "OUTLINE_S_ja.cfg.bin#10": "\uc2dc\ub178\ud558\ub77c\ub294 \uc2a4\ucf08\ub808\ud1a4\uc758 \ub3d9\ub8cc\ub85c, \uc2e0\ub3c4\uac00 \uacc4\ud68d\uc744\\\ubc29\ud574\ud558\uc9c0 \ubabb\ud558\ub3c4\ub85d \uac10\uc2dc\ud558\uace0 \uc788\uc5c8\ub2e4. \uc5f0\uad6c\uc18c\\\uc5d0\uc11c \ubc1c\uc774 \ubb36\uc5ec \uc788\ub358 \uc2e0\ub3c4\uc600\uc9c0\ub9cc, \uc218\uc218\uaed8\ub07c\uc758 \uc5ec\\\uc790\uc5d0\uac8c \uad6c\ucd9c\ub41c\ub2e4. \uc2e0\ub3c4\ub294 \uc218\uc218\uaed8\ub07c\uc758 \uc5ec\uc790\uc5d0\uac8c \uc5b4\ub5a4 \uc218\uc2dd\\\uc744 \ubc30\uc6b4\ub2e4. \uc218\uc2dd\uc744 \ud47c \uc2e0\ub3c4\ub294 \ud63c\uc790\\\ub7a9\uc73c\ub85c \ud5a5\ud55c\ub2e4.",
})

