def main() -> None:
    for filename in sorted(set(TRANSLATIONS) | set(OVERRIDES)):
        mapping = TRANSLATIONS.get(filename, {})
        path = UI / filename
        data = json.loads(path.read_text(encoding="utf-8"))
        entries = data.get("entries", data if isinstance(data, list) else [])
        overrides = OVERRIDES.get(filename, {})
        seen: set[str] = set()
        for entry in entries:
            entry_id = entry["id"]
            if entry_id in mapping or entry_id in overrides:
                value = overrides[entry_id] if entry_id in overrides else mapping[entry_id]
                if filename == "choice.json":
                    value = value.replace("\\n", "\n")
                if filename == "outline.json":
                    value = re.sub(r"\\(?!n)", r"\\n", value)
                for old, new in TEXT_REPLACEMENTS:
                    value = value.replace(old, new)
                entry["ko"] = value.replace("·", "・").replace("\u200b", "")
                seen.add(entry_id)
        missing = (set(mapping) | set(overrides)) - seen
        if missing:
            raise RuntimeError(f"{filename}: unknown ids: {sorted(missing)}")
        path.write_text(json.dumps(data, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
        print(f"{filename}: translated {len(seen)} entries")


if __name__ == "__main__":
    main()
